// ==========================================
// ★ K 의 방 — B등급 직업 갈림길 · 파괴
// 전사 · 화염술사 · 권사 · 폭파공 · 대검사
// 파괴: 잠긴 것을 부수고, 쫓아오는 것을 끊는다 — 비 오는 밤, 시간이 없다
// ==========================================

// ------------------------------------------
// 전사 · 무력
// ------------------------------------------
kJob('warrior', 'B', [

{ at:'B', t:'빗물 — 도는 자루',
  x:`비가 그치지 않는다. 지붕이 있는 데도 어디선가 샌다.<br><br>
    무기 자루가 젖었다. 감아 둔 천이 물을 먹어 손 안에서 돈다.<br>
    전사는 안다. 자루가 한 번 돌면 그날 싸움도 한 번 진다.<br><br>
    멀리서 발소리가 난다. 서두르지 않는 발소리다. 천을 다시 감을 시간은 있을지도 모른다.`,
  o:[
    { l:'① 젖은 천을 풀고 맨 나무를 쥔다.', k:'fix', dc:19,
      ok:`젖은 천을 풀어 주머니에 넣었다. 맨 나무가 손바닥에 닿는다.<br><br>나무는 젖어도 살에 붙는다. 천보다 낫다. 굳은살이 자루 결에 맞물린다.<br><br>발소리가 모퉁이에서 멈췄다. 이쪽 손이 다 쥐어진 뒤였다.`,
      ng:`푸는데 매듭이 물에 불어 안 풀린다.<br><br>손톱으로 뜯다가 손톱이 들렸다. 그사이 발소리가 가까워졌다.<br>반쯤 풀린 천이 자루에서 덜렁거린다. 쥘 때마다 미끄러진다.`,
      win:{ exp:14, dream:1 }, lose:{ hp:-20, mind:-12 } },
    { l:'② 쥐는 법을 바꾼다 — 손가락 사이에 자루를 건다.', k:'break', dc:20, wake:1,
      ok:`엄지로 감싸지 않았다. 검지와 중지 사이에 자루를 걸고 새끼손가락으로 잠갔다.<br><br>휘둘러 봤다. 손이 젖어도 자루가 안 돈다. 돌 데가 없다. 손가락 뼈가 자루를 물고 있다.<br><br>몇 해를 같은 법으로 쥐었다. 비 오는 밤 하나가 그 법을 고쳤다. 손이 새 법을 벌써 제 것처럼 쥔다.`,
      ng:`바꿔 쥐고 한 번 휘두르는데 손가락이 꺾였다.<br><br>자루가 손가락 사이에서 비틀린 것이다. 무기가 벽에 부딪혀 소리가 났다. 크게.<br>발소리가 멈췄다. 그리고 이쪽으로 빨라졌다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 사슬 감긴 셔터',
  x:`등 뒤로 셔터가 내려왔다. 밖에서 사슬 감는 소리가 났다. 세 바퀴.<br><br>
    셔터 밑단과 바닥 사이로 빗물이 들어온다. 손가락 하나 들어갈 틈이다.<br>
    무기를 쥐는 사람은 막힌 것을 보면 먼저 무게를 잰다. 셔터 한 장, 사슬 한 줄, 밖에서 그걸 감은 사람 하나.<br><br>
    창고 안쪽 어둠에서 대걸레가 바닥을 미는 소리가 난다. 천천히. 이쪽으로.`,
  o:[
    { l:'① 무력을 쓴다 — 셔터 밑단을 들어 올린다.', k:'steady', dc:20, cost:{ might:25 },
      ok:`밑단에 손가락을 넣고 무릎을 굽혔다. 무력을 허리에서 어깨로 올렸다.<br><br>셔터가 한 뼘 들렸다. 밖의 사슬이 팽팽하게 운다. 한 뼘이면 사람이 기어 나간다. 동료들이 하나씩 빠져나갔다.<br><br>마지막으로 몸을 굴렸다. 놓은 셔터가 바닥을 쳤다. 안쪽 대걸레 소리가 그 소리에 멈췄다.`,
      ng:`한 뼘이 들리다 반 뼘에서 걸렸다. 밖에서 사슬이 아니라 손이 누르고 있다.<br><br>셔터가 도로 내려와 손가락이 밑단에 끼었다. 빼는 데 숨 열을 참았다.<br>밖에서 우산 접는 소리가 났다. 발소리가 멀어진다. 서두르지 않는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12, might:-5 } },
    { l:'② 셔터 이음매를 친다.', k:'break', dc:21,
      ok:`셔터는 철판 여러 장을 이은 것이다. 이음매 하나가 녹슬어 벌어져 있다.<br><br>거기만 쳤다. 두 번. 철판 한 장이 바깥으로 접혔다. 비가 얼굴에 들이친다.<br><br>소리가 컸다. 안쪽 대걸레 소리가 멈췄다. 그리고 다시 시작됐다. 아까보다 가까이서.`,
      ng:`쳤는데 철판이 울리기만 한다. 창고 전체가 종처럼 운다.<br><br>무기가 튕겨 손목이 꺾였다. 셔터는 그대로다.<br>울림이 가라앉기도 전에 안쪽에서 장화 소리가 났다. 물웅덩이를 하나씩 밟고 온다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-26, spirit:-12 } },
    { l:'③ 셔터를 두고 물이 빠지는 데를 찾는다.', k:'sense', dc:20,
      ok:`빗물이 어디로 흐르는지 봤다. 바닥 물이 한쪽으로 기운다. 구석 배수구다.<br><br>쇠뚜껑 틈으로 바람이 올라온다. 바다 냄새다. 뚜껑을 들자 사람 하나 들어갈 관이 나 있다.<br><br>무기를 등에 붙이고 들어갔다. 셔터는 두드릴 필요가 없었다. 두드렸으면 안쪽 것이 왔다.`,
      ng:`물 흐르는 쪽을 따라갔는데 물이 거꾸로 흐른다. 바깥에서 안으로.<br><br>빠지는 구멍이 아니라 들어오는 구멍이다. 밀물 때다. 발목이 젖고 무릎이 젖는다.<br>되돌아오다 미끄러져 철제 선반에 옆구리를 찧었다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-20, mind:-12 } }
  ] },

{ at:'B2', t:'7층 — 손목의 가죽 띠',
  x:`눈을 뜨니 손목이 침대 난간에 묶여 있다. 가죽 띠다. 버클이 손 닿지 않는 쪽에 있다.<br><br>
    옆 침대 사람도 묶였다. 자고 있다. 숨이 고르다. 너무 고르다.<br>
    복도 시계가 정각 오 분 전이다. 정각이면 점검이 돈다. 묶인 사람은 묶인 채로 세어진다.<br><br>
    무기는 침대 밑에 있다. 누가 친절하게 두고 갔다.`,
  o:[
    { l:'① 무력을 쓴다 — 가죽 띠를 끊는다.', k:'break', dc:20, cost:{ might:22 },
      ok:`주먹을 쥐고 팔을 몸 쪽으로 당겼다. 무력을 손목에 몰았다.<br><br>가죽이 늘어난다. 늘어나다 버클 구멍이 찢어졌다. 한쪽이 풀리자 다른 쪽 버클은 손으로 풀었다.<br><br>침대 밑에서 무기를 꺼냈다. 복도에서 딸깍 소리가 시작됐다. 이 방까지 세 칸.`,
      ng:`가죽이 늘어나기만 하고 안 찢어진다. 오래 쓴 띠다. 많은 사람이 이렇게 당겼다.<br><br>손목 살갗이 벗겨졌다. 피가 띠에 스민다.<br>딸깍. 문이 열렸다. 간호사가 이쪽 손목을 보고 띠 하나를 더 가져와 감았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14, might:-5 } },
    { l:'② 손을 접어 빼낸다.', k:'evade', dc:20,
      ok:`엄지를 손바닥 안으로 접었다. 손을 최대한 좁게 하고 천천히 당겼다.<br><br>엄지 뿌리가 띠에 걸린다. 거기서 숨을 내쉬고 한 번에 뺐다. 살갗이 쓸리고 빠졌다.<br><br>무기를 쥐는 손은 크다. 작게 접어 본 적은 없다. 오늘 접었다. 다른 손은 쉽게 빠졌다.`,
      ng:`엄지 뿌리에서 걸렸다. 더 당기자 띠가 더 조인다. 그렇게 만든 띠다.<br><br>손끝이 하얘진다. 감각이 없어진다.<br>딸깍 소리가 문 앞에서 멈췄다. 숨을 고르게 쉬었다. 옆 침대 사람처럼. 정각이 지나도록 손목이 저리다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'9호차 — 휘두를 수 없는 통로',
  x:`열차 통로는 어깨 하나 너비다. 양옆은 좌석, 위는 선반.<br><br>
    무기를 크게 들면 선반에 걸린다. 옆으로 그으면 등받이에 박힌다. 휘두를 자리가 없다.<br>
    뒤에서 누가 따라온다. 아까 맨 뒷자리에서 자던 사람이다. 지금은 다른 얼굴이다.<br><br>
    덜컹. 이음매를 넘을 때마다 그 사람이 한 걸음씩 붙는다.`,
  o:[
    { l:'① 자루를 짧게 쥐고 찌른다.', k:'break', dc:21, wake:1,
      ok:`자루 끝이 아니라 날 바로 밑을 쥐었다. 무기가 팔뚝 길이로 줄었다.<br><br>그 사람이 붙는 순간 팔꿈치를 뒤로 빼고 앞으로 밀었다. 휘두르지 않았다. 밀었다. 그 사람이 좌석 사이로 접혔다.<br><br>무기는 길게 쓰라고 긴 줄 알았다. 짧게 쥐면 다른 무기가 된다. 손이 그 길이를 금방 외웠다. 좁은 데서는 이 길이가 제일 빠르다.`,
      ng:`짧게 쥐었는데 날이 손에 너무 가깝다. 찌르는 순간 열차가 덜컹했다.<br><br>날이 빗나가 등받이에 박혔다. 그 사람 손이 이쪽 손목을 잡는다. 차다.<br>뿌리치고 나니 손목에 손가락 자국이 남았다. 얼굴이 또 바뀌어 있었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, spirit:-14 } },
    { l:'② 빈 좌석에 들어가 먼저 보낸다.', k:'steady', dc:20,
      ok:`빈 좌석에 들어가 창에 등을 붙였다. 무기는 무릎 위에 눕혔다.<br><br>그 사람이 지나간다. 이쪽을 안 본다. 지나가면서 창에 비친 이쪽 얼굴을 본다. 오래.<br><br>통로 끝 문이 닫혔다. 이제 그 사람이 앞에 있다. 앞에 있는 것은 적어도 보인다.`,
      ng:`등을 붙였는데 창이 차다. 비가 유리 너머에서 등을 두드린다.<br><br>그 사람이 지나가다 멈췄다. 옆 좌석에 앉았다. 아무 말도 안 한다.<br>방송이 다음 역을 다 부를 때까지 그대로 앉아 있었다. 무기 쥔 손에 쥐가 났다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'통로 — 박자를 맞추는 발소리',
  x:`뒤에서 걸음이 따라온다. 이쪽이 걸으면 걷고 서면 선다.<br><br>
    맨 뒤에 선 사람이 뒤를 맡는다. 무기를 든 사람이 늘 맨 뒤에 선다.<br>
    걸음 박자가 이쪽과 똑같다. 따라 하는 게 아니라 맞추고 있다. 같은 박자면 소리가 하나로 들린다.<br><br>
    앞사람들은 발소리가 하나 더 있는 줄 모른다.`,
  o:[
    { l:'① 돌아서서 기다린다.', k:'break', dc:21,
      doom:{ title:'박자를 맞추던 것', what:'뒤에서 목이 졸렸습니다', dc:17, sec:55,
        text:`돌아서서 무기를 들었다. 어둠 속에 아무것도 없다.<br><br>박자가 끊겼다. 이쪽이 섰으니까. 그런데 발소리가 하나 남았다. 등 뒤에서. 앞사람들 쪽에서.<br>돌아서는 순간 맨 뒤가 맨 앞이 됐다.<br><br>목에 가는 것이 감겼다. 철사다. 젖었다.`,
        dieText:`맨 뒤에 선 사람이 뒤를 맡는다.<br><br>그날 맨 뒤는 한 번 돌아섰다. 돌아선 동안 뒤가 앞이 됐다.<br>일행은 한 사람 적은 발소리로 걸었다. 박자는 여전히 하나였다.` },
      ok:`돌아섰다. 무기를 낮게. 숨을 멈췄다.<br><br>박자가 끊기자 어둠 속에서 한 걸음이 늦게 떨어졌다. 맞추던 것이 맞출 데를 잃었다. 거기로 쳤다. 무언가 바닥에 무릎을 꿇는다.<br><br>얼굴은 보지 않았다. 다시 돌아서 걸었다. 이번엔 발소리가 하나다. 진짜 하나.`,
      win:{ exp:22, dream:3 } },
    { l:'② 걸음을 일부러 흐트러뜨린다.', k:'sense', dc:20,
      ok:`한 걸음은 길게, 한 걸음은 짧게. 일부러 절름거렸다.<br><br>뒤의 걸음이 따라오다 엇나간다. 둘로 들린다. 앞사람이 돌아본다. 이제 다들 안다.<br><br>모두 돌아서자 뒤의 걸음이 멎었다. 그 뒤로 다시 들리지 않았다. 들키면 물러나는 것이다. 이번에는.`,
      ng:`절름거리는 걸음도 그대로 따라온다. 길게, 짧게. 똑같이.<br><br>이쪽 걸음을 이쪽보다 잘 안다. 등이 젖는다. 비가 아니다.<br>앞사람을 부르려고 입을 여는데 뒤에서 숨이 귓바퀴에 닿았다. 그리고 멀어졌다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B1', t:'부두 — 불 끈 지게차',
  x:`컨테이너 사이 골목이다. 비가 철판을 두드린다.<br><br>
    골목 끝에 지게차가 서 있다. 불이 꺼졌다. 운전석에 그림자가 있다. 우비 모자를 썼다.<br>
    지게차 날이 사람 허리 높이로 올라와 있다. 젖어서 번들거린다.<br><br>
    엔진이 걸렸다. 불은 끈 채로 온다.`,
  o:[
    { l:'① 날 밑으로 들어가 운전석에 뛰어오른다.', k:'break', dc:21,
      ok:`달려오는 날 밑으로 몸을 숙였다. 쇠가 머리 위를 지난다.<br><br>손잡이를 잡고 운전석에 올라탔다. 얼굴은 모자 그늘에 있다. 무기 자루로 손목을 쳤다. 손이 핸들에서 떨어졌다.<br><br>지게차가 컨테이너에 박혀 멈췄다. 우비가 빗속으로 뛰어간다. 소리 하나 안 냈다.`,
      ng:`숙이는데 날이 내려왔다. 어깨를 긁고 지나갔다.<br><br>손잡이를 놓쳤다. 젖은 바닥에 굴렀다. 바퀴가 손가락 한 마디 옆을 지나갔다.<br>지게차가 돌아선다. 다시 온다. 컨테이너 틈으로 기어들었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'② 날 끝을 정면으로 받는다.', k:'steady', dc:22,
      ok:`무기를 가로로 들고 날 끝을 받았다. 발이 젖은 바닥에서 밀린다. 두 뼘. 세 뼘.<br><br>등에 컨테이너가 닿았다. 더 밀리지 않는다. 바퀴가 헛돈다. 물보라가 인다.<br>운전석이 기어를 바꾸는 사이 옆으로 빠졌다. 날이 컨테이너에 박혔다.<br><br>무기를 봤다. 휘었다. 쓸 만큼만 휘었다.`,
      ng:`받는 순간 무기가 휘었다. 날이 가슴 앞까지 왔다.<br><br>컨테이너와 날 사이에 끼었다. 숨이 반만 쉬어진다.<br>지게차가 물러난다. 다시 오려고 물러나는 것이다. 그 틈에 기어 나왔다. 갈비뼈 쪽이 이상하다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, mind:-12 } },
    { l:'③ 컨테이너 틈으로 비킨다.', k:'evade', dc:20,
      ok:`컨테이너 둘 사이 틈으로 몸을 넣었다. 무기가 걸린다. 위로 세웠다.<br><br>지게차가 틈 앞을 지나간다. 날이 틈 입구를 긁는다. 불꽃이 빗속에서 튄다.<br><br>지나간 뒤에도 한참 안 나왔다. 엔진 소리가 멀어지고 가까워지고 다시 멀어졌다. 찾고 있다.`,
      ng:`틈에 들어갔는데 무기가 걸려 몸이 반만 들어갔다.<br><br>날이 지나가며 밖에 남은 장화 끝을 찍었다.<br>소리를 삼켰다. 엔진이 멀어진 뒤에야 장화를 벗어 봤다. 발톱 둘이 까맣다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-24, mind:-12 } }
  ] },

{ at:'B2', t:'병실 — 정각, 바짝 선 보호사',
  x:`정각이다. 다들 침대 발치에 섰다. 그렇게 서라고 종이에 적혀 있었다.<br><br>
    계수기를 든 간호사 뒤로 보호사가 따라온다. 키가 문틀만 하다. 소매가 짧아 손목이 다 나왔다. 손목에 이름 대신 숫자가 새겨져 있다.<br>
    보호사가 이쪽 앞에서 멈춘다. 숨이 닿을 만큼 가깝다.<br><br>
    무기를 쥐던 손이 저절로 움찔한다. 보호사가 그 손을 내려다본다.`,
  o:[
    { l:'① 손을 펴고 세어진다.', k:'steady', dc:20,
      ok:`손가락을 하나씩 폈다. 빈손을 허벅지에 붙였다.<br><br>보호사가 한참 내려다보다 고개를 든다. 딸깍. 세어졌다. 둘은 다음 침대로 갔다.<br><br>펴진 손이 떨린다. 안 쥐고 버틴 손이 쥐고 버틴 손보다 힘들다.`,
      ng:`손을 펴는데 새끼손가락이 안 펴진다. 굳었다.<br><br>보호사가 그 손가락을 잡아 폈다. 천천히. 뼈가 소리를 낼 때까지.<br>딸깍. 세어졌다. 손가락은 다음 정각까지 퉁퉁 부어 있었다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 보호사 손목을 먼저 잡는다.', k:'break', dc:21, wake:1,
      ok:`보호사가 손을 뻗는 순간 그 손목을 잡았다. 무기를 쥐듯이.<br><br>손목이 굵다. 그래도 쥐어진다. 엄지가 뼈 사이로 들어간다. 보호사의 손가락이 저절로 펴진다. 쥐고 있던 주사기가 바닥에 떨어졌다.<br>보호사가 물러섰다. 간호사는 아무것도 못 본 얼굴로 계수기를 눌렀다. 딸깍.<br><br>무기를 쥐던 손이 처음으로 사람을 쥐었다. 어디를 쥐면 손이 풀리는지 엄지가 알았다. 쥐는 것도 치는 것이다.`,
      ng:`잡았는데 손목이 젖은 비누처럼 빠져나갔다.<br><br>보호사 손이 이쪽 목덜미를 잡았다. 따끔했다. 주사기다.<br>정각이 지나는 동안 다리에 힘이 안 들어왔다. 침대 난간을 붙들고 섰다. 세어지기는 했다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B3', t:'연결 통로 — 저쪽에서 쥔 손잡이',
  x:`객차와 객차 사이다. 바닥 철판 두 장이 따로 흔들린다. 틈으로 선로가 흘러간다.<br><br>
    앞 칸 문이 안 열린다. 잠긴 게 아니다. 손잡이가 조금씩 움직인다. 저쪽에서 누가 쥐고 있다.<br>
    문 유리는 김이 서려 뿌옇다. 손바닥 자국 하나만 맑다. 저쪽에서 대고 있다.<br><br>
    뒤 칸에서 문 열리는 소리가 난다.`,
  o:[
    { l:'① 흔들림에 맞춰 어깨로 민다.', k:'break', dc:21,
      ok:`어깨를 문에 붙이고 발을 철판 이음매에 걸었다. 열차가 덜컹할 때를 기다렸다.<br><br>덜컹. 그 흔들림에 몸무게를 실었다. 저쪽 손이 놓쳤다. 문이 열리며 앞 칸 바닥에 누가 엉덩방아를 찧는다. 승무원 옷이다. 모자가 굴러간다.<br><br>모자 안쪽에 이름표가 꿰매져 있다. 이름이 넷이다. 셋은 줄이 그어졌다.`,
      ng:`미는 순간 저쪽이 손을 놓았다. 일부러.<br><br>문이 열리며 몸이 앞으로 쏟아졌다. 철판 틈에 발이 빠졌다. 발목 밑으로 선로가 지나간다. 바람이 바짓단을 잡아당긴다.<br>발을 빼는 사이 앞 칸 사람은 사라졌다. 발목이 퍼렇게 부었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 돌아서서 뒤 칸 손잡이를 쥔다.', k:'steady', dc:20,
      ok:`앞은 두고 뒤로 돌았다. 뒤 칸 손잡이를 잡았다. 이번엔 이쪽이 쥐는 쪽이다.<br><br>뒤에서 누가 연다. 안 열린다. 두 번 더 해 보고 그만둔다. 발소리가 멀어진다.<br>돌아보니 앞 칸 문도 열려 있다. 아무도 없다. 유리에 손바닥 자국만 남았다.<br><br>앞뒤에서 동시에 오는 것이 둘이 아니라 하나일 때가 있다.`,
      ng:`뒤 칸 손잡이를 잡았다. 저쪽 힘이 세다. 손잡이가 손 안에서 돈다.<br><br>그사이 앞 칸 문이 열렸다. 무언가 등 뒤로 지나갔다. 옷깃이 스쳤다.<br>두 문이 동시에 닫혔다. 연결 통로에 혼자다. 철판 틈으로 선로가 계속 흘러간다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'숨은 자리 — 떨리는 손',
  x:`벽장 같은 데 숨었다. 다들 숨을 죽였다. 밖으로 무언가 지나간다.<br><br>
    무기 쥔 손이 떨린다. 아까 싸움 뒤로 안 멎는다. 떨리면 날이 벽에 닿는다. 닿으면 소리가 난다.<br>
    싸움이 끝나도 손은 끝난 줄 모른다. 무기를 오래 쥔 사람은 다 안다.<br><br>
    밖의 발소리가 문 앞에서 느려진다.`,
  o:[
    { l:'① 소매를 찢어 손과 자루를 묶는다.', k:'fix', dc:20,
      ok:`소매를 찢어 손등과 자루를 같이 감았다. 이로 매듭을 지었다.<br><br>손은 여전히 떨린다. 이제 무기도 같이 떨린다. 떨림이 하나가 되자 날이 벽에서 떨어진다. 소리가 없다.<br><br>발소리가 문 앞을 지나갔다.`,
      ng:`소매 찢는 소리가 났다. 작게. 여기서는 작은 게 크다.<br><br>발소리가 멈췄다. 문틈으로 그림자가 든다. 한참 머물다 갔다.<br>그사이 손이 더 떨렸다. 묶은 천이 반쯤 풀려 있었다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 떨림이 멎을 때까지 숨을 센다.', k:'steady', dc:21, wake:1,
      ok:`들이쉬며 넷, 멈추고 넷, 내쉬며 여덟. 손을 보지 않고 숨만 셌다.<br><br>세 번째 숨에 손목이 멎었다. 다섯 번째에 손가락이. 일곱 번째에 손 전체가 무기와 같이 가만해졌다.<br><br>밖의 것이 문 앞을 지나갔다. 그다음 숨에 알았다. 이 숨은 싸우기 전에도 쓸 수 있다. 떨림이 오기 전에 미리. 싸움이 끝나는 자리를 몸 안에 하나 만든 셈이다.`,
      ng:`세는데 숫자가 밖의 발소리에 섞였다. 넷이 다섯이 되고 셋이 된다.<br><br>손이 더 떨린다. 날 끝이 벽을 톡 쳤다. 한 번.<br>밖의 것이 멈췄다. 문고리가 반 바퀴 돌았다가 돌아갔다. 왜 돌아갔는지는 모른다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B', t:'길잡이 — 낯선 사람의 등',
  x:`낯선 사람이 하나 끼었다. 나가는 길을 안다고 했다. 외투 깃을 세웠다. 이 비에 젖지 않았다.<br><br>
    그가 앞장선다. 전사는 맨 뒤에서 그의 등을 본다. 등은 거짓말을 잘 못한다.<br>
    그는 모퉁이마다 벽을 짚는다. 짚을 때마다 손이 조금 오래 머문다.<br><br>
    다음 모퉁이가 보인다.`,
  o:[
    { l:'① 거리를 좁혀 그의 손을 본다.', k:'gaze', dc:20,
      ok:`한 걸음 붙었다. 무기를 쥐는 사람의 눈은 손을 본다.<br><br>그가 벽을 짚는다. 손끝에 분필이 있다. 작은 화살표. 우리가 가는 쪽으로.<br>뒤에서 오는 누군가를 위한 표시다. 길을 안내하는 게 아니라 데려다주는 중이다.<br><br>다음 모퉁이에서 화살표를 반대쪽으로 고쳐 그었다. 그는 몰랐다.`,
      ng:`붙었는데 그가 걸음을 늦춰 이쪽 옆으로 섰다.<br><br>웃는다. 이 길이 맞다고. 그 사이 손을 못 봤다.<br>모퉁이 몇 개를 지나서야 벽마다 분필 화살표가 있는 걸 봤다. 전부 우리가 간 쪽이다. 지울 시간은 지났다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 그의 손목을 쳐서 분필을 떨군다.', k:'break', dc:21, wake:1,
      ok:`모퉁이에서 그가 손을 드는 순간 자루로 손목을 쳤다. 날이 아니라 자루로.<br><br>분필이 굴렀다. 그가 돌아선다. 다른 손에 접이칼이 이미 펴져 있다. 그 손이 움직이기 전에 어깨가 먼저 움직였다. 어깨를 봤다. 그래서 칼보다 먼저 막았다.<br><br>그를 벽에 붙여 두고 왔다. 손을 보던 눈이 어깨를 보게 됐다. 어깨가 손보다 반 박자 빠르다. 그 반 박자가 이제 이쪽 것이다.`,
      ng:`손목을 쳤는데 그가 먼저 알았다. 손을 뺐다.<br><br>접이칼이 팔뚝을 긋고 지나갔다. 그가 빗속으로 뛴다. 뛰면서 휘파람을 분다. 멀리서 대답하는 휘파람이 있다.<br>팔뚝을 묶었다. 이제 뒤에서 오는 것이 우리 길을 안다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, spirit:-12 } },
    { l:'③ 앞장서게 두고 모퉁이마다 뒤를 끊는다.', k:'steady', dc:20,
      ok:`그를 앞에 두었다. 대신 모퉁이마다 맨 뒤에서 오래 섰다.<br><br>세 번째 모퉁이에서 뒤가 왔다. 표시를 따라온 것들이다. 길목에 무기를 세우고 선 사람을 보고 멈췄다.<br>멈춘 것들을 두고 물러났다. 그사이 앞의 낯선 사람은 없어졌다. 표시는 거기서 끊겼다.`,
      ng:`뒤를 끊으려 섰는데 앞에서 비명이 났다. 동료의 것이다.<br><br>뛰어가 보니 낯선 사람은 없고 동료가 바닥에 주저앉아 발목을 쥐고 있다. 밀었다고 한다.<br>그사이 뒤가 따라붙었다. 동료를 업고 뛰었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B1', t:'냉동 창고 — 손잡이 없는 문',
  x:`생선 상자가 천장까지 쌓인 냉동 창고다. 숨이 하얗다.<br><br>
    들어오자 뒤에서 문이 닫혔다. 두꺼운 문이다. 안쪽 손잡이가 떨어져 나갔다. 떨어진 자리가 새것이다.<br>
    벽 온도계 바늘이 천천히 내려간다. 밖에서 누가 돌리고 있다.<br><br>
    상자 틈으로 소금이 흘러내린다. 생선을 절인 굵은 소금이다.`,
  o:[
    { l:'① 무력을 쓴다 — 경첩 쪽 문틀을 친다.', k:'break', dc:21, cost:{ might:24 },
      ok:`손잡이 쪽이 아니라 경첩 쪽을 봤다. 경첩은 밖에 있어도 경첩이 박힌 문틀은 안에 있다.<br><br>무력을 실어 문틀 모서리를 쳤다. 다섯 번. 언 쇠는 잘 깨진다. 여섯 번째에 경첩이 문틀째 떨어졌다. 문이 비스듬히 밖으로 넘어간다.<br><br>나오는 길에 소금 덩이 하나를 주웠다. 손이 얼어 놓을 줄을 몰랐다.`,
      ng:`치는데 손이 얼어 자루 감각이 없다. 세 번째에 무기가 손에서 빠졌다.<br><br>주우려고 숙이는데 손가락이 바닥 서리에 붙었다. 떼면서 살갗을 두고 왔다.<br>온도계 바늘이 한 칸 더 내려갔다.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-26, mind:-12, might:-5 } },
    { l:'② 상자 사이에 숨어 문이 열리기를 기다린다.', k:'hide', dc:20,
      ok:`상자 몇 개를 옮겨 그 사이에 들어갔다. 숨을 상자 쪽으로 쉬었다. 입김이 안 보이게.<br><br>한참 뒤 문이 열렸다. 우비 입은 사람이 들어온다. 손에 장부를 들었다. 다 얼었는지 세러 온 것이다.<br><br>그가 안쪽으로 간 사이 열린 문으로 나왔다. 문을 밖에서 닫았다. 바깥에는 손잡이가 있다.`,
      ng:`기다리는 사이 손발이 먼저 갔다. 감각이 없다.<br><br>문이 열렸을 때 일어나려는데 무릎이 안 펴진다. 우비가 손전등으로 상자 사이를 훑는다. 불빛이 장화 앞에서 멈췄다가 지나갔다.<br>나오긴 나왔다. 손가락 끝이 하얗다. 돌아오는 데 오래 걸렸다.`,
      win:{ exp:16, dream:1, item:'소금 덩이' }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B2', t:'계단실 — 바깥에서 잠긴 방화문',
  x:`계단실 방화문이다. 내려가는 길은 이것 하나다.<br><br>
    바깥에서 잠겼다. 쇠문 가운데 철망 유리가 있다. 그 너머로 계단이 감겨 내려간다. 6층 표지판이 보인다.<br>
    무기로 치면 열릴 것이다. 계단실은 소리가 위아래로 다 간다.<br><br>
    철망 너머 아래층 계단참에 누가 서서 올려다본다. 환자복이다. 머리가 난간보다 높다.`,
  o:[
    { l:'① 문을 부순다.', k:'break', dc:21,
      doom:{ title:'울린 계단실', what:'계단 아래로 끌려 내려갑니다', dc:17, sec:55,
        text:`쳤다. 문이 우그러졌다. 두 번째에 걸쇠가 떨어졌다.<br><br>소리가 계단을 따라 내려간다. 6층, 5층, 4층. 층마다 문이 하나씩 열리며 대답한다.<br>발을 내딛는데 난간 사이로 손이 올라왔다. 아래층에서. 길다. 발목을 잡았다.<br><br>당긴다. 아래로. 한 칸씩이 아니라 한 층씩.`,
        dieText:`7층 방화문은 열렸다. 문은 부수면 열린다.<br><br>그날 밤 정각 점검의 숫자는 맞았다. 계단실 아래 어디에서 누가 대신 대답했다.<br>부서진 문에는 아침에 새 걸쇠가 달렸다.` },
      ok:`걸쇠 자리만 쳤다. 한 번. 크게 울리기 전에 무기를 문에 댄 채로 눌러 울림을 죽였다.<br><br>걸쇠가 떨어졌다. 소리가 아래로 반쯤만 갔다. 아래층 문 하나가 열리다 다시 닫혔다.<br><br>계단을 내려갔다. 난간을 잡지 않았다. 난간 사이로 아래가 보인다. 아래에서도 위가 보인다는 뜻이다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 무력을 쓴다 — 문짝을 소리 없이 들어낸다.', k:'steady', dc:21, cost:{ might:26 },
      ok:`치지 않았다. 문 밑단에 손을 넣고 위로 들었다. 경첩이 핀에서 빠지도록.<br><br>무력을 다리에서부터 올렸다. 문이 한 치 떴다. 핀 빠지는 소리가 손톱 깎는 소리만 했다. 잠긴 쪽을 축으로 문이 옆으로 벌어졌다.<br><br>계단 아래가 조용하다. 문은 다시 끼워 두었다. 잠긴 채로.`,
      ng:`들어 올리다 한쪽 핀이 먼저 빠졌다. 문이 기울며 벽을 긁었다.<br><br>쇠 긁는 소리가 아래로 길게 내려간다. 아래층 문이 열린다.<br>문을 내려놓고 벽에 붙었다. 올라오던 발소리가 6층에서 한참 머물다 내려갔다. 허리가 끊어질 것 같다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-14, might:-5 } }
  ] },

{ at:'B3', t:'식당칸 — 칼을 가는 요리사',
  x:`식당칸이다. 식탁마다 흰 보가 깔렸다. 손님은 없다. 의자가 다 반쯤 빠져 있다. 방금까지 앉아 있던 것처럼.<br><br>
    주방 창구 안에서 요리사가 칼을 간다. 슥, 슥. 열차 박자와 안 맞는다. 제 박자로 간다.<br>
    무기를 쥐는 사람은 칼 가는 소리로 날이 얼마나 섰는지 안다. 다 섰다. 더 갈 필요가 없다.<br><br>
    그런데 계속 간다. 이쪽을 보면서.`,
  o:[
    { l:'① 창구 너머 칼 쥔 손목을 친다.', k:'break', dc:21,
      ok:`창구 앞을 지나는 척하다 자루를 창구 안으로 찔러 넣었다. 손목.<br><br>칼이 떨어졌다. 요리사가 손목을 쥐고 웃는다. 웃는 사이 얼굴이 바뀐다. 아까 9호차에서 본 얼굴이다.<br>떨어진 칼을 발로 차서 식탁 밑으로 보냈다.<br><br>그것이 주방 뒷문으로 나간다. 서두르지 않는다. 칼이 하나가 아니라는 듯이.`,
      ng:`찔러 넣었는데 칼이 먼저 왔다. 창구 너머에서 짧게.<br><br>손등이 갈렸다. 무기는 안 놓쳤다. 요리사는 다시 칼을 간다. 이쪽 피가 묻은 날을.<br>슥, 슥. 그 소리가 다음 칸까지 따라왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'② 식탁을 세워 막고 지나간다.', k:'steady', dc:20, wake:1,
      ok:`식탁 하나를 들어 옆으로 세웠다. 창구와 통로 사이에 벽이 됐다.<br><br>그 뒤로 다들 몸을 낮추고 지났다. 칼이 날아와 상판에 박혔다. 손잡이가 떤다. 둘째도. 셋째도.<br>마지막으로 식탁째 들고 뒷걸음으로 지났다. 상판에 칼이 일곱 자루 박혔다.<br><br>무기를 들어야 싸우는 줄 알았다. 들 수 있는 것은 다 무기고, 다 방패다. 손이 식탁 무게를 무기 무게처럼 다뤘다. 다음엔 문짝도 될 것이다.`,
      ng:`식탁을 세우는데 보가 미끄러져 그릇이 쏟아졌다. 깨지는 소리.<br><br>칼이 식탁 위로 넘어와 어깨에 박혔다. 깊지 않다. 깊지 않아도 칼이다.<br>뽑지 않고 다음 칸까지 갔다. 뽑으니 피가 따라 나왔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-32, mind:-12 } },
    { l:'③ 요리사를 눈으로 붙잡아 두고 냉장 칸을 턴다.', k:'luck', dc:20,
      ok:`이쪽은 요리사만 봤다. 눈을 안 돌렸다. 그사이 동료들이 창구 옆 냉장 칸을 열었다.<br><br>요리사도 눈을 안 돌린다. 둘이 서로를 붙잡아 두는 사이 동료가 꾸러미 하나를 안고 나왔다. 언 고기 덩어리다.<br><br>요리사가 처음으로 칼 가는 손을 멈췄다. 멈춘 게 더 무섭다.`,
      ng:`냉장 칸 여는 소리에 요리사가 이쪽이 아니라 동료를 봤다.<br><br>창구 너머로 칼이 날았다. 동료 대신 팔로 막았다. 꾸러미는 떨어져 식탁 밑으로 굴러갔다. 찾을 틈이 없다.<br>팔에 박힌 칼을 뽑아 들고 나왔다. 칼은 하나 생겼다.`,
      win:{ exp:16, dream:1, item:'짐승 고기' }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B', t:'창가 — 네온 아래 웅덩이',
  x:`창으로 바깥 네온이 들어온다. 붉은 빛이 바닥 물웅덩이에 번진다. 젖은 신발들이 남긴 물이다.<br><br>
    웅덩이에 이쪽이 비친다. 이쪽 뒤도 비친다. 뒤에 한 사람이 더 서 있다. 젖은 우산을 들었다.<br>
    돌아보면 없을 것이다. 이런 것은 돌아보면 없다. 돌아보는 사이에 있다.<br><br>
    웅덩이 속 우산이 한 걸음 다가온다.`,
  o:[
    { l:'① 돌지 않고 웅덩이를 보며 뒤로 찌른다.', k:'break', dc:21,
      ok:`웅덩이에서 눈을 떼지 않았다. 우산까지 거리를 쟀다. 두 걸음. 한 걸음 반.<br><br>무기를 옆구리 뒤로 찔렀다. 보지 않고. 닿았다. 천 찢어지는 소리. 우산살 꺾이는 소리.<br>그제야 돌아봤다. 아무도 없다. 꺾인 우산살 하나가 바닥에 있다. 손잡이가 아직 따뜻하다.`,
      ng:`뒤로 찔렀는데 웅덩이 속 거리와 바깥 거리가 다르다. 물에 비친 것은 가깝다.<br><br>무기가 허공을 찔렀다. 그 팔을 누가 잡았다. 손이 빗물만큼 차다.<br>뿌리치고 돌아섰다. 없다. 팔에 멍이 다섯 개.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 웅덩이를 밟아 깨며 걷는다.', k:'steady', dc:20,
      ok:`웅덩이를 일부러 밟았다. 비친 것이 흩어진다.<br><br>걸었다. 웅덩이마다 밟았다. 비치지 않으면 따라올 데가 없다.<br>마지막 웅덩이를 밟고 마른 바닥으로 올라섰다. 마른 데에는 아무것도 안 비친다.`,
      ng:`밟을 때마다 물이 튀어 바지가 젖는다. 웅덩이는 다시 고인다. 다시 비친다.<br><br>우산이 이번엔 웅덩이마다 있다. 하나씩. 같은 거리로.<br>마른 바닥에 닿았을 때 다리가 후들거렸다. 마지막 웅덩이에서 우산이 접히는 걸 봤다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B1', t:'방파제 — 말뚝에 묶인 밧줄',
  x:`방파제 끝이다. 배가 없다. 다섯 시에 대 놓겠다던 배.<br><br>
    말뚝에 밧줄 하나가 묶여 있다. 바다 쪽으로 팽팽하다. 물 밑으로 들어간다. 끝에 무거운 것이 달렸다.<br>
    파도가 칠 때마다 밧줄이 조금씩 풀려 나간다. 말뚝 매듭이 헐겁다.<br><br>
    밧줄 끝에서 거품이 올라온다. 사람 숨 크기의 거품이다.`,
  o:[
    { l:'① 밧줄을 끌어올린다.', k:'steady', dc:21,
      doom:{ title:'방파제 끝', what:'밧줄째 바다로 끌려 들어갑니다', dc:17, sec:50,
        text:`밧줄을 손에 감고 당겼다. 무겁다. 사람 하나보다 무겁다.<br><br>한 뼘 올라왔다. 두 뼘. 그러다 아래에서 당기는 힘이 바뀌었다. 매달린 것이 아니라 쥔 것이다.<br>손에 감은 밧줄이 안 풀린다.<br><br>젖은 시멘트 위로 장화가 미끄러진다. 방파제 끝까지 한 걸음.`,
        dieText:`방파제 끝 말뚝의 밧줄이 다시 팽팽하다.<br><br>다섯 시 십 분, 해무호가 그 옆을 지나갔다. 아무도 밧줄을 보지 않았다.<br>밧줄 끝 거품은 하나 늘었다.` },
      ok:`손에 감지 않았다. 감으면 못 놓는다. 허리에 둘러 몸무게로 당겼다.<br><br>무거운 것이 올라온다. 그물 자루다. 사람이 아니라 사람 옷이 가득 들었다. 젖은 외투들. 다섯 벌.<br>자루에 비닐로 싼 쪽지가 꿰매져 있다. 『전량.』<br><br>숨 크기의 거품은 자루 안 공기였다. 그렇게 믿기로 했다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 밧줄을 끊고 돌아선다.', k:'break', dc:20,
      ok:`말뚝 앞에서 무기를 내리쳤다. 젖은 밧줄은 질기다. 두 번.<br><br>끊긴 밧줄이 물속으로 빨려 들어갔다. 거품이 멎었다.<br>돌아섰다. 배는 안 온다. 처음부터 올 배가 아니었다. 정문 쪽으로 걷는다. 빗속에서 우산 하나가 반대쪽으로 걸어간다.`,
      ng:`내리치는데 파도가 방파제를 넘었다. 발이 쓸린다.<br><br>무기가 말뚝을 쳤다. 밧줄은 반만 끊겼다. 물러서다 젖은 시멘트에 넘어져 무릎을 깼다.<br>반쯤 끊긴 밧줄이 파도마다 조금씩 풀린다. 더 볼 수가 없었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B2', t:'휴게실 — 문 앞의 의자',
  x:`휴게실이다. 환자복 입은 사람들이 텔레비전 앞에 앉았다. 화면에 지지직거리는 눈만 내린다. 다들 그걸 본다.<br><br>
    출구 문 앞에 보호사가 의자를 놓고 앉았다. 팔짱을 꼈다. 팔뚝이 이쪽 허벅지만 하다.<br>
    환자 하나가 이쪽 손에 종이학을 쥐여 준다. 펴 보면 무언가 적혀 있을 것이다.<br><br>
    보호사가 벽시계를 본다. 정각까지 십 분.`,
  o:[
    { l:'① 무력을 쓴다 — 일어서기 전에 의자째 민다.', k:'break', dc:22, cost:{ might:25 },
      ok:`보호사가 일어서기 전에 들어갔다. 일어선 다음은 늦다.<br><br>의자째 밀었다. 무력을 어깨에 실었다. 보호사가 의자와 같이 넘어가 문에 머리를 찧었다. 일어나려는 팔을 무릎으로 눌렀다. 사람이 아니라 문짝을 누르는 것 같다.<br><br>환자들은 화면만 본다. 아무도 돌아보지 않는다. 문을 열고 나왔다. 종이학 안쪽에 연필로 『계단 말고 세탁물 통로』.`,
      ng:`들어갔는데 보호사가 앉은 채로 손목을 잡았다. 일어날 필요가 없었다.<br><br>무력으로 비틀어도 안 풀린다. 그가 천천히 일어서며 팔을 등 뒤로 꺾는다.<br>환자들 틈에 앉혀졌다. 화면에 눈이 내린다. 정각까지 그렇게 앉아 있었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-14, might:-5 } },
    { l:'② 환자들 사이에 앉아 섞인다.', k:'hide', dc:20,
      ok:`빈 의자에 앉았다. 화면을 봤다. 다른 사람들처럼 입을 조금 벌렸다.<br><br>무기를 쥐던 손을 무릎에 얹었다. 손이 자꾸 쥐어지려 한다. 종이학을 쥐게 했다.<br>정각에 보호사가 세러 일어섰다. 문에서 떨어졌다. 세는 줄 끝에 붙었다가 문 쪽으로 빠졌다.<br><br>종이학을 폈다. 『계단 말고 세탁물 통로.』`,
      ng:`앉았는데 다들 같은 박자로 눈을 깜박인다. 이쪽만 박자가 다르다.<br><br>보호사가 그걸 봤다. 다가와 옆에 앉는다. 화면을 같이 본다. 무릎이 이쪽 무릎에 닿는다.<br>정각이 지날 때까지 일어설 수가 없었다. 종이학은 손 안에서 땀에 풀어졌다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B3', t:'침대칸 — 떨어진 신발 한 짝',
  x:`침대칸이다. 칸마다 이층 침대. 커튼이 다 쳐졌다.<br><br>
    한 칸만 위층 커튼이 조금 들렸다. 안에서 누가 이쪽을 본다. 눈 하나만.<br>
    통로가 좁다. 그 칸 앞을 지나야 한다. 위에서 손을 뻗으면 닿는 높이다.<br><br>
    커튼 밑으로 신발 한 짝이 떨어졌다. 일행 중 하나의 신발이다. 그 사람은 지금 맨 앞에 있다. 신발을 다 신고.`,
  o:[
    { l:'① 커튼째 내리친다.', k:'break', dc:21,
      ok:`커튼을 걷지 않았다. 커튼 위로 무기를 내리쳤다. 침대 판까지.<br><br>안에서 무언가 꺾이는 소리. 커튼이 처진다. 처진 커튼 밑으로 팔이 하나 늘어졌다. 소매가 젖었다. 이 열차에 탄 사람은 다 젖었다.<br><br>맨 앞의 일행이 돌아본다. 소매가 말라 있다. 이쪽은 그걸 처음 봤다.`,
      ng:`내리쳤는데 커튼 안이 비어 있다. 무기가 침대 판에 박혔다.<br><br>빼는 사이 아래층 커튼이 열렸다. 손이 발목을 잡았다. 위가 아니라 아래였다.<br>뿌리쳤다. 발목에 손톱자국이 넷. 다섯째 손가락 자리는 비었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-16 } },
    { l:'② 신발을 주워 맨 앞사람에게 내민다.', k:'gaze', dc:21,
      ok:`신발을 주워 앞으로 갔다. 맨 앞의 일행에게 내밀었다. 네 것이냐고.<br><br>그가 발을 내려다본다. 신발을 다 신었다. 그런데 신발 끈 매듭이 거꾸로 묶였다. 일행은 그렇게 안 묶는다.<br>그 얼굴이 웃다 말고 멈췄다. 다음 칸 문이 열렸다 닫혔다. 그가 없다.<br><br>진짜 일행은 위층 커튼 안에서 자고 있었다. 신발 한 짝만 벗은 채로.`,
      ng:`내밀자 그가 받아 신는다. 두 짝 위에 한 짝을 더. 아무렇지 않게.<br><br>뒷걸음질 쳤다. 그가 따라온다. 발소리가 셋이다.<br>침대칸 끝 문까지 뛰어 닫았다. 유리 너머에서 그가 신발 한 짝을 벗어 문 앞에 놓고 간다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-18 } }
  ] },

{ at:'B', t:'쉬는 자리 — 문 앞의 불침번',
  x:`잠깐 눈 붙일 데를 찾았다. 문이 하나뿐인 방이다. 문 하나면 지키기 쉽다. 나가기도 어렵다.<br><br>
    다들 눕는다. 전사가 문 앞에 앉는다. 무기를 무릎에 세웠다. 누가 정한 것도 아닌데 그렇게 됐다.<br>
    비가 창을 두드린다. 박자가 일정해서 잠이 온다.<br><br>
    문 밖 복도 불이 하나씩 꺼진다. 먼 데서부터.`,
  o:[
    { l:'① 반쯤 잠들고 반쯤 깨어 있는다.', k:'steady', dc:21, wake:1,
      ok:`눈을 감았다. 귀는 안 감았다. 무기 쥔 손도 안 감았다.<br><br>잠이 몸 반쪽에만 왔다. 다리와 등은 잤다. 손과 귀는 깨어 있었다. 복도 마지막 불이 꺼질 때 손이 먼저 일어났다. 문고리가 돌기 전에 무기가 문틈을 막고 있었다.<br><br>밖의 것이 물러났다. 반쪽이 쉰 몸이 반쪽 몫을 했다. 이렇게 자는 법은 아무도 안 가르친다. 몸이 오늘 혼자 만들었다.`,
      ng:`반쯤 잠든다는 게 다 잠들었다.<br><br>깨 보니 무기가 무릎에서 넘어가 있다. 문이 한 뼘 열려 있다. 아무도 없다. 문턱에 젖은 발자국이 방 안으로 하나, 밖으로 하나.<br>다들 세어 봤다. 맞다. 그래서 더 이상하다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 부은 손을 빗물에 식힌다.', k:'heal', dc:20,
      ok:`창틈으로 손을 내밀었다. 빗물이 손등을 친다. 오늘 친 것들의 자국이 거기 다 있다.<br><br>부기가 조금 빠진다. 손가락이 다 쥐어진다. 쥐어지면 내일도 싸운다.<br>손을 들이자 복도 불이 다 꺼져 있다. 어둠은 아무것도 하지 않고 아침까지 거기 있었다.`,
      ng:`창틈으로 손을 내밀었는데 밖에서 무언가 손가락을 쥐었다. 장난치듯 가볍게.<br><br>손을 뺐다. 손가락에 젖은 실 같은 것이 감겨 있다. 머리카락이다.<br>밤새 손을 품에 넣고 있었다. 부기는 그대로다.`,
      win:{ exp:14, dream:1, hp:8 }, lose:{ hp:-20, spirit:-16 } }
  ] },

{ at:'B', t:'마지막 문 — 남은 시간',
  x:`나가는 문이 보인다. 비 냄새가 그 문틈으로 들어온다.<br><br>
    문은 잠겼다. 뒤에서 쫓는 것들이 온다. 발소리가 등 뒤를 가득 채운다. 시계 바늘이 마지막 칸 앞에 있다.<br>
    문을 여는 데 걸릴 시간과 저것들이 닿을 시간이 거의 같다.<br><br>
    전사는 그 셈을 할 줄 안다. 누가 남아야 하는지도.`,
  o:[
    { l:'① 뒤에 남아 막는다.', k:'steady', dc:22,
      doom:{ title:'남은 사람', what:'쫓아온 것들에게 붙잡혔습니다', dc:18, sec:50,
        text:`동료들을 문 쪽으로 밀고 돌아섰다. 무기를 들었다.<br><br>첫째를 쳤다. 둘째도. 셋째가 무기를 잡았다. 넷째가 팔을. 다섯째부터는 셀 수가 없다.<br>등 뒤에서 문 열리는 소리가 들렸다. 빗소리가 커진다.<br><br>무기를 놓지 않았다. 손이 놓는 법을 잊었다.`,
        dieText:`문은 열렸다. 다들 빗속으로 나갔다.<br><br>맨 뒤에 선 사람이 맨 뒤를 맡았다. 끝까지.<br>문이 닫힐 때 안에서 무기 부딪는 소리가 한참 났다. 그리고 비만 왔다.` },
      ok:`동료들을 문 쪽으로 보내고 통로 가운데 섰다. 무기를 들었다.<br><br>첫째가 왔다. 쳤다. 둘째를 자루로 받아 첫째 위로 넘겼다. 쓰러진 것들이 길을 막는다. 뒤에 오는 것들이 그걸 넘느라 느려진다.<br>문 열리는 소리. 뒤로 뛰었다. 빗속으로 굴러 나갔다.<br><br>문이 닫혔다. 안에서 문을 두드린다. 두드리기만 한다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 무력을 다 쓴다 — 손때 묻은 자리를 친다.', k:'break', dc:22, cost:{ might:30 }, wake:1,
      ok:`자물쇠가 아니라 문 전체를 봤다. 제일 약한 데는 경첩도 자물쇠도 아니다. 사람들이 제일 많이 민 자리다. 손때가 까맣다.<br><br>무력을 남김없이 끌어올려 거기를 쳤다. 문이 가운데부터 꺾였다. 한 번에.<br>다들 빗속으로 쏟아져 나갔다. 마지막으로 나오며 돌아봤다. 쫓던 것들이 문턱에서 멈췄다. 넘어오지 않는다.<br><br>문을 보는 눈이 달라졌다. 어디를 쳐야 하는지가 아니라 남들이 어디를 쳐 왔는지가 보인다. 손때가 길을 알려 준다.`,
      ng:`쳤다. 문이 휘었다. 안 열렸다. 무력이 다 나갔다.<br><br>발소리가 등에 닿는다. 동료 하나가 휜 틈으로 기어 나간다. 둘. 이쪽은 어깨가 걸린다.<br>누가 옷자락을 잡았다. 찢고 나왔다. 옷자락 반이 안에 남았다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-30, spirit:-16, might:-5 } },
    { l:'③ 문틈에 날을 끼워 비튼다.', k:'fix', dc:21,
      ok:`문과 문틀 틈에 날을 끼웠다. 날이 아니라 지렛대로 썼다.<br><br>비틀었다. 걸쇠가 조금씩 물러난다. 무기가 휜다. 휘는 만큼 걸쇠가 빠진다.<br>찰칵. 문이 열렸다. 무기는 활처럼 휘었다. 그래도 들고 나왔다. 빗속에서 휜 무기가 우습게 보인다.`,
      ng:`비트는데 날이 부러졌다. 반 토막이 문틈에 남았다.<br><br>문은 그대로다. 발소리가 바로 뒤를 돈다.<br>반 토막으로 문을 두드렸다. 다들 같이 두드렸다. 열린 건 한참 뒤다. 그 한참 동안 뒤에서 무엇이 왔는지는 말하지 않기로 했다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'B', t:'막다른 데 — 쇠파이프 셋',
  x:`막다른 데로 몰렸다. 사람 둘이 겨우 서는 너비다. 뒤는 벽이다.<br><br>
    쫓아온 것이 셋이다. 셋 다 같은 외투를 입었다. 같은 속도로 숨을 쉰다.<br>
    넓은 데서 셋은 셋이다. 좁은 데서 셋은 하나씩이다. 무기를 오래 쥔 사람은 그 차이로 산다.<br><br>
    첫째가 외투 안에서 쇠파이프를 꺼낸다.`,
  o:[
    { l:'① 제일 좁은 목에 서서 하나씩 받는다.', k:'break', dc:21, wake:1,
      ok:`벽과 벽 사이 제일 좁은 데에 섰다. 옆으로는 아무도 못 온다.<br><br>첫째가 왔다. 파이프가 벽에 걸려 크게 못 휘두른다. 이쪽은 짧게 쥐었다. 찔렀다. 첫째가 무너지며 둘째 앞을 막는다. 둘째가 그걸 넘는 순간 쳤다. 셋째는 넘어오지 않았다.<br><br>좁은 곳은 늘 이쪽 무기를 막는 곳이었다. 오늘은 저쪽 무기를 막았다. 벽이 이쪽 편이 되는 자리가 따로 있다. 이제 들어서는 데마다 그 자리가 먼저 보인다.`,
      ng:`좁은 데에 섰는데 저쪽도 그걸 안다. 한꺼번에 안 온다. 하나씩 오되 쉬지 않고 온다.<br><br>첫째를 막으면 둘째가, 둘째를 막으면 다시 첫째가. 팔이 지친다. 파이프가 어깨를 쳤다.<br>동료들이 뒤에서 빠질 데를 찾는 동안 셋을 다 받았다. 어깨가 안 올라간다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 첫째를 받은 채로 셋을 밀어낸다.', k:'steady', dc:21,
      ok:`첫째가 오는 걸 무기째 받았다. 받은 채로 밀었다. 한 걸음, 두 걸음.<br><br>첫째 등이 둘째에게 닿는다. 둘째가 셋째에게. 셋이 한 덩어리로 밀린다. 좁아서 비킬 데가 없다.<br>입구까지 밀어내고 무기를 뺐다. 셋이 같이 넘어졌다. 그 위를 동료들이 넘어갔다.`,
      ng:`밀었는데 첫째가 버틴다. 뒤에서 둘이 받쳐 준다. 셋이 미는 힘이 이쪽 하나를 민다.<br><br>벽에 등이 닿았다. 숨이 막힌다. 파이프 끝이 옆구리를 찔렀다.<br>동료가 첫째 무릎을 걷어차서 겨우 풀렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] }

]);

// ------------------------------------------
// 화염술사 · 마력
// ------------------------------------------
kJob('pyro', 'B', [

{ at:'B', t:'빗속 — 꺼지는 손끝',
  x:`비가 옆으로 온다. 손바닥에 띄운 불이 빗방울을 맞을 때마다 쉬익 운다.<br><br>
    불이 작아진다. 작아지면 앞이 안 보인다. 키우면 멀리서도 보인다.<br>
    화염술사는 늘 이 셈을 한다. 이 비에서는 셈이 더 빨라야 한다.<br><br>
    뒤쪽 어둠에서 누가 이쪽 불빛을 보고 걸음을 바꿨다.`,
  o:[
    { l:'① 손을 오므려 불을 손안에 품는다.', k:'steady', dc:20, wake:1,
      ok:`손가락을 오므려 불을 손바닥 안에 가뒀다. 빛이 손가락 틈으로만 샌다. 발밑 한 뼘만 비춘다.<br><br>비가 손등을 친다. 불은 손안에 있어 안 꺼진다. 대신 손바닥이 뜨겁다. 참았다. 참는 사이 뜨거움이 줄었다. 불이 살갗 쪽을 피해 가운데로 모인다.<br><br>불을 드러내 쓰는 줄만 알았다. 감춰서도 쓴다. 손이 불을 쥐는 법을 하나 더 알았다. 뒤의 걸음이 방향을 잃고 멀어진다.`,
      ng:`오므리는데 불이 손가락 사이로 비어져 나왔다. 손등이 데었다.<br><br>놀라서 손을 폈다. 불이 한꺼번에 피었다가 빗속에서 꺼졌다. 한순간 둘레가 다 환했다.<br>그 한순간이면 됐다. 뒤의 걸음이 빨라졌다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, spirit:-12 } },
    { l:'② 마력을 쓴다 — 빗속에서도 안 꺼지게 키운다.', k:'break', dc:20, cost:{ mana:22 },
      ok:`마력을 손바닥에 밀었다. 불이 주먹만 해지고 머리만 해진다. 빗방울이 불에 닿기 전에 김이 된다.<br><br>앞이 다 보인다. 바닥의 물웅덩이, 벽의 금, 길이 꺾이는 데까지. 다들 뛰었다.<br><br>뒤에서도 다 보였을 것이다. 그래도 먼저 꺾었다. 꺾고 나서 불을 껐다.`,
      ng:`불을 키우는데 마력이 빗물에 쓸려 나간다. 키운 만큼 꺼진다.<br><br>머리만 했던 불이 주먹, 손가락 끝, 연기가 됐다. 마력만 빠졌다.<br>어둠 속에서 다들 서로 부딪쳤다. 누가 넘어져 무릎을 깼다. 뒤의 걸음은 멈추지 않는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-14, mana:-5 } }
  ] },

{ at:'B1', t:'부두 — 기름 뜬 물',
  x:`부두 물 위에 기름이 떴다. 빗방울이 떨어질 때마다 무지개가 깨진다.<br><br>
    배 한 척이 불을 끈 채 다가온다. 뱃전에 우비 입은 사람이 셋. 갈고리 장대를 들었다.<br>
    불을 다루는 사람은 기름 냄새를 맡으면 불이 어디까지 갈지 먼저 안다. 부두 끝까지 간다. 이쪽 발밑까지.<br><br>
    발밑 널판도 기름에 젖었다.`,
  o:[
    { l:'① 물 위 기름에 불을 떨군다.', k:'break', dc:21,
      doom:{ title:'불붙은 부두', what:'불길에 갇혔습니다', dc:17, sec:55,
        text:`불씨 하나를 물에 떨궜다. 물 위가 한꺼번에 붉어진다.<br><br>배가 불길에 휩싸였다. 우비들이 물로 뛰어든다. 됐다. 그런데 불이 멈추지 않는다. 기름을 따라 널판 밑으로 들어온다.<br>발밑 틈에서 불이 솟았다. 앞도 불, 뒤도 불이다.<br><br>화염술사는 제 불에는 안 탄다. 기름이 붙든 불은 이미 제 불이 아니다.`,
        dieText:`그날 밤 부두는 오래 탔다. 비가 와도 탔다.<br><br>새벽에 해무호가 들어올 때 물 위에 아직 작은 불들이 떠 있었다.<br>탄 널판 위에 사람 모양 그을음이 하나. 비가 그것부터 지웠다.` },
      ok:`불씨를 배 쪽 물에만 떨궜다. 그리고 손을 펴서 이쪽으로 오는 불을 눌렀다.<br><br>물 위가 배 둘레만 붉어진다. 우비들이 물로 뛰어든다. 불이 이쪽으로 기어 오다 손바닥 앞에서 멈춘다. 더 오지 말라고 했다. 불이 말을 들었다.<br><br>널판에서 물러났다. 등 뒤에서 배가 탄다. 비가 그 위로 계속 온다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 불을 다 감추고 기름 위를 지난다.', k:'hide', dc:20,
      ok:`손끝 불까지 껐다. 다들에게도 불붙을 것은 다 넣으라고 했다.<br><br>어둠 속에서 널판을 밟았다. 미끄럽다. 배는 이쪽을 못 본다. 장대 끝 갈고리가 빈 널판을 긁고 지나간다.<br><br>창고 뒤로 돌아 들어간 뒤에야 숨을 쉬었다. 손이 근질거린다. 불이 쓰고 싶었다고 손이 말한다.`,
      ng:`어둠 속에서 기름 먹은 널판에 미끄러졌다. 무릎이 널판을 쳤다. 소리가 물 위로 간다.<br><br>배에서 장대가 뻗어 왔다. 갈고리가 외투 자락을 찢고 갔다.<br>엎드린 채 기었다. 손바닥이 기름투성이다. 지금 불을 켜면 손부터 탄다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-24, mind:-14 } },
    { l:'③ 드럼통 하나만 달궈 길을 막는다.', k:'fix', dc:21,
      ok:`부두 입구에 기름 드럼통이 서 있다. 손바닥을 통 옆구리에 댔다. 뚜껑 쪽이 아니라 바닥 쪽을.<br><br>통이 데워진다. 뚜껑이 떨린다. 뛰어서 물러났다. 펑. 뚜껑이 날고 불기둥이 선다. 부두 입구가 불에 막혔다.<br><br>배가 거기서 멈췄다. 불은 거기까지만 갔다. 거기까지만 가게 데웠다.`,
      ng:`데우는 사이 손바닥에 기름이 묻어 있었다.<br><br>통보다 손이 먼저 붙었다. 손을 털다 불똥이 널판에 떨어졌다. 작게 탔다가 빗물에 꺼졌다.<br>손등 살갗이 일어났다. 배는 이쪽 불빛을 봤다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-12 } }
  ] },

{ at:'B2', t:'복도 — 천장의 화재 감지기',
  x:`복도 천장에 동그란 화재 감지기가 있다. 빨간 불이 깜빡인다.<br><br>
    병동 문마다 작은 스티커가 붙어 있다. 화재 시 출입문 자동 개방.<br>
    그 글자를 오래 봤다. 불이면 문이 열린다. 불이면 사람들도 나온다. 직원 아닌 직원들도.<br><br>
    정각까지 이십 분이다.`,
  o:[
    { l:'① 감지기 밑에서 손끝을 달군다.', k:'fix', dc:21,
      ok:`의자에 올라 손끝을 감지기 밑에 댔다. 불은 안 냈다. 열만 올렸다.<br><br>삑. 경보가 울린다. 복도 문들이 한꺼번에 철컥 풀린다. 간호사들이 복도로 나온다. 계수기를 쥔 채로 사람을 센다. 다들 문 밖으로 나와 섞였다.<br><br>세는 사람들이 숫자를 놓친다. 그 틈에 계단 쪽 문으로 빠졌다. 경보는 아직 운다.`,
      ng:`손끝을 대는데 감지기가 아니라 스프링클러였다.<br><br>천장에서 물이 쏟아진다. 문은 안 열린다. 손끝 열이 물에 꺼진다.<br>젖은 복도에 간호사가 하나 나와 이쪽을 본다. 의자 위에 선 이쪽을. 딸깍.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 불을 거두고 감지기 아래를 피해 간다.', k:'hide', dc:20,
      ok:`손끝 열까지 다 거뒀다. 몸에서 열이 빠지자 손이 시리다. 불 쓰는 손이 시린 건 드문 일이다.<br><br>감지기 아래를 지날 때마다 숨을 참았다. 빨간 불이 깜빡이기만 한다.<br><br>문 하나는 결국 손으로 열어야 했다. 잠긴 문은 잠긴 대로 있었다. 경보를 안 울린 값이다.`,
      ng:`열을 거두는데 몸이 말을 안 듣는다. 아까 쓴 불이 몸 안에 남았다.<br><br>감지기 밑을 지나는데 빨간 불이 빨리 깜빡인다. 삑, 한 번. 짧게.<br>간호사실 창이 열린다. 누가 고개를 내민다. 한참 이쪽을 보다 들어간다. 계수기 소리가 났다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B3', t:'9호차 — 김 서린 창',
  x:`객차 창에 김이 뿌옇게 서렸다. 바깥 비와 안의 숨 때문이다.<br><br>
    창마다 손바닥 자국이 있다. 누가 김을 닦았던 자리다. 자국은 금방 다시 흐려진다.<br>
    얼굴을 바꾸는 손님도 창을 닦았을 것이다. 얼굴은 바꿔도 손은 하나다.<br><br>
    창 하나에 손바닥을 가까이 댄다. 데우면 김이 걷힌다. 걷히는 순서가 있다.`,
  o:[
    { l:'① 손바닥 열로 창을 고르게 데운다.', k:'gaze', dc:21, wake:1,
      ok:`손바닥을 유리 한 뼘 앞에 두고 아주 낮게 데웠다. 창 하나를 다 덮도록.<br><br>김이 걷힌다. 고르게 걷히지 않는다. 손바닥 자국이 있던 자리가 먼저 걷힌다. 손이 닿았던 데는 유리가 아직 다르다. 자국 셋이 떠오른다. 둘은 아이 손, 하나는 어른 손. 어른 손은 손가락 하나가 짧다.<br><br>불은 태우는 데만 쓰는 줄 알았다. 데우면 보인다. 열이 지나간 자리마다 남은 것이 떠오른다. 눈이 손바닥에 하나 더 생긴 것 같다.`,
      ng:`데우는데 유리 한가운데가 먼저 달았다. 쩍 소리가 났다. 금이 갔다.<br><br>금 사이로 빗물이 스민다. 객차 사람들이 일제히 이쪽을 본다. 다 자는 줄 알았는데.<br>창에 이쪽 손바닥 자국만 남았다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 입김으로 다시 서리게 해 자국을 센다.', k:'sense', dc:20,
      ok:`닦인 창에 입김을 불었다. 뜨거운 숨이다. 김이 다시 서린다.<br><br>새로 서린 김 위로 자국들이 하얗게 떠오른다. 손가락 하나가 짧은 손자국이 창마다 있다. 앞쪽으로 갈수록 새것이다.<br><br>그것이 지나간 길이다. 앞쪽으로 갔다. 아직 앞에 있다.`,
      ng:`입김을 부는데 창 너머에서 누가 같이 분다. 바깥에서. 달리는 열차 바깥에서.<br><br>김이 양쪽에서 서린다. 그 사이에 얼굴 하나가 떠오른다. 이쪽 얼굴이다. 눈만 다르다.<br>창에서 물러났다. 그 창에 다시는 안 갔다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B', t:'숨은 자리 — 식지 않는 몸',
  x:`좁은 데 숨었다. 다들 몸을 붙였다. 밖으로 무언가 지나간다. 냄새를 맡으며.<br><br>
    화염술사의 몸은 남보다 덥다. 불을 쓴 날은 더 덥다. 오늘은 많이 썼다.<br>
    숨을 쉴 때마다 입김이 오른다. 이 추운 데서 혼자만 김이 난다.<br><br>
    밖의 것이 냄새를 맡다 멈췄다. 따뜻한 쪽으로 고개를 돌린다.`,
  o:[
    { l:'① 몸 안의 불을 아래로 내린다.', k:'steady', dc:21, wake:1,
      ok:`불을 끄는 법은 안다. 몸 안의 불을 끄는 법은 모른다. 그래서 내렸다. 가슴에서 배로, 배에서 발바닥으로.<br><br>입김이 옅어진다. 손이 식는다. 발바닥만 뜨겁다. 바닥 돌이 그 열을 먹는다. 밖의 것이 고개를 갸웃하다 지나갔다.<br><br>불을 몸 어디에 둘지 고를 수 있다. 처음 알았다. 쓰는 불만 다루는 줄 알았는데 지니는 불도 다룬다.`,
      ng:`내리려는데 불이 가슴에서 안 내려간다. 오히려 오른다.<br><br>입김이 더 짙어졌다. 밖의 것이 숨은 데 앞에 와서 섰다. 숨을 들이쉬는 소리가 들린다. 길게.<br>한참 뒤에 갔다. 왜 갔는지 모른다. 옆 동료가 이쪽 손을 꽉 쥐고 있었다. 손톱자국이 남았다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 벽에 손을 대 열을 다른 데로 흘린다.', k:'hide', dc:20,
      ok:`벽에 손바닥을 대고 열을 흘렸다. 벽을 따라 멀리. 반대쪽 모퉁이까지.<br><br>밖의 것이 고개를 돌린다. 따뜻한 쪽으로. 모퉁이 쪽으로 간다. 거기서 벽을 긁는다.<br><br>그사이 숨은 데서 나와 반대로 갔다. 벽에 남긴 열은 한참 따뜻할 것이다.`,
      ng:`흘린 열이 멀리 안 갔다. 바로 옆 벽만 데워졌다.<br><br>밖의 것이 그 벽에 코를 댄다. 벽 너머가 바로 이쪽이다.<br>벽을 긁는 소리가 귀 옆에서 났다. 다들 반대쪽 틈으로 기어서 빠졌다. 무릎이 다 까졌다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'창고 사무실 — 금고',
  x:`창고 2층 사무실이다. 블라인드 사이로 항구 네온이 붉게 줄무늬를 긋는다.<br><br>
    구석에 금고가 있다. 다이얼식이다. 우산 쓴 남자가 말한 장부는 저 안에 있을 것이다.<br>
    다이얼은 돌릴 줄 모른다. 쇠를 녹일 줄은 안다.<br><br>
    계단 밑에서 대걸레 소리가 멎었다. 양동이 내려놓는 소리가 났다.`,
  o:[
    { l:'① 마력을 쓴다 — 자물쇠 한 점만 녹인다.', k:'break', dc:21, cost:{ mana:25 },
      ok:`다이얼 옆 열쇠 구멍에 검지를 댔다. 마력을 손가락 끝 한 점에 몰았다.<br><br>쇠가 빨개지고 하얘지고 흘러내린다. 바늘구멍만 한 데부터. 안에서 무언가 툭 끊어졌다. 문이 열렸다.<br><br>장부가 있다. 마지막 장에 오늘 날짜. 그 밑에 다섯 줄. 이쪽 일행 수와 같다. 이름 칸은 비었고 옆에 『처리』라고 적혔다.`,
      ng:`한 점에 모이지 않고 금고 문 전체가 달았다. 빨갛게.<br><br>안에서 종이 타는 냄새가 난다. 열었을 때 장부는 재다. 손을 넣자 재가 날렸다.<br>계단에서 장화 소리가 올라온다. 한 칸씩. 손가락 끝이 덴 채로 창으로 나갔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-14, mana:-5 } },
    { l:'② 금고는 두고 책상 위 재떨이를 본다.', k:'gaze', dc:20,
      ok:`재떨이에 종이 탄 재가 있다. 다 타지 않았다. 불 쓰는 사람은 덜 탄 종이를 안다. 어느 쪽부터 탔는지 보면 무엇을 지우려 했는지 안다.<br><br>모서리에 숫자가 남았다. 0510. 그리고 반쯤 탄 글자. 『…문 열어 둘 것. 하나만.』<br><br>다섯 명이 들어왔다. 하나만 나가게 되어 있다. 재를 털어 버렸다. 누가 그 하나인지는 우산이 정하는 것이다.`,
      ng:`재를 손끝으로 뒤적이는데 불씨가 아직 살아 있었다.<br><br>손끝 바람에 살아난 불씨가 남은 종이를 마저 태웠다. 글자가 눈앞에서 지워진다.<br>남은 건 손끝의 그을음뿐이다. 계단에서 장화 소리가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-12 } }
  ] },

{ at:'B2', t:'처치실 — 소독약 냄새',
  x:`처치실이다. 선반에 소독약 병이 줄지어 있다. 뚜껑이 다 열려 있다.<br><br>
    손끝이 저절로 오그라든다. 불이 좋아하는 냄새다. 방 전체가 그 냄새다.<br>
    복도에서 딸깍 소리가 다가온다. 정각 점검이 오고 있다. 이 방에서 숨을 데는 없다.<br><br>
    문 앞 바닥에 소독약이 흘러 있다. 누가 일부러 흘렸다.`,
  o:[
    { l:'① 솜에 불을 붙여 문 앞에 던진다.', k:'break', dc:21,
      ok:`솜 뭉치에 손끝 불을 붙여 문 앞 웅덩이에 던졌다. 그리고 선반 반대쪽 끝으로 몸을 붙였다.<br><br>문 앞이 파랗게 탄다. 소리 없이. 문을 열려던 간호사가 멈춘다. 파란 불 너머에서 계수기를 쥔 채 이쪽을 본다. 불을 넘어오지 않는다.<br><br>불이 꺼지기 전에 창 쪽 배관 통로로 빠졌다. 흘린 사람은 이쪽이 이럴 줄 알았을까. 몰랐길 바란다.`,
      ng:`던진 솜이 웅덩이에 닿기 전에 공기가 먼저 탔다. 방에 냄새가 너무 찼다.<br><br>펑. 불이 방 전체를 한 번 핥았다. 눈썹과 앞머리가 사라졌다. 소매가 탄다.<br>바닥에 굴러 껐다. 문이 열렸다. 간호사가 연기 속에서 딸깍 누른다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-14 } },
    { l:'② 불은 안 쓴다 — 병 뚜껑을 닫고 창을 연다.', k:'sense', dc:20,
      ok:`병 뚜껑을 하나씩 닫았다. 손이 떨렸다. 불을 쓰는 손이 불을 막느라 떨린다.<br><br>철망 창을 밀어 틈을 냈다. 빗바람이 들어와 냄새를 쓸어 간다.<br>문이 열렸다. 간호사가 들어와 둘러본다. 이쪽은 선반 그늘에 서 있었다. 딸깍. 세어졌다. 다른 문제는 없었다.<br><br>나갈 때 바닥에 흘린 웅덩이를 봤다. 문지방을 따라 일부러 길게 흘렸다. 불이 문을 막도록.`,
      ng:`뚜껑을 닫는 사이 하나를 넘어뜨렸다. 쨍그랑.<br><br>냄새가 한꺼번에 오른다. 머리가 핑 돈다. 무릎이 꺾였다.<br>간호사가 들어와 이쪽을 내려다본다. 쓰러진 사람도 세어진다. 딸깍.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B3', t:'침대칸 — 어둠 속 담뱃불',
  x:`침대칸 통로 끝에 담뱃불 하나가 떠 있다. 빨간 점. 그것 말고는 어둡다.<br><br>
    담뱃불이 밝아졌다 어두워진다. 빨아들일 때마다. 그 순간마다 입가가 잠깐 비친다. 매번 다른 입이다.<br>
    불을 보면 거리를 안다. 열 걸음. 그런데 빨아들일 때마다 한 걸음씩 가깝다.<br><br>
    여기는 금연칸이다. 벽에 그렇게 적혀 있다.`,
  o:[
    { l:'① 담뱃불을 끌어당겨 얼굴을 비춘다.', k:'gaze', dc:21,
      ok:`멀리서 담뱃불에 마력을 살짝 걸었다. 불이 이쪽 말을 듣는다. 확 피어올랐다.<br><br>얼굴 전체가 비쳤다. 한순간. 그 한순간에는 얼굴을 바꾸지 못했다. 남자다. 왼쪽 눈썹에 흉이 있다. 눈이 놀라 크다.<br><br>불이 꺼졌다. 다시 담뱃불이 켜지자 다른 얼굴이다. 그래도 흉은 봤다. 바꾼 얼굴에도 그 흉이 있다.`,
      ng:`불을 끌어당기는데 그것이 담배를 손가락으로 비벼 껐다. 먼저.<br><br>어둠이 완전해졌다. 열 걸음이었던 것이 몇 걸음인지 모른다.<br>귀 옆에서 담배 냄새가 났다. 손가락 하나가 볼을 쓸고 갔다. 뜨거웠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-18 } },
    { l:'② 멀리서 불씨를 죽여 버린다.', k:'fix', dc:20,
      ok:`담뱃불에서 열을 빼냈다. 멀리서. 촛불을 손끝으로 집어 끄듯이.<br><br>빨간 점이 꺼졌다. 다시 붙이는 소리가 난다. 라이터가 안 켜진다. 세 번. 네 번. 이쪽이 그 불도 쥐고 있다.<br><br>어둠 속에서 그것이 낮게 혀를 찬다. 발소리가 반대로 멀어진다. 불이 없으면 이것도 볼 수 없는 것이다.`,
      ng:`불씨를 죽였는데 다른 데서 불이 켜졌다. 이쪽 바로 옆 침대 커튼 안에서.<br><br>담뱃불이 둘이었다. 처음부터.<br>커튼 안에서 연기가 이쪽 얼굴로 뿜어졌다. 눈이 따갑다. 뜨니 둘 다 없다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-14, spirit:-16 } }
  ] },

{ at:'B', t:'쉬는 자리 — 손바닥 물집',
  x:`쉴 데에 닿았다. 손바닥을 펴 봤다.<br><br>
    물집이 셋. 비 오는 밤에 불을 쓰면 이렇게 된다. 빗물이 불에 닿아 김이 되고, 그 김이 손을 익힌다.<br>
    화염술사의 손은 불에는 강하다. 김에는 약하다.<br><br>
    밤은 아직 길다. 이 손으로 불을 몇 번 더 내야 한다.`,
  o:[
    { l:'① 물집을 터뜨리지 않고 천천히 식힌다.', k:'heal', dc:20,
      ok:`물에 담그지 않았다. 손을 펴서 바람만 쐬었다. 천천히.<br><br>물집이 가라앉지는 않는다. 다만 덜 뜨겁다. 붕대를 느슨하게 감았다. 불 낼 때 풀기 쉽게.<br><br>쉬는 동안 손바닥이 숨을 쉬었다. 내일 손은 오늘 손보다 조금 낫다.`,
      ng:`식히는데 물집 하나가 저절로 터졌다.<br><br>쓰라리다. 붕대를 감다가 피가 배어 나왔다.<br>이 손으로 불을 내면 피가 끓는다. 아는데도 손이 근질거린다.`,
      win:{ exp:12, dream:1, hp:8 }, lose:{ hp:-20, mind:-12 } },
    { l:'② 손바닥 말고 손목에서 불을 내 본다.', k:'steady', dc:21, wake:1,
      ok:`불은 늘 손바닥에서 냈다. 손바닥이 다쳤다. 그래서 손목 안쪽, 핏줄이 지나는 데에 마력을 모았다.<br><br>처음엔 열만 났다. 다음엔 연기. 셋째에 불이 손목에서 피어 손등 위로 흘렀다. 손바닥은 안 데었다.<br><br>불이 나오는 문이 손바닥 하나뿐인 줄 알았다. 몸에 문이 더 있다. 오늘 하나를 찾았다. 다친 손이 가르쳐 준 것이다.`,
      ng:`손목에 모은 마력이 핏줄을 타고 거꾸로 올라왔다. 팔꿈치까지 뜨겁다.<br><br>팔을 감싸 쥐고 웅크렸다. 땀이 김이 되어 오른다.<br>한참 뒤에 식었다. 팔 안쪽에 빨간 줄이 길게 남았다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'추격 — 훑고 오는 손전등',
  x:`뒤에서 손전등 불빛이 바닥을 훑는다. 좌에서 우로. 다시 우에서 좌로. 서두르지 않는다.<br><br>
    불빛이 닿는 데는 다 보인다. 닿지 않는 데로 다들 몸을 붙였다.<br>
    불을 다루는 사람은 남의 불빛을 보면 그 불을 든 손이 어디 있는지 안다. 불빛은 손에서 시작된다.<br><br>
    불빛이 이쪽 발끝 한 뼘 앞까지 왔다 돌아간다. 다음번엔 닿는다.`,
  o:[
    { l:'① 불씨를 멀리 던져 미끼로 둔다.', k:'hide', dc:21, wake:1,
      ok:`손끝 불씨를 떼어 반대쪽 모퉁이로 던졌다. 손을 떠나도 꺼지지 말라고 일렀다.<br><br>불씨가 모퉁이 바닥에 앉아 깜빡인다. 사람 담뱃불만 하다. 손전등이 그쪽으로 돌아간다. 발소리도.<br>그사이 반대로 빠졌다. 한참 가서 돌아보니 불씨가 아직 거기서 깜빡인다.<br><br>불은 손에서 떨어지면 죽는 줄 알았다. 이른 대로 거기 남아 있다. 불을 두고 갈 수 있다. 그 불이 이쪽 대신 거기 있어 준다.`,
      ng:`던진 불씨가 공중에서 꺼졌다. 손을 떠난 불은 오래 못 간다.<br><br>모퉁이에서 빨간 점 하나가 반짝하고 사라지는 걸 손전등이 봤다. 그리고 불씨가 날아온 쪽을 비췄다.<br>이쪽 얼굴에 불빛이 닿았다. 눈이 부시다. 다들 뛰었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, spirit:-14 } },
    { l:'② 마력을 쓴다 — 손전등 쥔 손을 달군다.', k:'break', dc:21, cost:{ mana:24 },
      ok:`불빛이 시작되는 데를 봤다. 손이다. 손전등 쇠통에 마력을 걸었다. 멀리서.<br><br>쇠통이 달아오른다. 손전등이 바닥에 떨어져 굴렀다. 불빛이 천장을 비춘다. 쥐었던 사람이 손을 감싸 쥐고 비명을 삼킨다.<br><br>떨어진 손전등을 지나쳐 갔다. 그 사람 손바닥에 동그란 자국이 남았을 것이다. 다음에 만나면 그걸로 안다.`,
      ng:`쇠통에 마력을 걸었는데 손전등이 아니라 그 옆 쇠난간이 달았다.<br><br>손전등은 그대로 이쪽을 찾는다. 달아오른 난간에 동료가 손을 짚었다. 비명이 났다.<br>비명이 난 쪽으로 불빛이 왔다. 마력만 쓰고 들켰다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14, mana:-5 } },
    { l:'③ 몸을 낮추고 불빛 주기를 센다.', k:'steady', dc:20,
      ok:`엎드렸다. 불빛이 지나가는 박자를 셌다. 좌에서 우로 일곱 숨. 돌아오는 데 일곱 숨.<br><br>불빛이 우로 간 순간 왼쪽으로 기었다. 일곱 숨 안에 다음 그늘까지.<br>세 번 반복해서 빠졌다.<br><br>남의 불을 셀 줄 아는 것도 불 쓰는 사람의 일이다.`,
      ng:`세다가 박자가 바뀌었다. 불빛이 갑자기 멈췄다가 거꾸로 왔다.<br><br>기던 중에 불빛이 등에 닿았다. 그대로 엎드려 숨을 죽였다. 불빛이 등 위에 한참 머문다.<br>그러다 갔다. 왜 갔는지는 모른다. 등이 아직 뜨겁다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B1', t:'냉동 창고 — 성에 낀 문',
  x:`냉동 창고에 갇혔다. 문틈이 성에로 붙었다. 바깥 손잡이를 누가 철사로 묶었다.<br><br>
    생선 상자 사이로 숨이 하얗게 흩어진다. 다들 입술이 파래진다.<br>
    여기서 따뜻한 것은 이쪽 하나다. 다들 그걸 안다. 말은 안 한다.<br><br>
    문 너머에서 철사를 한 번 더 감는 소리가 난다.`,
  o:[
    { l:'① 문틈 성에를 녹이고 철사까지 데운다.', k:'fix', dc:21,
      ok:`문틈에 손가락을 대고 위에서 아래로 그었다. 성에가 녹아 물이 흐른다.<br><br>문틈이 벌어지자 그 틈으로 열을 밀었다. 바깥 철사까지. 철사가 빨개지고 끊어진다. 밖에서 누가 손을 데고 욕을 한다.<br><br>문을 밀었다. 바깥은 비다. 차가운 비가 따뜻하게 느껴진다.`,
      ng:`녹인 물이 문틈에서 다시 언다. 녹이는 것보다 어는 게 빠르다.<br><br>손가락이 문에 붙었다. 떼면서 살갗을 남겼다.<br>밖의 철사 감는 소리가 멈췄다. 그리고 웃음소리. 짧게.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 다들 붙여 앉히고 가운데서 몸을 데운다.', k:'bond', dc:20,
      ok:`다들 둘러앉게 하고 가운데 앉았다. 몸에 열을 올렸다. 숨 쉴 만큼만.<br><br>입술 색이 돌아온다. 누가 졸기 시작한다. 깨웠다. 여기서 졸면 안 된다.<br>한참 뒤 문이 열렸다. 우비가 장부를 들고 들어온다. 다 얼었는지 세러.<br><br>다섯이 다 일어서 있는 걸 보고 우비가 장부를 떨어뜨렸다. 그 틈에 나갔다.`,
      ng:`열을 올리는데 상자 속 얼음이 녹아 바닥이 젖었다. 젖은 바닥이 다시 언다.<br><br>다들 엉덩이가 바닥에 붙었다. 일어날 때 옷이 찢어졌다.<br>열은 다섯에게 나누기엔 모자랐다. 이쪽 몫까지 다 나눴다. 이쪽 입술이 파랗다.`,
      win:{ exp:16, dream:1, hp:6 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B2', t:'세탁실 — 건조기 열기',
  x:`지하로 가는 세탁실이다. 건조기 여섯 대가 돈다. 문 유리 너머로 흰 시트가 구른다.<br><br>
    방이 덥다. 다른 사람들은 땀을 흘린다. 이쪽은 숨이 편하다.<br>
    벽에 세탁물 통로 입구가 있다. 쇠 뚜껑. 아래로 이어진다. 종이학에 적혀 있던 길이다.<br><br>
    문 밖에서 딸깍 소리가 다가온다. 정각이다.`,
  o:[
    { l:'① 제일 뜨거운 건조기 뒤에 붙어 숨는다.', k:'steady', dc:21,
      ok:`건조기 뒤 틈에 몸을 넣었다. 쇠가 손을 데울 만큼 뜨겁다. 참을 만하다. 이쪽은.<br><br>간호사가 들어와 둘러본다. 건조기 뒤를 들여다보려다 열기에 얼굴을 돌린다. 딸깍. 빈 방으로 셌다.<br><br>나와 보니 옷이 바싹 말랐다. 그것 하나는 좋다.`,
      ng:`틈에 들어갔는데 건조기가 멈췄다. 다 돌았다.<br><br>조용해진 방에 이쪽 숨소리만 있다. 간호사가 건조기 문을 열고 시트를 꺼낸다. 시트 사이에 이쪽 그림자가 비친다.<br>딸깍. 세어졌다. 다른 칸에서 한 명이 덜 세어졌을 것이다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 세탁물 통로로 몸을 던진다.', k:'evade', dc:21,
      doom:{ title:'세탁물 통로', what:'세탁물 통로 아래로 빨려 들어갑니다', dc:17, sec:55,
        text:`쇠 뚜껑을 열고 발부터 넣었다. 미끄러진다. 생각보다 빠르다.<br><br>통로가 꺾이는 데서 무언가에 걸렸다. 젖은 시트. 시트가 다리를 감는다. 아래에서 당긴다.<br>위를 올려다봤다. 입구가 동전만 하다.<br><br>아래는 세탁실이 아니다. 더 아래다. 몇 층인지 모른다. 당기는 힘이 쉬지 않는다.`,
        dieText:`그날 밤 세탁실 건조기는 한 번 더 돌았다.<br><br>정각 점검의 숫자는 맞았다. 맞추는 것이 이 병동의 일이다.<br>아침에 나온 시트 한 장이 유난히 따뜻했다. 아무도 이유를 묻지 않았다.` },
      ok:`뚜껑을 열고 발부터 넣었다. 두 손으로 통로 벽을 짚어 속도를 죽였다. 손바닥 열로 젖은 벽을 말리며.<br><br>꺾이는 데서 젖은 시트가 다리를 감으려 한다. 손끝 불을 대자 시트가 오그라들며 놓았다.<br>미끄러져 내려 시트 더미 위에 떨어졌다. 아래층 세탁물 수거실이다.<br><br>위에서 뚜껑 닫히는 소리. 다들 하나씩 떨어져 내렸다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B3', t:'터널 — 꺼진 객차 불',
  x:`열차가 터널로 들어갔다. 객차 불이 한꺼번에 꺼졌다.<br><br>
    완전한 어둠이다. 바퀴 소리가 터널 벽에 부딪혀 두 배로 크다.<br>
    누가 이쪽 팔을 잡았다. 일행 손 같다. 손 크기가 맞다. 온도가 안 맞는다.<br><br>
    불은 켤 수 있다. 켜면 다 보인다. 이쪽도 보인다.`,
  o:[
    { l:'① 손바닥에 불을 피운다.', k:'break', dc:21,
      doom:{ title:'터널 속 불빛', what:'열린 창밖으로 끌려 나갑니다', dc:17, sec:50,
        text:`손바닥에 불을 피웠다. 객차가 주황으로 물든다.<br><br>팔을 잡은 것은 일행 얼굴을 하고 있었다. 이쪽이 그걸 본 순간 그것도 이쪽 불을 봤다. 웃는다.<br>그것 뒤의 창이 열려 있다. 터널 바람이 들이친다. 그것이 팔을 당긴다. 창 쪽으로.<br><br>불이 바람에 눕는다. 창틀이 허리에 닿았다.`,
        dieText:`터널을 빠져나오자 객차 불이 다시 켜졌다.<br><br>창 하나가 열려 빗물이 들이친다. 누가 닫았다.<br>일행을 세었다. 맞다. 그중 하나의 손이 유난히 찼다.` },
      ok:`손바닥에 불을 피웠다. 크게 말고 작게. 손 위로 한 뼘.<br><br>팔을 잡은 것이 일행 얼굴을 하고 있다. 불빛에 눈동자가 안 줄어든다. 손끝 불을 그 손등에 대었다. 그것이 손을 놓고 어둠 속으로 물러났다.<br><br>불을 쥔 채 일행을 하나씩 비춰 세었다. 눈동자가 다 줄어든다. 터널 끝 빛이 보였다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 불은 안 켜고 다들 손을 잡게 한다.', k:'bond', dc:20,
      ok:`불을 켜지 않았다. 낮게 말했다. 다들 옆사람 손을 잡으라고. 따뜻한 손만.<br><br>불 쓰는 손이 제일 따뜻하다. 그 손에서 옆으로, 또 옆으로 손이 이어진다. 팔을 잡았던 찬 손은 이어질 데가 없다. 놓고 갔다.<br><br>터널을 나왔다. 손을 잡은 줄이 그대로다. 다섯. 맞다. 다들 손을 놓기 싫어했다.`,
      ng:`손을 잡으라고 했는데 손이 여섯이다.<br><br>어느 손이 찬지 모르겠다. 다 차다. 비에 젖어서.<br>터널을 나와 불이 켜졌을 때 줄 끝에 아무도 없었다. 끝의 동료 손에 젖은 손자국만 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B', t:'창가 — 꺼진 네온',
  x:`창밖 네온이 지지직 떨다 꺼졌다.<br><br>
    안이 한꺼번에 어두워진다. 이제 여기서 제일 밝은 것은 이쪽 손끝이다.<br>
    창 앞에 누가 서 있다. 네온이 켜져 있을 때는 없었다.<br><br>
    그것이 손끝 불빛을 보고 한 발 내디딘다.`,
  o:[
    { l:'① 불을 끄고 어둠에 섞인다.', k:'hide', dc:20,
      ok:`손끝 불을 껐다. 다들 벽에 붙었다.<br><br>창 앞의 것이 멈췄다. 불빛이 있던 자리를 본다. 거기 아무도 없다. 이쪽은 세 걸음 옆에 있다.<br><br>네온이 다시 켜졌다. 창 앞이 비었다. 바닥에 젖은 발자국만 두 개 있다. 발끝이 이쪽을 향해 있다.`,
      ng:`불을 껐는데 손끝에 열이 남아 김이 오른다. 어둠 속에 하얀 김 한 줄.<br><br>그것이 김을 보고 다가온다. 천천히.<br>뛰었다. 등 뒤로 젖은 손이 외투 깃을 스쳤다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 불을 한꺼번에 터뜨려 눈을 멀게 한다.', k:'break', dc:21, wake:1,
      ok:`손끝 불을 접어 손안에 모았다. 그리고 한 번에 폈다. 열은 빼고 빛만.<br><br>하얀 빛이 사방을 한 번 때렸다. 창 앞의 것이 얼굴을 감싸고 주저앉는다. 그사이 다들 모퉁이를 돌았다. 이쪽 눈은 미리 감았다.<br><br>불에서 열을 떼고 빛만 쓸 수 있다. 태우지 않고 멀게 한다. 손이 그걸 해냈다. 불이 하는 일 하나를 떼어 쥔 셈이다.`,
      ng:`빛만 내려 했는데 열이 같이 나갔다. 손바닥이 터질 듯 뜨겁다.<br><br>빛은 짧았다. 그것은 눈을 한 번 깜박이고 그대로 온다.<br>이쪽 눈이 먼저 멀었다. 한참 동료 어깨를 잡고 걸었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-24, mind:-14 } }
  ] },

{ at:'B1', t:'방파제 — 바다의 불빛',
  x:`방파제 끝에서 바다를 본다. 비 너머에 작은 불빛 하나가 깜빡인다. 배다.<br><br>
    짧게 셋, 길게 하나. 다시 짧게 셋, 길게 하나. 신호다. 대답을 기다린다.<br>
    불로 대답할 수는 있다. 무슨 대답을 원하는지는 모른다.<br><br>
    방파제 뒤쪽에서 양동이 손잡이가 덜그럭거린다.`,
  o:[
    { l:'① 같은 박자로 불을 띄워 대답한다.', k:'fix', dc:21,
      ok:`손바닥 불을 같은 박자로 띄웠다. 짧게 셋, 길게 하나.<br><br>바다의 불빛이 멈췄다. 그리고 다른 박자로 깜빡인다. 길게 다섯. 그리고 꺼졌다. 배가 돌아선다.<br><br>뒤에서 양동이 소리가 멈췄다. 대답한 것은 이쪽인데 배는 다섯을 확인했다. 확인한 다음 떠났다. 이쪽을 실으러 온 배가 아니었다.`,
      ng:`대답했는데 박자를 하나 틀렸다. 짧게 넷.<br><br>바다의 불빛이 꺼졌다. 대신 방파제 뒤에서 손전등이 켜졌다. 이쪽 손 불빛을 정확히 비춘다.<br>틀린 박자는 모르는 사람이라는 뜻이었다. 아는 사람이 오고 있다. 양동이를 들고.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 대답하지 않고 불빛을 읽는다.', k:'gaze', dc:20,
      ok:`대답하지 않았다. 불빛을 봤다. 불의 색을 봤다.<br><br>기름 등불이 아니다. 붉은 천을 씌운 손전등이다. 깜빡이는 사이마다 불빛이 조금씩 오른쪽으로 간다. 배가 방파제가 아니라 정문 쪽 선착장으로 간다.<br><br>배가 오는 데가 아니라 배가 가는 데를 피하면 된다. 다들 방파제를 벗어나 창고 뒤로 붙었다.`,
      ng:`읽는데 불빛이 이쪽을 향해 길게 켜졌다. 꺼지지 않는다.<br><br>대답이 없으니 직접 비추는 것이다. 빗줄기가 불빛 속에서 하얗게 보인다. 이쪽도.<br>엎드렸다. 방파제 시멘트가 차다. 뒤에서 양동이 소리가 가까워진다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B2', t:'격리실 — 찬 방',
  x:`격리실 문 작은 창 너머가 하얗다. 성에다. 안이 얼음장이다.<br><br>
    침대에 환자 하나가 웅크렸다. 이불 없이. 입술이 보라색이다. 이쪽을 보더니 입 모양으로 말한다. 추워.<br>
    문은 안에서는 안 열리고 밖에서는 열린다. 화이트보드에 이 방 숫자는 1이다.<br><br>
    손바닥을 문 창에 댔다. 성에가 손 모양으로 녹는다.`,
  o:[
    { l:'① 마력을 쓴다 — 들어가 방을 데운다.', k:'bond', dc:21, cost:{ mana:22 },
      ok:`들어갔다. 문은 열어 두었다. 침대 옆에 앉아 마력을 낮게 풀었다. 방 전체가 데워지도록.<br><br>성에가 벽에서 물이 되어 흐른다. 환자 입술 색이 돌아온다. 손을 내밀어 이쪽 손을 쥔다. 손이 작다.<br>환자가 베개 밑에서 종이를 꺼내 준다. 계단실 열쇠 번호가 적혀 있다.<br><br>나갈 때 환자는 따라오지 않았다. 이 방 숫자는 1이어야 한다고 했다.`,
      ng:`데우는데 방이 마력을 먹는다. 벽이 열을 빨아들인다. 데워지지 않는다.<br><br>마력이 바닥나고 이쪽 손도 시려 온다. 환자가 이쪽 손을 쥔다. 너무 세게.<br>손을 빼는 데 한참 걸렸다. 문 밖으로 나오자 손가락 끝이 하얗게 얼어 있다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, mind:-14, mana:-5 } },
    { l:'② 문 창 너머로 손바닥 열만 보낸다.', k:'heal', dc:20,
      ok:`문을 열지 않았다. 손바닥을 창에 대고 열을 유리 너머로 보냈다. 한 줄기만.<br><br>환자가 창 쪽으로 기어 와 유리에 이마를 댄다. 따뜻한 데에. 눈을 감는다.<br>한참을 그렇게 있었다. 환자가 눈을 뜨고 손가락으로 김 위에 글씨를 쓴다. 『6층 세탁실.』<br><br>문을 연 것도 아닌데 손바닥이 문 너머까지 갔다.`,
      ng:`열을 보내는데 유리 너머 환자가 이쪽 손바닥에 제 손바닥을 맞댔다.<br><br>유리를 사이에 두고 찬 기운이 거꾸로 온다. 이쪽 손이 유리에 붙는다.<br>떼었다. 손바닥 살갗이 유리에 남았다. 환자가 그 자국을 핥는다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B3', t:'차장 — 행선지 칸이 빈 표',
  x:`차장이 통로를 지나며 표를 본다. 모자 챙에 빗물이 맺혔다. 이 칸에서 비를 맞을 데는 없다.<br><br>
    이쪽 표를 받아 든다. 행선지 칸이 비었다. 차장이 고개를 젓는다. 행선지가 없는 손님은 종착까지 간다고.<br>
    불에 그을려 본 손은 종이 냄새를 안다. 표에서 레몬 같은 냄새가 아주 조금 난다.<br><br>
    차장이 표를 돌려준다. 펀치를 든 채로 기다린다.`,
  o:[
    { l:'① 표를 손끝으로 천천히 데운다.', k:'gaze', dc:21, wake:1,
      ok:`표를 손바닥에 놓고 손끝 열을 아주 낮게 올렸다. 태우지 않을 만큼.<br><br>빈 칸에 갈색 글씨가 떠오른다. 누가 보이지 않는 즙으로 써 둔 것이다. 역 이름이 아니다. 『맨 앞 칸. 04:20.』<br>차장이 표를 보고 얼굴이 굳는다. 펀치로 그 글씨 옆에 구멍을 뚫는다. 다음 칸으로 간다.<br><br>불로 태우는 것 말고 불로 드러내는 것이 있다. 손끝이 오늘 그 온도를 찾았다. 숨긴 것은 대개 그 온도에서 나온다.`,
      ng:`데우는데 열이 한 점에 몰렸다. 표가 갈색이 되다 까맣게 구멍이 났다.<br><br>떠오르던 글씨가 구멍과 같이 사라졌다.<br>차장이 탄 표를 본다. 웃는다. 펀치로 탄 구멍 옆에 하나를 더 뚫는다. 종착까지 간다는 표시다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 차장의 쇠 펀치를 달군다.', k:'break', dc:21,
      ok:`차장이 펀치를 내밀 때 펀치 쇠에 열을 걸었다.<br><br>차장이 펀치를 떨어뜨린다. 손을 털며 이쪽을 본다. 처음으로 표정이 생긴다. 놀람이다.<br>떨어진 펀치를 주워 줬다. 손잡이 쪽으로. 차장이 받고 이쪽 표를 다시 보지 않고 지나갔다.<br><br>표 검사를 안 받은 손님은 아직 아무 데서도 내리지 않기로 한 손님이다.`,
      ng:`펀치를 달궜는데 차장이 놓지 않는다. 손바닥에서 김이 나는데 그대로 쥐고 있다.<br><br>달아오른 펀치로 이쪽 표에 구멍을 뚫는다. 구멍 둘레가 탄다.<br>차장이 고개를 숙여 인사하고 간다. 손바닥 살 타는 냄새를 남기고.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B', t:'뒤의 냄새 — 그을음 자국',
  x:`벽을 짚으며 왔다. 손끝이 까맣다. 오늘 불을 많이 썼다.<br><br>
    돌아보니 벽마다 그을음 손자국이 찍혀 있다. 지나온 길이 다 보인다.<br>
    화염술사는 그을음으로 많은 것을 읽는다. 남들도 읽을 수 있다는 걸 오늘 처음 생각했다.<br><br>
    멀리서 누가 자국 하나에 손가락을 대 냄새를 맡는다.`,
  o:[
    { l:'① 손을 싸매고 자국을 지우며 간다.', k:'fix', dc:20,
      ok:`손을 천으로 싸맸다. 지나온 자국은 젖은 소매로 문질렀다.<br><br>그을음이 번지기만 하고 안 지워진다. 그래서 번지게 했다. 손자국이 그냥 얼룩이 되도록.<br><br>뒤쫓는 것이 얼룩 앞에서 머뭇거린다. 얼룩은 어느 쪽으로도 가리키지 않는다.`,
      ng:`문지르는데 그을음이 소매로 옮았다. 소매가 이제 길을 그린다.<br><br>천으로 싼 손도 젖어 까만 물이 떨어진다. 바닥에 점이 찍힌다.<br>지우려던 것보다 더 많이 남겼다.`,
      win:{ exp:14, dream:1 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 그을음으로 가짜 길을 낸다.', k:'hide', dc:21,
      ok:`갈림길에서 일부러 반대쪽 벽에 손자국을 찍었다. 다섯 걸음마다 하나. 지나온 박자 그대로.<br><br>그리고 손을 씻고 진짜 길로 갔다. 진짜 길에는 아무것도 없다.<br><br>멀리서 발소리가 가짜 길로 간다. 손자국을 하나씩 짚으며. 짚을 때마다 조금씩 빨라진다. 가까워졌다고 믿는 것이다.`,
      ng:`가짜 길에 찍는데 손자국 손가락이 거꾸로 찍혔다. 손을 돌려서 찍었다.<br><br>오는 쪽을 향한 손가락은 가는 쪽을 가리키지 않는다.<br>발소리가 가짜 길 앞에서 멈췄다가 진짜 길로 꺾었다. 빨라졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B', t:'마지막 문 — 녹여야 할 자물쇠',
  x:`나가는 문이다. 쇠문에 맹꽁이자물쇠가 셋 걸렸다. 굵다.<br><br>
    뒤에서 쫓는 것들이 온다. 발소리가 모퉁이 하나 너머다. 시계는 마지막 칸 앞이다.<br>
    쇠는 녹일 수 있다. 셋을 녹일 시간은 없다. 셋을 녹일 마력도 없다.<br><br>
    문은 나무 문틀에 박혀 있다. 나무는 쇠보다 빨리 탄다. 연기도 빨리 난다.`,
  o:[
    { l:'① 마력을 다 쓴다 — 셋을 한 줄로 녹인다.', k:'break', dc:22, cost:{ mana:30 }, wake:1,
      ok:`자물쇠 셋이 걸린 고리를 봤다. 고리는 하나의 쇠막대에 꿰어 있다. 자물쇠가 아니라 그 막대를 녹이면 된다.<br><br>마력을 남김없이 모아 손가락 하나 굵기로 내렸다. 넓게가 아니라 가늘게. 막대가 하얗게 달아 한 줄로 끊어졌다. 자물쇠 셋이 한꺼번에 떨어졌다.<br>문을 밀고 나갔다. 빗속이다.<br><br>불은 넓게 퍼질수록 세다고 믿었다. 가늘게 모으니 더 깊이 들어갔다. 이제 불의 굵기를 고를 수 있다.`,
      ng:`가늘게 모으려다 마력이 흩어졌다. 막대가 빨갛게만 달았다.<br><br>자물쇠 하나가 떨어졌다. 둘은 남았다. 마력이 바닥이다.<br>발소리가 모퉁이를 돈다. 다들 문에 매달려 비틀었다. 열렸을 때 이쪽 소매가 붙잡혀 있었다. 찢고 나왔다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-30, spirit:-16, mana:-5 } },
    { l:'② 나무 문틀을 태운다.', k:'break', dc:21,
      doom:{ title:'타는 문틀', what:'연기 속에 갇혔습니다', dc:17, sec:50,
        text:`문틀에 두 손을 대고 불을 밀었다. 나무가 금방 붙는다.<br><br>문틀이 탄다. 연기가 난다. 연기가 위로 안 가고 이쪽으로 깔린다. 문 밖에서 바람이 들이친다.<br>뒤에서 오던 발소리가 연기 너머에서 멈춘다. 기다린다.<br><br>눈을 뜰 수가 없다. 숨을 쉴 수가 없다. 화염술사는 불에는 강하다. 연기에는 아니다.`,
        dieText:`문틀은 다 탔다. 문은 열렸다.<br><br>연기가 걷힌 뒤 문턱에 한 사람이 엎드려 있었다. 손이 문 밖을 향해 뻗어 있었다.<br>손끝만 빗물에 젖었다.` },
      ok:`문틀 아래쪽에만 불을 붙였다. 그리고 바닥에 엎드리라고 했다. 연기는 위로 간다.<br><br>나무가 탄다. 쇠문이 문틀째 기운다. 엎드린 채로 문짝을 밀었다. 문틀째 밖으로 넘어갔다.<br>연기 속을 기어 빗속으로 나왔다. 뒤의 발소리가 연기 앞에서 멈췄다.<br><br>비가 문틀 불을 끈다. 쉬익. 다 끄기 전에 멀리 갔다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 경첩을 달궈 늘인다.', k:'fix', dc:21,
      ok:`자물쇠 반대편, 경첩을 봤다. 경첩 둘. 손바닥을 대고 달궜다. 녹이지 않고 무르게만.<br><br>달아오른 경첩에 어깨를 붙이고 밀었다. 쇠가 엿처럼 휜다. 문이 경첩 쪽으로 벌어졌다. 자물쇠는 그대로 잠겨 있다.<br><br>잠긴 문을 잠긴 채로 열었다. 어깨에 탄 자국이 남았다. 그 정도는 낸다.`,
      ng:`경첩 하나만 무르고 하나는 안 무르다. 문이 비틀린다.<br><br>비틀린 문 틈은 팔 하나 들어갈 너비다. 몸이 안 들어간다.<br>다시 데우는 사이 발소리가 모퉁이를 돌았다. 다들 그 틈으로 억지로 빠졌다. 이쪽 팔이 경첩에 데었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B', t:'막다른 데 — 젖은 바닥',
  x:`막다른 데다. 뒤는 벽, 앞은 쫓아온 것들. 셋, 넷.<br><br>
    바닥이 젖었다. 빗물이 들이쳐 고였다. 불은 물 위로 안 간다.<br>
    바닥을 본다. 물웅덩이 사이로 무지개가 번진다. 물만 고인 게 아니다.<br><br>
    쫓아온 것들이 천천히 다가온다. 서두를 필요가 없다는 걸 안다.`,
  o:[
    { l:'① 마력을 쓴다 — 바닥에 불의 줄을 긋는다.', k:'fix', dc:21, cost:{ mana:26 },
      ok:`두 손을 바닥에 대고 마력을 밀었다. 물 위로 불을 그었다. 물이 김이 되고 김 사이로 불이 선다.<br><br>불의 줄이 막다른 데를 가로질렀다. 쫓아온 것들이 그 앞에서 멈춘다. 불 너머에서 이쪽을 본다.<br>그사이 동료들이 벽 위 창을 깼다. 하나씩 올라갔다.<br><br>마지막으로 이쪽이 불을 쥔 채 올라갔다. 손을 떼자 불이 꺼졌다. 김만 남았다.`,
      ng:`물이 불을 먹는다. 줄이 아니라 점으로 끊긴다.<br><br>끊긴 틈으로 하나가 넘어왔다. 이쪽 손목을 잡았다. 바닥에서 손이 떨어지자 남은 불마저 꺼졌다.<br>동료가 그것을 떼어 냈다. 손목이 퍼렇다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, mind:-14, mana:-5 } },
    { l:'② 무지개 진 물만 골라 불을 떨군다.', k:'sense', dc:21,
      ok:`물웅덩이마다 봤다. 무지개 진 데만 기름이다. 쫓아온 것들 발밑에 셋.<br><br>불씨를 하나씩 떨궜다. 셋이 차례로 붙는다. 쫓아온 것들이 발밑 불에 물러선다. 맨 물 위에 선 이쪽 발밑은 조용하다.<br><br>불은 갈 데만 간다. 갈 데를 고르는 것이 불 쓰는 사람의 일이다.`,
      ng:`무지개를 잘못 봤다. 네온 빛이 물에 비친 것이었다.<br><br>불씨가 맨 물에 떨어져 쉬익 꺼진다. 셋 다.<br>쫓아온 것들이 그걸 보고 웃는다. 웃음소리가 벽에 부딪혀 돌아온다. 다가온다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-16 } },
    { l:'③ 불 든 손을 앞세우고 맨 앞에 선다.', k:'break', dc:22,
      ok:`손바닥 불을 머리만 하게 키워 들고 맨 앞에 섰다. 한 걸음 나갔다.<br><br>쫓아온 것들이 한 걸음 물러선다. 다시 한 걸음. 불을 든 사람은 앞으로 갈 수 있다.<br>막다른 데를 그렇게 걸어 나왔다. 그것들이 양옆으로 갈라졌다. 등 뒤로 닫히지 않게 뒷걸음질로 지났다.<br><br>골목을 나와서야 불을 껐다. 손바닥이 아니라 다리가 떨렸다.`,
      ng:`한 걸음 나갔는데 그것들이 안 물러선다. 하나가 불에 손을 넣는다. 데면서도.<br><br>불 든 손목을 잡혔다. 불이 그 손 위로 번진다. 그래도 안 놓는다.<br>동료들이 뒤에서 끌어당겨 겨우 빠졌다. 손목에 남의 화상 자국이 찍혔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-14 } }
  ] }

]);

// ------------------------------------------
// 권사 · 내공
// ------------------------------------------
kJob('fist', 'B', [

{ at:'B', t:'젖은 바닥 — 밀리는 발',
  x:`바닥이 젖었다. 타일인지 철판인지 시멘트인지, 젖으면 다 같다.<br><br>
    권사는 발부터 배운다. 주먹은 발에서 나온다. 발이 밀리면 주먹도 밀린다.<br>
    앞에서 누가 길을 막고 섰다. 장갑을 꼈다. 장갑 너클이 젖어 번들거린다.<br><br>
    한 걸음 내딛는데 뒤꿈치가 반 치 미끄러졌다. 상대가 그걸 봤다.`,
  o:[
    { l:'① 발가락으로 바닥을 문다.', k:'steady', dc:20, wake:1,
      ok:`뒤꿈치를 들었다. 무게를 발 앞쪽에 싣고 발가락을 오므렸다. 신발 안에서 바닥을 쥐듯이.<br><br>밀리지 않는다. 상대가 들어온다. 발끝에서 무릎, 허리로 힘이 올라가 주먹이 먼저 닿았다. 상대가 젖은 바닥에 미끄러진다. 이쪽은 안 미끄러진다.<br><br>발바닥 전체로 서는 줄만 알았다. 발가락 열 개로도 선다. 젖은 땅에서는 이게 낫다. 발이 새 서는 법을 하나 가졌다.`,
      ng:`발가락을 오므리는데 신발이 헐겁다. 발이 신발 안에서 밀린다.<br><br>상대 너클이 옆구리에 박혔다. 숨이 반쯤 나갔다.<br>뒤로 물러서다 엉덩방아를 찧었다. 상대는 서두르지 않는다. 장갑을 다시 낀다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-12 } },
    { l:'② 내공을 쓴다 — 발바닥에 기를 내려 붙인다.', k:'evade', dc:20, cost:{ qi:22 },
      ok:`숨을 아랫배에 모았다가 다리로 내렸다. 발바닥이 무거워진다. 바닥에 붙는다.<br><br>상대가 들어온다. 비켰다. 발이 미끄러지지 않으니 비키는 것도 짧다. 반 걸음. 상대 주먹이 어깨를 스치고 지나간다. 그 옆구리에 팔꿈치를 넣었다.<br><br>상대가 벽에 기대 숨을 고른다. 그 옆을 지나갔다.`,
      ng:`기가 무릎에서 막혔다. 발바닥까지 안 내려간다.<br><br>막힌 무릎이 굳는다. 비키려는데 다리가 늦다. 너클이 광대뼈를 쳤다.<br>눈앞이 하얬다가 돌아왔다. 입안에서 쇠 맛이 난다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-12, qi:-5 } }
  ] },

{ at:'B1', t:'창고 — 매달린 그물 짐',
  x:`창고 천장 크레인에 그물 짐이 매달렸다. 상자가 가득하다. 걸쇠 하나에 걸려 있다.<br><br>
    아래 통로로 우비 입은 사람들이 온다. 넷. 손전등 불빛이 바닥을 훑는다.<br>
    이쪽은 크레인 기둥 위에 올라와 있다. 쫓기다 올라왔다. 내려갈 데가 없다.<br><br>
    걸쇠가 손 닿는 데에 있다. 녹이 슬었다.`,
  o:[
    { l:'① 걸쇠를 쳐서 짐을 떨군다.', k:'break', dc:21,
      ok:`우비들이 짐 밑을 지날 때를 기다렸다. 첫째가 지나고 둘째가 지나고.<br><br>걸쇠 옆구리를 손날로 쳤다. 녹이 튀며 걸쇠가 벌어졌다. 그물이 떨어진다. 상자가 쏟아진다. 셋째와 넷째 사이에.<br>통로가 상자로 막혔다. 앞의 둘과 뒤의 둘이 갈렸다.<br><br>크레인 레일을 타고 반대편 끝으로 갔다. 아래에서 손전등이 이쪽을 찾는다. 상자 너머로는 못 온다.`,
      ng:`걸쇠를 쳤는데 안 벌어진다. 손날이 녹에 찢겼다.<br><br>쇳소리가 창고에 울렸다. 손전등 넷이 한꺼번에 위를 비춘다.<br>눈이 부시다. 크레인 기둥에 매달린 채로 빛 속에 있다. 아래에서 누가 사다리를 끌어온다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-14 } },
    { l:'② 그물을 타고 지붕 쪽으로 오른다.', k:'evade', dc:20,
      ok:`그물에 매달렸다. 그물이 흔들린다. 흔들림이 멎기를 기다리지 않고 올랐다. 그물코를 발가락에 걸면서.<br><br>그물 위에서 크레인 와이어를 잡고 지붕 들보로 넘어갔다. 들보 위는 어둡다. 손전등이 거기까지 안 닿는다.<br><br>아래에서 우비들이 그물을 올려다본다. 그물만 흔들린다.`,
      ng:`그물코가 손에서 미끄러졌다. 젖었다.<br><br>그물에 매달린 채로 빙빙 돈다. 손전등이 이쪽 다리를 비춘다.<br>아래에서 장대가 올라와 발목을 찔렀다. 들보로 겨우 넘어갔다. 발목에서 피가 떨어진다. 떨어지는 소리가 아래에 들린다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B2', t:'병실 — 구속복',
  x:`눈을 뜨니 팔이 몸에 감겨 있다. 구속복이다. 소매 끝이 등 뒤에서 묶였다.<br><br>
    권사는 맨손이 무기다. 그 손이 지금 제 몸에 묶였다.<br>
    복도에서 딸깍 소리가 다가온다. 정각 점검이다. 묶인 사람은 묶인 대로 세어진다. 그다음 무엇이 오는지는 모른다.<br><br>
    옆 침대 사람도 구속복을 입었다. 그 사람 소매는 비어 있다.`,
  o:[
    { l:'① 어깨를 빼서 빠져나온다.', k:'evade', dc:21,
      ok:`숨을 다 내쉬었다. 가슴이 좁아진다. 한쪽 어깨를 앞으로 접었다. 뼈가 제자리를 조금 비켜 앉는다.<br><br>그 틈으로 팔 하나가 빠졌다. 등 뒤 매듭을 풀었다. 어깨를 도로 끼웠다. 소리가 났다. 이를 악물었다.<br><br>구속복을 침대에 눕혀 이불을 덮었다. 사람 모양으로. 딸깍 소리가 문 앞에 왔을 때 이쪽은 침대 밑에 있었다.`,
      ng:`어깨를 접는데 뼈가 덜 빠졌다. 걸린 채로 멈췄다.<br><br>빠지지도 들어가지도 않는다. 숨을 쉴 때마다 어깨가 운다.<br>딸깍. 간호사가 들어와 이쪽을 본다. 구속복 끈을 한 칸 더 조인다. 어깨가 저절로 들어갔다. 비명을 삼켰다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } },
    { l:'② 내공을 쓴다 — 가슴으로 기를 밀어 끈을 끊는다.', k:'break', dc:21, cost:{ qi:24 },
      ok:`숨을 아랫배에 모았다. 한 번에 가슴으로 올려 밖으로 밀었다. 팔이 아니라 몸통으로.<br><br>구속복이 가슴에서부터 터진다. 등 뒤 매듭이 끊어지는 소리가 났다. 두 팔이 풀렸다.<br><br>옆 침대의 빈 소매를 봤다. 그 안에는 처음부터 팔이 없었다. 구속복만 누워 숨을 쉬고 있다. 쳐다보지 않고 나왔다.`,
      ng:`기를 밀었는데 구속복이 버틴다. 천이 두껍다. 몇 번을 꿰맸다.<br><br>밀어낸 기가 갈 데가 없어 가슴 안에서 돈다. 숨이 거꾸로 올라온다. 기침이 터졌다.<br>딸깍. 기침하는 사람도 세어진다. 간호사가 수첩에 무언가 적는다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, mind:-14, qi:-5 } }
  ] },

{ at:'B3', t:'9호차 — 흔들리는 바닥의 싸움',
  x:`통로에서 누가 덤볐다. 아까 창에 비쳤던 얼굴이다. 지금은 다른 얼굴이다.<br><br>
    열차가 흔들린다. 덜컹. 이음매를 넘을 때마다 바닥이 한 치씩 튄다.<br>
    주먹은 땅에 서서 배웠다. 땅은 안 흔들린다. 여기서는 땅이 제 박자로 흔든다.<br><br>
    상대가 흔들림에 맞춰 들어온다. 이 열차를 오래 탄 걸음이다.`,
  o:[
    { l:'① 흔들림을 주먹에 싣는다.', k:'break', dc:21, wake:1,
      ok:`버티지 않았다. 덜컹하는 박자를 셌다. 하나, 둘, 덜컹. 하나, 둘, 덜컹.<br><br>상대가 들어올 때 이쪽도 들어갔다. 덜컹하는 순간에. 바닥이 튀는 힘이 무릎을 타고 올라와 주먹에 얹혔다. 상대가 좌석 등받이를 넘어 날아갔다.<br><br>주먹은 제 힘으로만 치는 줄 알았다. 바닥이 흔드는 힘도 빌린다. 빌릴 데가 있으면 빌린다. 몸이 그 셈을 오늘 처음 했다.`,
      ng:`박자를 셌는데 이음매가 두 개 연달아 왔다. 덜컹, 덜컹.<br><br>주먹이 허공을 쳤다. 상대 무릎이 배에 들어왔다.<br>좌석 사이에 처박혔다. 상대가 선반의 가방을 내려 이쪽 머리 위에 떨군다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 손잡이를 잡고 발로만 상대한다.', k:'steady', dc:20,
      ok:`좌석 손잡이를 두 손으로 잡았다. 몸을 열차에 묶었다.<br><br>상대가 들어온다. 발로 받았다. 무릎, 정강이. 손이 묶인 대신 발이 자유롭다. 상대가 세 번 들어왔다 세 번 밀려났다.<br><br>상대가 숨을 고르며 물러선다. 얼굴이 바뀐다. 바꾼다고 다리가 길어지지는 않는다.`,
      ng:`손잡이를 잡았는데 상대가 이쪽 손가락을 노렸다. 손잡이째 밟았다.<br><br>손가락이 꺾였다. 손잡이를 놓쳤다. 덜컹. 몸이 통로로 굴렀다.<br>일어나 보니 상대는 없다. 손가락 둘이 이상한 쪽으로 굽었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'통로 — 칼 든 손',
  x:`모퉁이에서 사람이 나왔다. 손에 칼이 있다. 짧은 것. 날이 위를 보게 쥐었다.<br><br>
    칼을 저렇게 쥐는 사람은 찌르지 않는다. 올려 벤다. 손목을 아는 사람이다.<br>
    권사는 맨손이다. 맨손과 칼 사이에는 한 걸음이 있다. 그 한 걸음을 넘으면 이쪽 것이다. 못 넘으면 저쪽 것이다.<br><br>
    상대가 한 걸음 물러선다. 이쪽 한 걸음을 재고 있다.`,
  o:[
    { l:'① 한 걸음을 넘어 손목을 손날로 친다.', k:'break', dc:22,
      doom:{ title:'한 걸음', what:'칼에 찔렸습니다', dc:18, sec:45,
        text:`넘었다. 손날이 손목에 닿았다.<br><br>칼이 떨어지지 않았다. 손목이 아니라 팔꿈치에 맞았다. 상대가 반 걸음 물러서 있었다. 이쪽이 넘을 걸음을 미리 줄여 놓았다.<br>칼날이 올라온다. 아래에서 위로.<br><br>배가 차갑다. 뜨거워진다. 다시 차갑다.`,
        dieText:`맨손과 칼 사이에는 한 걸음이 있다.<br><br>그날 그 한 걸음은 반 걸음이었다. 상대가 먼저 쟀다.<br>통로 바닥에 빗물과 다른 것이 섞여 흘렀다. 칼은 한 번만 쓰였다.` },
      ok:`넘는 척하고 넘지 않았다. 상대 칼이 한 걸음 앞 허공을 올려 그었다.<br><br>그 칼이 올라간 순간 넘었다. 손날로 손목을 쳤다. 칼이 손에서 튀어 천장에 박혔다. 그대로 팔꿈치를 꺾어 바닥에 눌렀다.<br><br>천장에 박힌 칼이 떤다. 상대가 웃는다. 바닥에 뺨을 댄 채로. 칼이 하나뿐이었다는 걸 아는 웃음이 아니다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 외투를 벗어 팔에 감는다.', k:'fix', dc:20,
      ok:`외투를 벗어 왼팔에 둘둘 감았다. 젖은 외투는 무겁다. 무거운 천은 칼을 먹는다.<br><br>상대가 올려 벤다. 왼팔로 받았다. 칼이 천에 박혀 걸린다. 오른 주먹이 상대 턱에 닿았다.<br><br>외투를 풀어 보니 칼자국이 넷이다. 팔에는 하나도 없다.`,
      ng:`감는 사이 상대가 먼저 들어왔다. 외투가 반만 감겼다.<br><br>칼이 감기지 않은 손등을 긋고 지나갔다. 피가 외투에 스민다.<br>상대가 물러나 칼을 턴다. 다음 번에는 더 깊을 것이다. 등을 돌리지 않고 물러났다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-28, spirit:-12 } },
    { l:'③ 물러서서 거리를 다시 잰다.', k:'evade', dc:20,
      ok:`한 걸음 물러섰다. 상대가 한 걸음 들어온다. 또 물러섰다. 또 들어온다.<br><br>세 번째에 상대 뒤꿈치가 젖은 데를 밟았다. 미끄러졌다. 반 치. 그 반 치 동안 거리가 무너졌다.<br>들어가서 칼 든 팔을 겨드랑이에 끼고 꺾었다. 칼이 떨어졌다.<br><br>재는 쪽이 이긴다. 오래 재는 쪽이.`,
      ng:`물러서다 등이 벽에 닿았다. 잴 거리가 없어졌다.<br><br>칼이 올라온다. 팔로 막았다. 팔뚝이 갈렸다.<br>상대가 칼을 거두고 모퉁이로 사라진다. 다음 모퉁이에서 또 나올 것이다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B1', t:'선창 — 청소부',
  x:`선창 끝에서 누가 바닥을 닦는다. 우비에 장화. 대걸레 자루가 쇠다. 끝에 갈고리가 달렸다.<br><br>
    옆에 양동이가 있다. 물이 아니라 표백제 냄새가 난다. 빗물이 양동이에 떨어져 거품이 인다.<br>
    청소부가 대걸레를 멈추고 이쪽을 본다. 모자 그늘 아래 얼굴이 없다. 그늘만 있다.<br><br>
    장대를 든 사람과 맨손으로 싸울 때는 안쪽으로 들어가야 한다. 장대 끝은 멀고 장대 안쪽은 가깝다.`,
  o:[
    { l:'① 장대 안쪽으로 파고든다.', k:'break', dc:22,
      doom:{ title:'선창 끝', what:'갈고리에 걸려 물속으로 끌려갑니다', dc:17, sec:50,
        text:`장대가 휘둘러지는 순간 안쪽으로 뛰어들었다. 청소부 가슴 앞.<br><br>주먹을 넣으려는데 장대가 등 뒤에서 돌아왔다. 갈고리가 외투 깃에 걸렸다.<br>청소부가 장대를 당긴다. 선창 끝 쪽으로. 발이 젖은 널판에서 미끄러진다.<br><br>아래는 검은 물이다. 갈고리는 깃에서 안 빠진다. 그렇게 만든 갈고리다.`,
        dieText:`청소부는 대걸레를 다시 잡았다. 선창 끝을 마저 닦았다.<br><br>양동이를 들어 바다에 비웠다. 거품이 한참 떴다가 가라앉았다.<br>선창 끝 널판이 깨끗하다. 새벽까지 아무것도 안 남았다.` },
      ok:`장대가 크게 돌아오는 순간 안쪽으로 들어갔다. 청소부 가슴 앞.<br><br>갈고리가 등 뒤를 지나간다. 장대 안쪽에서는 갈고리가 안 닿는다. 팔꿈치로 장대 쥔 손을 쳤다. 쇠자루가 널판에 떨어져 구른다.<br>청소부가 물러선다. 맨손이 되자 처음으로 망설인다.<br><br>쇠자루를 발로 차 바다에 빠뜨렸다. 청소부가 양동이를 들고 빗속으로 간다. 다른 대걸레가 있는 것이다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 양동이를 걷어차 발밑을 적신다.', k:'fix', dc:21,
      ok:`옆으로 돌며 양동이를 걷어찼다. 표백제가 청소부 장화 밑으로 쏟아진다.<br><br>널판이 미끄러워졌다. 청소부가 장대를 휘두르다 한쪽 무릎을 꿇는다. 그사이 선창 뒤로 빠졌다.<br><br>멀리서 돌아보니 청소부가 무릎을 꿇은 채 쏟아진 것을 닦고 있다. 이쪽은 안 쫓는다. 바닥이 먼저다.`,
      ng:`걷어찬 양동이가 이쪽으로 튀었다. 표백제가 정강이에 쏟아졌다.<br><br>살갗이 타는 것 같다. 젖은 바지가 다리에 붙는다.<br>청소부가 장대 끝으로 쏟아진 양동이를 바로 세운다. 천천히. 그리고 이쪽 다리를 본다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } },
    { l:'③ 장대를 두 손으로 붙잡아 버틴다.', k:'steady', dc:21,
      ok:`장대가 오는 걸 두 손으로 잡았다. 쇠자루가 손바닥을 태울 듯 차다.<br><br>청소부가 당긴다. 이쪽은 발가락으로 널판을 물었다. 한 치도 안 밀렸다. 당기는 힘이 멎는 순간 이쪽이 밀었다. 청소부가 자기 양동이에 걸려 넘어졌다.<br><br>장대를 빼앗아 무릎에 대고 꺾으려다 그만뒀다. 쇠는 안 꺾인다. 바다에 던졌다.`,
      ng:`잡았는데 장대가 손안에서 돈다. 갈고리가 손목 쪽으로 돌아온다.<br><br>손을 놓았다. 갈고리가 손등을 긁고 갔다. 살점이 갈고리에 남았다.<br>청소부가 갈고리 끝을 양동이에 헹군다. 거품이 붉어진다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } }
  ] },

{ at:'B2', t:'복도 — 철망 유리',
  x:`병동 문 가운데 유리창이 있다. 유리 안에 철망이 들었다. 손바닥 두 개만 하다.<br><br>
    철망 너머 안쪽 빗장이 보인다. 유리만 없으면 손이 닿는다.<br>
    깨면 소리가 난다. 이 층은 소리 하나에 다들 나온다. 직원 아닌 직원들이.<br><br>
    유리를 본다. 그리고 제 손바닥을 본다.`,
  o:[
    { l:'① 장을 붙여 소리 없이 깬다.', k:'break', dc:21, wake:1,
      ok:`손바닥을 유리에 붙였다. 치지 않았다. 붙인 채로 숨을 아래로 내렸다가 손바닥 한가운데로 한 번에 보냈다.<br><br>유리 안쪽이 먼저 갈라졌다. 바깥은 그대로다. 철망이 깨진 조각을 붙든다. 와르르 대신 사락. 모래 쏟아지는 소리만 났다.<br><br>치면 소리가 난다. 보내면 소리가 안 난다. 같은 힘인데 밖으로 안 새고 안에서 끝난다. 손바닥이 그 길을 외웠다. 다음 문도 이렇게 연다.`,
      ng:`보내는 힘이 반만 들어갔다. 나머지 반이 손바닥에서 튕겼다.<br><br>쨍. 유리가 바깥까지 금이 가며 울린다. 복도 끝 문이 열리는 소리.<br>손을 떼고 벽에 붙었다. 손바닥에 철망 자국이 찍혔다. 발소리가 다가온다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-20, spirit:-18 } },
    { l:'② 유리 가장자리 틈으로 손가락을 넣는다.', k:'fix', dc:20,
      ok:`유리와 문틀 사이 고무가 삭았다. 손톱으로 고무를 뜯어냈다. 손가락 하나 들어갈 틈.<br><br>철망 끝을 손가락으로 걸어 당겼다. 유리가 문틀에서 반 치 밀려난다. 거기로 손가락 둘을 넣어 빗장 끝을 밀었다.<br><br>빗장이 빠졌다. 소리 없이. 유리는 다시 끼워 두었다.`,
      ng:`고무를 뜯는데 손톱이 뒤집혔다. 피가 유리에 번진다.<br><br>손가락을 넣었는데 빗장 끝이 안 닿는다. 한 마디가 모자라다.<br>정각이 다 됐다. 손을 빼고 침대로 돌아갔다. 문 유리에 핏자국이 남았다. 지울 시간이 없었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B3', t:'화장실 — 잠긴 칸',
  x:`열차 화장실 문에 사용 중이 떠 있다. 아까부터.<br><br>
    안에서 물 트는 소리가 계속 난다. 손을 씻는 소리다. 오래. 너무 오래.<br>
    문 밑 틈으로 물이 흘러나온다. 비누 거품이 섞였다. 일행 중 하나가 아까 화장실에 간다고 했다. 아직 안 왔다.<br><br>
    문 경첩을 본다. 바깥에 있다.`,
  o:[
    { l:'① 경첩 쪽에 장을 넣어 문을 뗀다.', k:'break', dc:21,
      ok:`경첩 바로 옆 문틀에 손바닥을 붙이고 한 번에 보냈다. 경첩 나사가 문틀째 빠졌다.<br><br>문이 잠긴 쪽을 축으로 비스듬히 열린다. 안에 일행이 있다. 세면대 앞에 서서 손을 씻는다. 거울 속 얼굴만 다르다.<br>어깨를 잡아 돌렸다. 진짜 얼굴이다. 눈이 멍하다. 언제부터 씻었는지 모른다고 한다.<br><br>거울은 아직 다른 얼굴을 비춘다. 이쪽을 보고 웃는다. 주먹으로 거울을 쳤다.`,
      ng:`경첩이 빠지면서 문이 이쪽으로 쓰러졌다. 어깨로 받았다.<br><br>안은 비었다. 물만 튼 채로. 세면대에 비누가 반으로 닳았다.<br>돌아보니 통로 저쪽에서 일행이 손을 털며 걸어온다. 손이 젖지 않았다.`,
      win:{ exp:20, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 문 밑 틈으로 발을 본다.', k:'gaze', dc:20,
      ok:`바닥에 엎드려 문 밑 틈을 봤다. 발이 둘. 일행 신발이다.<br><br>그런데 발이 하나 더 있다. 맨발. 일행 발 뒤에 바짝 붙어 서 있다. 발가락이 일행 뒤꿈치에 닿아 있다.<br>문을 두드려 일행 이름을 불렀다. 일행이 대답한다. 문을 연다. 혼자다.<br><br>맨발은 없다. 바닥 물웅덩이에 발자국만 하나 더 있다. 발가락이 문 쪽을 향해 있다.`,
      ng:`엎드리자 문 밑 틈에서 눈 하나가 이쪽을 본다. 바닥 높이에서.<br><br>숨이 멎었다. 일어나는데 문이 열렸다. 일행이 나온다. 혼자다. 이쪽을 내려다보며 왜 엎드려 있냐고 묻는다.<br>대답을 못 했다. 문 밑 틈을 다시는 못 봤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'B', t:'쉬는 자리 — 빗소리 운기',
  x:`잠깐 숨을 돌릴 데다. 다들 벽에 기대 눈을 감는다.<br><br>
    앉아서 숨을 아래로 내린다. 운기는 자는 것보다 낫다.<br>
    오늘은 숨이 안 내려간다. 쫓기는 몸은 숨이 가슴에 붙는다. 억지로 내리면 막힌다.<br><br>
    밖에서 비가 일정하게 온다. 홈통으로 떨어지는 물소리가 한 박자다.`,
  o:[
    { l:'① 빗소리에 숨을 맞춘다.', k:'steady', dc:21, wake:1,
      ok:`제 박자로 숨을 쉬지 않았다. 홈통 물소리에 맞췄다. 떨어질 때 들이쉬고, 다음이 떨어질 때 내쉰다.<br><br>가슴에 붙었던 숨이 박자를 따라 내려간다. 바깥 박자는 쫓기지 않는다. 그래서 내려간다. 아랫배가 데워진다. 손끝까지 기가 돈다.<br><br>운기는 안에서만 하는 줄 알았다. 바깥 소리를 빌려 와도 된다. 마음이 흔들릴 때 몸 밖에 박자를 하나 두는 법. 이제 어디서든 빗소리를 찾을 것이다.`,
      ng:`맞추는데 빗소리가 갑자기 빨라졌다. 바람이 바뀌었다.<br><br>빨라진 박자를 따라가다 숨이 가빠졌다. 기가 엉켜 가슴을 찌른다.<br>운기를 접었다. 숨을 고르는 데 한참. 쉰 게 아니라 더 지쳤다.`,
      win:{ exp:22, dream:2, qi:10 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 떠는 동료 등에 손을 대 숨을 눌러 준다.', k:'bond', dc:20,
      ok:`옆 동료가 떤다. 춥거나 무섭거나. 등 한가운데에 손바닥을 댔다.<br><br>내공을 흘려보내지는 않았다. 손바닥 무게만 실었다. 동료 숨이 손바닥을 밀었다가 돌아간다. 몇 번 그러더니 고르게 된다.<br><br>동료가 눈을 감은 채 고맙다고 한다. 손바닥 하나가 사람 하나를 붙잡아 둔다.`,
      ng:`손을 대자 동료가 놀라 튀었다. 뒤통수가 벽을 쳤다. 소리가 났다.<br><br>밖의 빗소리 사이로 발소리가 멈췄다.<br>다들 숨을 죽였다. 한참 뒤 발소리가 다시 갔다. 동료는 그 뒤로 등을 벽에 붙이고 안 뗐다.`,
      win:{ exp:16, dream:1, mind:6 }, lose:{ mind:-14, spirit:-14 } }
  ] },

{ at:'B', t:'점검구 — 내민 손',
  x:`위로 올라가야 한다. 천장 점검구가 열려 있다. 사다리는 없다. 뒤에서 쫓는 것들이 온다.<br><br>
    먼저 올라간 사람이 점검구에서 손을 내민다. 낯선 사람이다. 아까 길을 같이 찾자고 붙었다.<br>
    주먹 쓰는 사람은 손을 보면 쥐는 힘을 안다. 저 손은 끌어올리는 손 모양이 아니다. 손목이 꺾여 있다. 밀어내는 손이다.<br><br>
    발소리가 모퉁이를 돌았다.`,
  o:[
    { l:'① 손을 잡되 손바닥이 아니라 손목을 쥔다.', k:'gaze', dc:21,
      ok:`손바닥을 마주 잡지 않았다. 그의 손목을 쥐었다. 엄지를 뼈 사이에 넣고.<br><br>그가 손을 놓으려 한다. 놓지 못한다. 쥔 쪽이 이쪽이다. 벽을 차고 올라갔다. 그가 끌려 점검구 가장자리에서 휘청한다.<br><br>위에서 그의 얼굴을 봤다. 웃는다. 손목을 놔줬다. 그는 천장 속 어둠으로 기어가 사라졌다.`,
      ng:`손목을 쥐려는데 그가 먼저 손을 뺐다. 이쪽 손이 허공을 쥔다.<br><br>미끄러져 떨어졌다. 등이 먼저 닿았다. 숨이 멎는다.<br>위에서 그가 내려다본다. 그리고 점검구 뚜껑을 닫는다. 발소리가 등 뒤에 닿는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } },
    { l:'② 손을 마다하고 혼자 오른다.', k:'evade', dc:21,
      ok:`그 손을 보지 않았다. 벽 틈에 발가락을 걸고 뛰어올랐다. 손끝이 점검구 가장자리에 걸린다.<br><br>팔 힘으로 몸을 끌어올렸다. 그가 내민 손을 거두며 물러선다. 그 무릎 옆에 깨진 유리 조각이 한 줌 놓여 있다. 이쪽 손이 올라올 자리에.<br><br>이쪽은 그 옆으로 올라왔다. 유리 조각을 손등으로 쓸어 그쪽으로 보냈다.`,
      ng:`벽 틈이 젖어 발가락이 미끄러졌다. 손끝이 가장자리의 유리 조각을 짚었다.<br><br>손바닥이 갈렸다. 그래도 올랐다. 그는 이미 없다.<br>천장 속에 앉아 손바닥에서 유리를 뽑았다. 주먹을 쥘 수가 없다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-28, mind:-12 } },
    { l:'③ 잡는 척 당겨 끌어내린다.', k:'break', dc:21,
      ok:`손을 잡았다. 그가 밀어내기 전에 이쪽이 먼저 당겼다. 아래로. 체중을 실어서.<br><br>그가 점검구에서 떨어졌다. 이쪽 앞에 등으로. 그를 디딤돌 삼아 올랐다. 미안하지 않았다.<br><br>위에서 내려다보니 그가 일어나 쫓는 것들 쪽으로 걸어간다. 반가운 얼굴로. 처음부터 그쪽 사람이었다.`,
      ng:`당겼는데 그가 버틴다. 위에서 다리를 무언가에 걸어 두었다. 준비한 사람이다.<br><br>오히려 이쪽이 끌려 올라가다 놓쳤다. 떨어지며 점검구 모서리에 턱을 찧었다.<br>그가 위에서 웃는다. 손을 털고 뚜껑을 닫는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-12 } }
  ] },

{ at:'B1', t:'컨테이너 — 안에서 두드리는 소리',
  x:`컨테이너 하나가 따로 서 있다. 문에 맹꽁이자물쇠. 새것이다.<br><br>
    안에서 두드리는 소리가 난다. 셋. 쉬고. 셋. 쉬고. 사람 손바닥 소리다.<br>
    칠판에 적혀 있던 글자가 떠오른다. 모자라면 채울 것. 저 안이 채울 것인지 채워진 것인지 모른다.<br><br>
    자물쇠를 본다. 굵다. 그래도 쇠고리는 한 점이 제일 약하다.`,
  o:[
    { l:'① 내공을 쓴다 — 자물쇠 고리 한 점에 장을 넣는다.', k:'break', dc:21, cost:{ qi:25 },
      ok:`자물쇠를 손바닥으로 감싸 쥐었다. 내공을 모아 고리 이음매 한 점으로 보냈다.<br><br>쇠가 안에서 갈라진다. 고리가 툭 벌어졌다. 문을 열었다. 안에 사람 넷이 쭈그려 앉아 있다. 젖은 외투. 이쪽을 보고 손을 든다. 손바닥이 퉁퉁 부었다. 계속 두드렸다.<br><br>넷이 빗속으로 흩어져 뛴다. 고맙다는 말은 없다. 셋째가 돌아서서 손짓으로 말한다. 정문 말고 담.`,
      ng:`내공이 고리에 안 들어간다. 쇠가 너무 차다. 손바닥에서 튕겨 나갔다.<br><br>손목이 시큰하다. 자물쇠는 멀쩡하다. 안의 두드림이 멈췄다.<br>멈춘 게 더 무섭다. 컨테이너 안에서 무언가 문 쪽으로 기어 오는 소리가 났다. 물러났다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, mind:-16, qi:-5 } },
    { l:'② 같은 박자로 두드려 대답한다.', k:'bond', dc:20,
      ok:`손바닥으로 컨테이너 벽을 두드렸다. 셋. 쉬고.<br><br>안에서 두드림이 멈췄다가 바뀐다. 하나. 둘. 하나. 무언가 알려 주는 박자다. 컨테이너 뒤쪽 아래 모서리를 두드린다.<br>뒤로 돌아가 보니 바닥 판이 녹슬어 들떴다. 손을 넣어 들어 올렸다. 안에서 손이 하나씩 나온다.<br><br>마지막 손은 나오지 않았다. 안에서 그 손이 판을 도로 내렸다. 누군가는 남아서 숫자를 채운다.`,
      ng:`두드렸는데 안에서 대답하는 박자가 이쪽 박자보다 빠르다. 점점 빨라진다.<br><br>컨테이너 전체가 울린다. 안에 넷이 아니다. 훨씬 많다.<br>멀리서 손전등이 이쪽 소리를 향해 돈다. 손을 떼고 뛰었다. 등 뒤에서 두드림이 계속됐다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B2', t:'승강기 — 위쪽 단추 하나',
  x:`승강기 앞이다. 단추가 하나뿐이다. 위로 가는 것. 7층에서 위로.<br><br>
    문틈에 손가락을 넣으면 벌어질 것 같다. 승강로가 있으면 사다리도 있다. 내려가는 길이다.<br>
    문을 벌릴 손가락 힘은 있다. 그 아래가 어떤지는 모른다.<br><br>
    문틈으로 찬바람이 올라온다. 바람 끝에 숨소리가 섞였다.`,
  o:[
    { l:'① 손가락으로 문을 벌리고 버틴다.', k:'steady', dc:21,
      ok:`두 손 손가락을 문틈에 넣고 벌렸다. 문이 버틴다. 손가락 마디가 하얘진다.<br><br>한 뼘이 벌어졌다. 버텼다. 그 틈으로 동료들이 승강로 사다리에 옮겨 붙는다. 하나씩. 마지막으로 이쪽이 몸을 넣고 손을 뺐다. 문이 닫히며 손끝을 스쳤다.<br><br>사다리를 잡았다. 아래는 어둡다. 숨소리는 위에서 났다. 승강기 칸 위에서.`,
      ng:`벌렸는데 문이 반 뼘에서 멈췄다. 안쪽에서 무언가 문을 잡고 있다.<br><br>손가락이 틈에 끼었다. 문이 닫히려 한다. 겨우 뺐다. 손톱 둘이 까맣다.<br>문이 닫혔다. 위쪽 단추에 불이 들어온다. 누가 눌렀다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-14 } },
    { l:'② 승강로 사다리로 먼저 내려간다.', k:'evade', dc:21,
      doom:{ title:'승강로', what:'승강로 아래로 끌려 내려갑니다', dc:17, sec:50,
        text:`문을 조금 벌리고 승강로로 몸을 넣었다. 사다리를 잡고 내려갔다. 6층, 5층.<br><br>4층 문틈에서 불빛이 샌다. 그 앞을 지나는데 아래 어둠에서 손이 올라와 발목을 잡았다.<br>당긴다. 손이 사다리에서 미끄러진다. 한 칸. 두 칸.<br><br>아래는 1층이 아니다. 승강로는 1층보다 깊다. 지하로 몇 층인지 아무도 적어 두지 않았다.`,
        dieText:`그날 밤 승강기는 한 번 내려갔다. 단추가 하나뿐인데도.<br><br>정각 점검의 숫자는 맞았다. 맞지 않을 리가 없다.<br>승강로 사다리 가로대 하나에 손톱자국 다섯이 남았다.` },
      ok:`문을 조금 벌리고 승강로로 몸을 넣었다. 발이 아니라 손으로 내려갔다. 발은 사다리 옆 벽에 붙였다.<br><br>4층 근처에서 아래 어둠이 움직였다. 손이 올라온다. 사다리 가로대를 더듬는다. 발이 거기 없다. 손이 허공을 쥐고 내려간다.<br>3층 문틈에 손가락을 넣어 벌렸다. 복도로 굴러 나왔다.<br><br>문을 닫았다. 승강로 안에서 사다리 가로대를 하나씩 쥐어 오르는 소리가 난다. 천천히.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'B3', t:'침대칸 — 좁은 칸 안의 싸움',
  x:`침대칸 한 칸 안이다. 이층 침대 둘 사이 바닥이 한 사람 너비다.<br><br>
    커튼 뒤에서 누가 덮쳤다. 칸 안으로 끌려 들어왔다. 문이 닫혔다.<br>
    팔을 뻗을 데가 없다. 주먹을 내지를 거리가 없다. 상대 숨이 얼굴에 닿는다.<br><br>
    상대 얼굴이 이쪽 얼굴로 바뀌고 있다. 아주 천천히.`,
  o:[
    { l:'① 팔꿈치와 무릎만 쓴다.', k:'break', dc:21, wake:1,
      ok:`주먹은 접었다. 팔꿈치를 상대 갈비에 넣었다. 한 뼘 거리. 다음은 무릎. 다음은 이마.<br><br>칸이 좁아 상대도 못 빠진다. 이쪽은 빠질 필요가 없다. 짧게 짧게 치고 들어갔다. 상대가 침대 사다리에 등을 박고 주저앉았다. 얼굴이 반쯤 바뀐 채로 멈췄다.<br><br>주먹은 멀리서 치는 것이었다. 붙으면 팔꿈치가 주먹이고 무릎이 주먹이다. 몸 마디마다 주먹이 하나씩 있었다. 오늘 그 수를 셌다.`,
      ng:`팔꿈치를 넣는데 상대가 이쪽 팔을 침대 기둥에 끼웠다.<br><br>팔이 꺾이는 소리. 무릎을 올렸는데 상대 무릎이 먼저 올라왔다. 같은 수를 같은 때에.<br>얼굴만 아니라 수도 베끼는 것이다. 문을 차고 굴러 나왔다. 팔이 안 펴진다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'② 커튼을 뜯어 상대 얼굴을 덮는다.', k:'fix', dc:20,
      ok:`손을 뻗어 커튼을 뜯었다. 커튼을 상대 머리에 씌우고 아래로 당겨 묶었다.<br><br>얼굴이 가려지자 상대가 버둥거린다. 얼굴을 못 바꾸는 게 아니라 볼 얼굴이 없다. 그 틈에 문을 열고 나왔다.<br><br>칸 안에서 커튼 찢는 소리가 났다. 나왔을 때 그것은 이쪽 일행 중 누구의 얼굴로 나올 것이다. 다들 서로 얼굴을 봤다.`,
      ng:`커튼을 씌웠는데 상대가 커튼째 이쪽 얼굴을 감쌌다. 양손으로.<br><br>숨이 막힌다. 천 너머로 상대 얼굴이 이쪽 얼굴에 겹친다.<br>무릎으로 밀어내고 빠져나왔다. 거울을 볼 때까지 제 얼굴이 맞는지 몰랐다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-18, spirit:-16 } }
  ] },

{ at:'B', t:'길목 — 담배 피우는 둘',
  x:`지나야 할 길목에 둘이 서 있다. 담배를 피운다. 빗소리 사이로 낮게 말한다.<br><br>
    둘 다 허리에 무언가 찼다. 하나가 소리를 지르면 더 온다. 저 너머에 불 켜진 문이 있다.<br>
    둘을 한 번에 칠 수 있는 거리를 잰다. 일곱 걸음. 젖은 바닥.<br><br>
    한 사람이 담배를 바닥에 던져 밟는다. 돌아설 것이다.`,
  o:[
    { l:'① 일곱 걸음을 한 숨에 들어가 둘을 친다.', k:'break', dc:22,
      ok:`숨을 들이쉬고 멈췄다. 그 숨이 다할 때까지 들어갔다. 일곱 걸음.<br><br>돌아서던 사람 턱에 손바닥. 다른 사람이 입을 열기 전에 목울대에 손날. 둘이 벽에 기대 미끄러져 앉는다. 소리는 빗소리뿐이다.<br><br>숨을 내쉬었다. 담배 연기가 아직 길목에 떠 있다. 둘 다 숨은 쉰다. 한참 일어나지 못할 것이다.`,
      ng:`다섯 걸음째에 바닥 물웅덩이를 밟았다. 철벅.<br><br>둘이 동시에 돌아섰다. 하나는 쳤다. 하나가 소리를 질렀다. 불 켜진 문이 열린다.<br>뛰었다. 등 뒤로 문 여는 소리가 셋, 넷.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-16 } },
    { l:'② 내공을 쓴다 — 기척을 죽이고 하나씩 잠재운다.', k:'hide', dc:21, cost:{ qi:22 },
      ok:`내공을 안으로 말았다. 숨이 가늘어지고 발소리가 사라진다. 빗소리 밑으로 들어갔다.<br><br>담배 밟던 사람 뒤에 섰다. 목 뒤 한 점을 엄지로 눌렀다. 무릎이 꺾인다. 받아서 앉혔다. 다른 사람이 돌아보기 전에 그 사람도.<br><br>둘이 벽 밑에 나란히 앉아 조는 것처럼 보인다. 그대로 두고 지나갔다.`,
      ng:`기척을 죽이는 데 기가 다 들어가 손끝에 힘이 모자랐다.<br><br>엄지로 누른 사람이 쓰러지지 않고 돌아섰다. 이쪽 얼굴을 봤다.<br>둘을 다 쓰러뜨리긴 했다. 쓰러지기 전에 하나가 호루라기를 불었다. 짧게.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14, qi:-5 } }
  ] },

{ at:'B1', t:'정문 — 경비 초소',
  x:`항구 정문이다. 차단기 옆 초소에 불이 켜졌다. 『출입』 네온이 빨갛게 떤다.<br><br>
    초소 안에 경비가 앉아 졸고 있다. 발치에 개가 묶여 있다. 개는 안 존다. 이쪽을 본다. 짖지 않는다. 짖지 않는 개가 제일 무섭다.<br>
    차단기 단추는 초소 안에 있다.<br><br>
    멀리서 해무호 고동 소리가 한 번 운다. 들어오고 있다.`,
  o:[
    { l:'① 개 앞에 낮게 앉아 손을 펴 보인다.', k:'steady', dc:21,
      ok:`개 앞에 무릎을 꿇었다. 주먹을 펴서 손바닥을 보였다. 주먹 쓰는 사람이 손을 펴는 일은 드물다.<br><br>개가 냄새를 맡는다. 손에서 피 냄새와 비 냄새가 난다. 개가 낑 하고 앉는다. 묶인 줄이 느슨해진다.<br>그 옆으로 초소 문을 열고 단추를 눌렀다. 차단기가 올라간다. 경비는 졸고 있다.<br><br>개가 끝까지 짖지 않았다. 나가면서 돌아보니 개가 이쪽을 보며 꼬리를 한 번 쳤다.`,
      ng:`앉았는데 개가 이쪽 손을 물었다. 소리 없이. 물고 놓지 않는다.<br><br>주먹을 쥘 수가 없다. 개 이빨이 손바닥을 관통했다. 다른 손으로 개 턱 밑을 눌러 겨우 뗐다.<br>경비가 눈을 떴다. 이쪽 피 흘리는 손을 본다. 전화기를 든다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 초소 창을 깨고 단추를 친다.', k:'break', dc:21,
      ok:`개가 일어서기 전에 초소 창에 장을 붙였다. 안으로 깨지게.<br><br>유리가 초소 안으로 쏟아진다. 경비가 놀라 의자째 넘어진다. 깨진 창으로 팔을 넣어 단추를 쳤다. 차단기가 올라간다.<br>개가 그제야 짖는다. 묶인 줄 끝까지 달려와 멈춘다. 다들 차단기 밑으로 뛰었다.<br><br>경비가 일어나 전화를 건다. 빗속에서 고동이 다시 운다.`,
      ng:`창을 쳤는데 유리가 아니라 두꺼운 아크릴이다. 손바닥이 튕겼다.<br><br>경비가 깼다. 개가 줄을 끊을 듯 당긴다. 짖는다. 이제야.<br>경비가 단추 대신 다른 단추를 눌렀다. 항구 전체에 조명이 켜진다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-16 } }
  ] },

{ at:'B2', t:'운동실 — 매달린 샌드백',
  x:`운동실 문이 열려 있다. 안에 샌드백 하나가 천장에 매달렸다. 혼자 천천히 돈다.<br><br>
    바닥에 매트가 깔렸다. 벽 시간표에 적혀 있다. 7층 환자 운동 시간 03:00. 지금 2시 58분이다.<br>
    샌드백을 보면 손이 근질거린다. 저 샌드백은 가죽이 사람 피부색이다. 아래쪽이 조금 부풀었다 꺼진다.<br><br>
    숨 쉬는 것처럼.`,
  o:[
    { l:'① 샌드백을 친다.', k:'break', dc:21,
      ok:`세게 치지 않았다. 손바닥으로 한 번 밀었다. 속이 어떤지 보려고.<br><br>손바닥에 울림이 돌아온다. 모래가 아니다. 단단한 것과 무른 것이 겹겹이. 샌드백이 흔들리다 멈춘다. 부풀던 것도 멈췄다.<br>천장 고리에 매달린 쇠사슬을 봤다. 고리에 열쇠 꾸러미가 걸려 있다. 손을 뻗어 땄다.<br><br>3시 정각에 운동실 불이 켜졌다. 이쪽은 이미 복도에 있었다. 등 뒤에서 샌드백 치는 소리가 시작됐다. 여럿이서.`,
      ng:`쳤는데 샌드백 안에서 소리가 났다. 낮은 신음.<br><br>손이 멈췄다. 샌드백이 이쪽으로 돌아온다. 가죽 표면에 손바닥 자국이 안쪽에서 찍혀 나온다.<br>뒷걸음질 쳤다. 정각이 되며 불이 켜졌다. 문 앞에 환자들이 줄을 서 있다. 이쪽을 보고 손을 쥔다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } },
    { l:'② 샌드백을 내리고 지퍼를 연다.', k:'gaze', dc:21,
      ok:`쇠사슬 고리를 풀어 샌드백을 매트에 눕혔다. 무겁다. 지퍼가 있다.<br><br>열었다. 안에 환자복이 둘둘 말려 가득하다. 수십 벌. 모두 이름표가 떼어졌다. 맨 아래에서 무언가 딱딱한 게 잡힌다. 손전등과 계단실 열쇠다.<br><br>지퍼를 닫고 도로 매달았다. 3시 정각에 운동실 불이 켜졌다. 샌드백이 다시 천천히 돈다. 숨 쉬는 것처럼.`,
      ng:`지퍼를 여는데 안에서 지퍼를 잡았다. 안쪽에서.<br><br>지퍼가 도로 닫힌다. 손가락이 끼었다. 빼니 손톱 밑이 까맣다.<br>3시. 불이 켜진다. 샌드백을 내려놓은 이쪽을 간호사가 문간에서 본다. 딸깍.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B3', t:'지붕 — 앞 칸으로',
  x:`앞 칸 문이 용접돼 있다. 안에서 누가 막았다.<br><br>
    연결 통로 위 사다리가 지붕으로 이어진다. 지붕으로 가면 앞 칸에 닿는다. 비가 지붕을 때린다. 바람이 사람을 지운다.<br>
    몸은 가볍다. 지붕 위에서도 설 수 있다. 문제는 지붕 위에서 열차가 무엇을 지나느냐다.<br><br>
    멀리 어둠 속에 더 검은 구멍이 보인다. 터널이다.`,
  o:[
    { l:'① 지붕을 기어 앞 칸 사다리까지 간다.', k:'evade', dc:22,
      doom:{ title:'지붕 위', what:'터널 입구에 쓸려 갑니다', dc:18, sec:45,
        text:`지붕에 엎드려 기었다. 손가락을 지붕 이음매에 걸며. 한 칸. 두 칸.<br><br>터널이 다가온다. 열차 지붕과 터널 천장 사이가 얼마인지 모른다. 엎드리면 되는 줄 알았다.<br>다 와서 사다리를 잡으려는데 앞 칸 지붕 위에 누가 서 있다. 이쪽 손을 밟는다.<br><br>손이 이음매에서 빠졌다. 몸이 지붕에서 반쯤 뜬다. 터널 입구가 바로 앞이다.`,
        dieText:`터널을 빠져나온 열차 지붕에 빗물만 흘렀다.<br><br>앞 칸 사다리 맨 위 가로대에 손자국이 하나 남았다. 비가 지울 때까지.<br>방송이 다음 역을 부른다. 서지 않는다.` },
      ok:`지붕에 엎드려 기었다. 손가락을 이음매에 걸며. 터널이 다가오는 걸 등으로 느꼈다.<br><br>앞 칸 사다리를 잡는 순간 지붕 위에 누가 서 있는 게 보였다. 이쪽 손을 밟으려 발을 든다. 그 발목을 쳤다. 그것이 지붕에서 미끄러진다.<br>사다리를 타고 연결 통로로 떨어지듯 내려왔다. 머리 위로 터널이 덮쳤다. 굉음.<br><br>지붕 위에 섰던 것은 내려오지 않았다. 터널은 사람 키만큼의 틈도 주지 않았다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 내공을 쓴다 — 지붕 환기구를 뚫고 내려간다.', k:'break', dc:21, cost:{ qi:24 },
      ok:`지붕 끝까지 가지 않았다. 앞 칸 첫머리 지붕에 환기구 덮개가 있다. 거기까지만 기었다.<br><br>덮개에 손바닥을 붙이고 내공을 한 번에 보냈다. 나사가 다 튀어 나갔다. 덮개를 젖히고 안으로 떨어졌다.<br>머리 위로 터널이 덮친다. 환기구 구멍으로 굉음과 빗물이 쏟아진다.<br><br>앞 칸 승객들이 일제히 이쪽을 본다. 다 같은 얼굴이다. 한 사람만 다르다. 그 사람이 일행이다.`,
      ng:`손바닥을 붙였는데 지붕이 젖어 기가 미끄러졌다. 덮개가 반만 들렸다.<br><br>터널이 온다. 반 들린 틈으로 몸을 밀어 넣었다. 등이 덮개에 긁힌다. 다리가 아직 밖이다.<br>터널 바람이 다리를 잡아당긴다. 동료가 안에서 끌어당겼다. 신발 한 짝은 터널이 가졌다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-14, qi:-5 } }
  ] },

{ at:'B', t:'쉬는 자리 — 부은 마디',
  x:`손을 폈다. 마디가 다 부었다. 오늘 문을 쳤고 유리를 쳤고 사람을 쳤다.<br><br>
    가운뎃손가락 마디 하나가 제자리를 비켜 앉았다. 주먹을 쥐면 그 손가락만 따로 논다.<br>
    권사의 주먹이 반쯤만 쥐어지면 반쯤 다친다. 이쪽이.<br><br>
    밤은 아직 길다.`,
  o:[
    { l:'① 마디를 맞춰 넣는다.', k:'heal', dc:20,
      ok:`손가락을 잡고 숨을 셋 셌다. 셋에 당겼다가 밀어 넣었다.<br><br>똑. 소리가 났다. 눈앞이 잠깐 하얬다. 손가락이 제자리에 앉는다. 옆 손가락에 천으로 묶었다.<br><br>주먹을 쥐어 봤다. 다 쥐어진다. 아프다. 아파도 쥐어지면 쓴다.`,
      ng:`당기는데 손가락이 미끄러졌다. 반만 들어갔다.<br><br>이제 더 이상한 쪽으로 굽었다. 다시 할 엄두가 안 난다.<br>천으로 감고 주먹 대신 손바닥으로 싸우기로 했다. 그것도 아프다.`,
      win:{ exp:14, dream:1, hp:8 }, lose:{ hp:-22, mind:-12 } },
    { l:'② 주먹을 접고 손바닥으로 싸우는 법을 다시 짠다.', k:'break', dc:21, wake:1,
      ok:`주먹을 쥐지 않았다. 손을 펴서 벽에 댔다. 손바닥 뿌리로 벽을 밀어 봤다. 마디가 안 닿는다.<br><br>손바닥 뿌리, 손날, 손가락 끝을 모은 끝. 하나씩 벽에 대 봤다. 다친 마디를 피해 갈 데가 이렇게 많다.<br>쉬는 동안 손으로 백 번 벽을 밀었다. 소리가 안 났다.<br><br>주먹이 권사의 전부인 줄 알았다. 손은 주먹 말고도 여러 모양이다. 다친 손가락 하나가 나머지 모양을 다 꺼내 줬다.`,
      ng:`손바닥 뿌리로 벽을 미는데 손목이 꺾였다. 주먹으로만 버틴 손목이라 손바닥 힘을 모른다.<br><br>손목까지 붓기 시작했다. 이제 손 전체가 쓸모가 없다.<br>밤새 손을 품에 안고 앉아 있었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B', t:'마지막 문 — 쇠 빗장',
  x:`나가는 문이다. 바깥에서 쇠 빗장이 걸렸다. 문틈으로 빗장 그림자가 보인다. 팔뚝만 하다.<br><br>
    등 뒤로 쫓는 것들이 온다. 시계는 마지막 칸 앞이다.<br>
    문을 본다. 문짝은 철판이다. 철판 너머 빗장까지 한 뼘.<br><br>
    한 뼘이면 권사의 거리다.`,
  o:[
    { l:'① 내공을 다 쓴다 — 철판 너머 빗장으로 장을 보낸다.', k:'break', dc:22, cost:{ qi:30 }, wake:1,
      ok:`빗장 그림자가 걸친 자리에 손바닥을 붙였다. 철판에 대고 빗장까지의 한 뼘을 쟀다.<br><br>내공을 남김없이 모아 보냈다. 철판을 치는 게 아니라 철판을 지나 그 뒤를 치게. 철판은 울리지 않았다. 문 너머에서 빗장 꺾이는 소리가 났다.<br>문을 밀었다. 빗속이다. 다들 빠져나갔다.<br><br>손바닥이 닿은 데가 아니라 그 너머에서 힘이 끝났다. 거리를 정해서 보냈다. 앞을 막은 것은 이제 막은 것이 아니다. 그 뒤가 과녁이다.`,
      ng:`보낸 힘이 철판에서 끝났다. 철판이 움푹 들어가며 크게 울렸다.<br><br>빗장은 그대로다. 내공이 바닥이다.<br>등 뒤 발소리가 빨라진다. 다들 문을 두드렸다. 열린 건 바깥에서 누가 빗장을 뺐을 때다. 누군지는 못 봤다. 빗속에 우산 하나가 멀어졌다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-28, spirit:-16, qi:-5 } },
    { l:'② 문을 등지고 서서 쫓는 것들을 받는다.', k:'steady', dc:21,
      ok:`문은 동료들에게 맡겼다. 돌아서서 마보를 디뎠다. 발가락으로 바닥을 물었다.<br><br>첫째가 왔다. 받아서 옆 벽에 넘겼다. 둘째. 셋째. 한 걸음도 안 물러섰다. 등 뒤에서 철판 긁는 소리, 빗장 빠지는 소리.<br>누가 등을 잡아당겼다. 동료다. 문밖으로 같이 굴렀다.<br><br>문이 닫혔다. 안에서 문을 친다. 철판이 운다. 열리지 않는다.`,
      ng:`셋째까지 받았다. 넷째가 무릎을 찼다. 무릎이 꺾였다.<br><br>꺾인 채로 버텼다. 다섯째가 어깨를 문다. 사람 이빨이다.<br>동료들이 문을 열고 이쪽 허리를 끌었다. 어깨에 이빨 자국이 둥글게 남았다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-14 } },
    { l:'③ 경첩 옆 벽을 쳐서 문틀째 뗀다.', k:'break', dc:21,
      ok:`문이 아니라 문틀이 박힌 벽을 봤다. 벽돌이다. 젖었다. 젖은 벽돌 줄눈은 무르다.<br><br>경첩 옆 벽돌을 쳤다. 줄눈이 부서진다. 다섯 번. 문틀이 벽에서 들뜬다. 어깨로 밀었다.<br>문이 빗장째 문틀째 밖으로 넘어갔다.<br><br>빗장은 끝까지 잠겨 있었다. 잠긴 문이 열렸다.`,
      ng:`벽돌이 생각보다 단단했다. 줄눈이 아니라 벽돌을 쳤다.<br><br>마디 둘이 갈라졌다. 벽돌에 피 묻은 주먹 자국.<br>문틀은 반 치 들떴다. 다들 매달려 밀었다. 열리기까지 발소리가 너무 가까웠다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B', t:'막다른 데 — 쇠파이프',
  x:`막다른 데다. 쫓아온 것들이 쇠파이프를 들었다. 셋.<br><br>
    파이프는 길다. 주먹은 짧다. 파이프 끝이 닿는 데에서는 주먹이 안 닿는다.<br>
    주먹은 그 사이를 안다. 파이프 끝과 파이프 쥔 손 사이. 거기는 파이프가 제일 약하다.<br><br>
    첫째가 파이프를 어깨 위로 든다.`,
  o:[
    { l:'① 파이프가 내려오는 안쪽으로 들어간다.', k:'break', dc:22, wake:1,
      ok:`파이프가 내려오는 순간 물러서지 않고 들어갔다. 파이프 끝이 아니라 쥔 손 쪽으로.<br><br>파이프가 등 뒤 허공을 친다. 이쪽은 이미 첫째 가슴 앞이다. 거기서는 파이프가 그냥 쇠막대다. 팔꿈치를 넣었다. 둘째도 같은 수로. 셋째는 파이프를 버리고 맨손으로 왔다. 그건 이쪽 거리다.<br><br>긴 것에서 물러나는 게 맞는 줄 알았다. 긴 것일수록 안쪽이 넓다. 무서운 쪽으로 한 걸음 더 가는 것. 몸이 그걸 수로 바꿨다.`,
      ng:`들어갔는데 첫째가 파이프를 짧게 고쳐 쥐었다. 안쪽이 없어졌다.<br><br>파이프 끝이 아니라 손잡이 쪽이 갈비를 쳤다. 숨이 끊긴다.<br>둘째 파이프가 등을 친다. 겨우 벽 쪽으로 굴렀다. 일어나는 데 셋을 셌다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-32, mind:-12 } },
    { l:'② 첫 파이프를 빼앗아 쓴다.', k:'fix', dc:21,
      ok:`파이프가 내려오는 걸 두 손으로 잡았다. 비틀었다. 손목을 꺾는 쪽으로.<br><br>첫째가 파이프를 놓친다. 이제 이쪽 손에 있다. 무기를 안 드는 사람이 무기를 들었다. 둘째 파이프를 그것으로 받았다. 쇳소리.<br><br>파이프를 바닥에 던졌다. 원래 손이 편하다. 그래도 받는 데는 쓸 만했다.`,
      ng:`잡았는데 파이프가 젖어 손에서 빠졌다. 손바닥이 쓸렸다.<br><br>빠진 파이프가 다시 돌아와 팔뚝을 쳤다. 뼈가 운다.<br>팔을 늘어뜨린 채 물러섰다. 다른 손으로만 버텼다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'③ 벽을 차고 천장 배관으로 오른다.', k:'evade', dc:21,
      ok:`옆 벽을 한 번 차고 맞은편 벽을 또 찼다. 좁은 데라서 된다. 천장 배관을 잡고 몸을 끌어올렸다.<br><br>파이프 셋이 이쪽이 있던 데를 친다. 이쪽은 배관 위다. 배관을 타고 셋의 머리 위를 지나 그 뒤에 떨어졌다. 셋이 돌아서는 사이 동료들이 빠져나왔다.<br><br>파이프 하나가 날아와 배관을 치고 떨어졌다. 그 소리를 등 뒤에 두고 뛰었다.`,
      ng:`두 번째 벽에서 발이 미끄러졌다. 젖은 벽이다.<br><br>떨어지는 등에 파이프가 닿았다. 바닥에 처박혔다.<br>동료들이 끌어냈다. 등이 펴지지 않는다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-28, mind:-14 } }
  ] }

]);

// ------------------------------------------
// 폭파공 · 자원 없음
// ------------------------------------------
kJob('blaster', 'B', [

{ at:'B', t:'젖은 화약 — 비 오는 밤',
  x:`화약 주머니를 열었다. 눅눅하다. 손가락으로 비비면 뭉친다.<br><br>
    폭파공에게 비 오는 밤은 제일 나쁜 밤이다. 화약이 젖고 심지가 젖고 손이 젖는다.<br>
    젖은 화약은 안 터지거나 한꺼번에 터진다. 어느 쪽일지는 터져 봐야 안다.<br><br>
    뒤에서 쫓는 것들이 온다. 말릴 시간이 많지 않다.`,
  o:[
    { l:'① 주머니를 배에 붙여 체온으로 말린다.', k:'steady', dc:20,
      ok:`주머니를 셔츠 안, 배 위에 붙였다. 젖은 옷 안쪽에서도 배는 따뜻하다.<br><br>걸으면서 말렸다. 한 시간쯤 지나 꺼내 보니 반은 보슬보슬하다. 반은 그대로다.<br>보슬한 반을 따로 쌌다. 반이면 문 두 개다.<br><br>배에 검은 물이 들었다. 화약 다루는 사람 배는 원래 그렇다.`,
      ng:`땀이 났다. 쫓기는 몸은 식은땀이 난다.<br><br>꺼내 보니 화약이 아까보다 더 뭉쳤다. 배에 검은 물이 줄줄 흐른다.<br>반의 반만 건졌다. 그걸로 열 수 있는 문은 하나다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 젖은 화약을 단단히 다져 느린 불로 쓴다.', k:'fix', dc:21, wake:1,
      ok:`말리지 않았다. 젖은 화약을 종이에 넣고 손가락으로 꾹꾹 다졌다. 대롱처럼 단단하게.<br><br>끝에 불을 대 봤다. 안 터진다. 탄다. 느리게. 한 치에 숨 열. 터지는 화약이 아니라 기어가는 불이 됐다.<br>그 대롱 끝에 마른 화약 한 꼬집을 붙였다. 심지보다 늦고 심지보다 확실하다.<br><br>젖은 화약은 버리는 것인 줄 알았다. 젖은 대로 쓸 데가 있다. 손이 화약의 성질 하나를 더 쥐었다.`,
      ng:`다지는데 종이가 젖어 찢어졌다. 화약이 손에 들러붙는다.<br><br>불을 대 봤다. 한 번 퍽 하고 손 앞에서 튀었다. 손등이 까맣다.<br>눈썹 끝이 탄 냄새가 난다. 쫓는 것들도 맡았을 것이다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-24, spirit:-12 } }
  ] },

{ at:'B1', t:'3번 창고 — 기둥에 감긴 전선',
  x:`창고 기둥마다 무언가 감겨 있다. 기름종이 꾸러미. 그 위로 전선.<br><br>
    한눈에 안다. 화약이다. 이 창고를 통째로 지울 만큼.<br>
    전선이 모이는 데에 자명종 시계가 하나 있다. 바늘이 5시에 맞춰져 있다. 해무호는 5시 10분에 온다. 그 전에 다 없어지게 되어 있다.<br><br>
    시계 초침 소리가 빗소리보다 크게 들린다.`,
  o:[
    { l:'① 시계 태엽을 멈춘다.', k:'gaze', dc:22,
      doom:{ title:'멈춘 시계', what:'창고 기둥이 터지기 직전입니다', dc:18, sec:45,
        text:`시계 뒤 태엽 손잡이를 잡고 멈췄다. 초침이 섰다.<br><br>그 순간 시계 안에서 딸깍 소리가 났다. 바늘이 아니라 바닥판 밑에서.<br>초침이 멈추면 이어지게 해 둔 것이다. 시계를 만지는 사람을 위한 장치다. 이 일을 아는 사람을 위한.<br><br>기둥 쪽 꾸러미에서 쉬익 소리가 난다. 하나. 둘.`,
        dieText:`해무호는 5시 10분에 들어왔다. 3번 창고 자리에 연기만 피어 있었다.<br><br>칠판의 숫자는 다섯이었다. 채울 필요가 없었다.<br>잿더미 속에서 자명종 시계 하나가 멀쩡했다. 초침은 서 있었다.` },
      ok:`시계를 바로 만지지 않았다. 뒷면부터 봤다. 바닥판 밑으로 가는 선 하나가 다른 선보다 새것이다.<br><br>그 선을 먼저 손톱으로 벗겨 떼어 냈다. 그다음 태엽을 멈췄다. 초침이 섰다. 아무 일도 없다.<br><br>숨을 내쉬었다. 시계를 멈추는 사람을 노린 덫이었다. 이 일을 아는 사람을 노린 덫. 만든 사람도 폭파공이다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 전선을 따라가 뿌리를 찾는다.', k:'sense', dc:21, wake:1,
      ok:`시계는 두고 전선을 손가락으로 따라갔다. 기둥 하나, 둘, 셋. 꼬는 방향이 다 같다. 오른쪽. 매듭은 늘 두 번.<br><br>그런데 넷째 기둥만 왼쪽으로 꼬였다. 매듭이 세 번이다. 다른 손이 만든 것이다. 그 꾸러미가 진짜고 나머지는 미끼다.<br>넷째 꾸러미 전선만 끊었다. 시계는 계속 간다. 5시에 아무 일도 없을 것이다.<br><br>남의 전선은 남의 글씨 같다. 버릇이 다 묻어 있다. 이제 손이 남의 버릇을 읽는다.`,
      ng:`따라가는데 전선이 기둥 뒤에서 바닥 밑으로 들어간다. 손가락을 넣을 수 없다.<br><br>어디로 가는지 모른다. 초침 소리가 아까보다 빨라진 것 같다. 기분 탓일 것이다.<br>결국 시계로 돌아왔다. 남은 시간이 아까보다 적다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'③ 꾸러미에서 화약만 덜어 낸다.', k:'fix', dc:21,
      ok:`기둥 꾸러미 하나를 칼끝으로 살짝 갈랐다. 화약을 손으로 퍼냈다. 숨을 안 쉬었다.<br><br>반을 덜어 이쪽 주머니에 넣었다. 꾸러미는 도로 쌌다. 터져도 기둥 하나 금 가는 정도다.<br>다섯 기둥을 다 그렇게 했다. 주머니가 무겁다.<br><br>남이 이쪽을 지우려고 쌓은 화약으로 이쪽 문을 열 것이다.`,
      ng:`세 번째 꾸러미를 가르는데 안에 유리병이 있다. 화약이 아니다. 기름이다.<br><br>병이 칼끝에 깨졌다. 손이 기름에 젖는다. 바닥으로 번진다.<br>시계 초침 소리가 계속 간다. 기름 젖은 손으로 다음 꾸러미를 만질 수가 없다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B2', t:'복도 — 산소통',
  x:`복도 끝에 산소통이 셋 서 있다. 바퀴 달린 받침대. 초록 칠이 벗겨졌다.<br><br>
    산소통을 보면 손이 먼저 오그라든다. 저건 터지면 쇠가 날아간다. 날아간 쇠는 사람보다 빠르다.<br>
    복도 끝 방화문이 잠겼다. 저 문을 치면 열린다. 치는 소리로 7층이 다 깬다.<br><br>
    정각까지 십오 분이다.`,
  o:[
    { l:'① 산소통을 굴려 방화문 걸쇠를 친다.', k:'break', dc:21,
      ok:`터뜨리지 않았다. 산소통 하나를 받침대에서 내려 옆으로 눕혔다. 무겁다. 쇠뭉치다.<br><br>복도 끝 경사를 따라 굴렸다. 산소통이 방화문 걸쇠 자리에 정확히 박혔다. 둔한 소리 한 번. 걸쇠가 휘었다.<br>소리는 컸지만 한 번이었다. 한 번은 무언가 떨어진 소리로 들린다.<br><br>문을 밀었다. 열렸다. 산소통 밸브가 무사한지 먼저 봤다. 무사하다.`,
      ng:`굴렸는데 산소통이 비스듬히 갔다. 벽에 부딪혀 튀었다.<br><br>밸브 쪽이 바닥을 긁는다. 쉬익. 가스가 샌다. 손으로 밸브를 잠갔다. 손가락이 하얗게 얼었다.<br>복도 문들이 하나씩 열린다. 간호사들이 소리 난 쪽을 본다. 계수기를 들고.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 밸브를 살짝 풀어 휘파람 소리로 꾄다.', k:'hide', dc:20,
      ok:`산소통 하나를 복도 반대편 끝으로 밀어 두고 밸브를 아주 조금 풀었다. 휘이. 가는 소리가 난다.<br><br>간호사실 문이 열린다. 직원들이 그 소리 쪽으로 간다. 하나, 둘. 뭔지 보러.<br>그사이 이쪽은 간호사실 안으로 들어갔다. 벽에 열쇠가 걸려 있다. 방화문 열쇠.<br><br>나올 때 휘파람 소리는 아직 났다. 직원들이 산소통 앞에 둘러서서 그걸 세고 있다.`,
      ng:`밸브를 너무 풀었다. 휘이가 아니라 쉬이익.<br><br>소리가 커서 병동 전체가 깼다. 환자들이 침대에서 일어나 복도로 나온다. 다들 소리 쪽이 아니라 이쪽을 본다.<br>밸브를 잠그고 물러났다. 직원 셋이 이쪽 앞에 섰다. 딸깍.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-16 } }
  ] },

{ at:'B3', t:'연결기 — 뒤 칸을 떼기',
  x:`8호차와 9호차 사이 연결기 앞이다. 바닥 철판 아래로 쇠 고리와 굵은 핀이 보인다.<br><br>
    9호차에서 그것이 온다. 얼굴을 바꾸는 손님. 통로 유리 너머로 천천히.<br>
    핀을 본다. 핀 하나만 빠지면 9호차는 여기서 떨어진다. 저것을 싣고.<br><br>
    열차가 이음매를 넘을 때마다 핀이 위아래로 한 치씩 논다.`,
  o:[
    { l:'① 핀에 작은 꾸러미를 붙이고 이음매에 맞춰 터뜨린다.', k:'break', dc:22, wake:1,
      ok:`핀 머리에 손톱만 한 꾸러미를 붙였다. 심지는 짧게. 그리고 덜컹 소리를 셌다. 덜컹, 하나, 둘, 셋, 덜컹.<br><br>핀이 위로 뜨는 박자에 맞춰 불을 붙였다. 셋째 덜컹에 핀이 떠오른 순간 터졌다. 핀이 위로 날아간다. 고리가 풀렸다.<br>9호차가 천천히 멀어진다. 유리 너머 그것이 이쪽을 본다. 얼굴을 바꿀 생각도 안 하고.<br><br>가만히 있는 것만 터뜨렸다. 움직이는 것은 그 박자 안에서 터뜨린다. 손이 이제 열차 박자로 심지를 자른다.`,
      ng:`박자를 하나 놓쳤다. 핀이 내려앉은 순간 터졌다.<br><br>핀이 아니라 철판이 들렸다. 파편이 정강이에 박혔다. 고리는 그대로다.<br>9호차 문이 열렸다. 그것이 연결 통로로 나온다. 철판 틈으로 선로가 지나간다. 다리를 끌고 8호차로 들어갔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-30, spirit:-12 } },
    { l:'② 엎드려 손으로 핀을 뽑는다.', k:'fix', dc:21,
      ok:`철판 틈에 팔을 넣었다. 선로 바람이 팔을 잡아당긴다. 핀 머리를 쥐었다.<br><br>덜컹. 핀이 뜰 때 같이 당겼다. 한 치. 덜컹. 또 한 치. 셋째에 빠졌다. 9호차가 떨어져 나간다.<br><br>팔을 빼고 일어났다. 화약은 하나도 안 썼다. 쓸 데가 아직 많다.`,
      ng:`핀을 쥐었는데 덜컹하는 순간 핀이 내려오며 손가락을 찧었다.<br><br>손을 뺐다. 손톱 둘이 갈라졌다.<br>9호차 문이 열리는 소리. 그것이 연결 통로로 나온다. 핀은 그대로다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B', t:'통로 — 발목 높이의 철사',
  x:`통로 발목 높이에 철사가 걸려 있다. 가늘다. 빗물이 맺혀야 보인다.<br><br>
    철사를 보면 끝부터 본다. 철사는 끝에 무엇이 달렸는지가 전부다.<br>
    한쪽 끝은 벽 고리에 묶였다. 다른 쪽 끝은 어둠 속으로 간다.<br><br>
    일행 중 하나가 발을 들고 있다. 철사를 못 봤다.`,
  o:[
    { l:'① 철사 끝을 따라가 본다.', k:'gaze', dc:21,
      ok:`일행 어깨를 잡아 세웠다. 철사를 따라 어둠 속으로 손을 더듬었다.<br><br>끝에 깡통이 있다. 안에 자갈. 철사가 당겨지면 깡통이 떨어져 소리를 낸다. 터지는 게 아니라 알리는 것이다. 누구에게.<br><br>깡통을 조용히 내려 바닥에 눕혔다. 철사를 넘어갔다. 알리는 덫이 있다는 건 들으러 오는 사람이 있다는 뜻이다.`,
      ng:`따라가는데 철사가 두 갈래로 갈라진다. 하나를 따라가는 사이 다른 하나를 일행이 건드렸다.<br><br>어둠 속에서 깡통이 떨어지는 소리. 자갈이 쏟아진다.<br>멀리서 문 열리는 소리가 대답한다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 다들 한 사람씩 철사를 넘게 한다.', k:'evade', dc:20,
      ok:`철사 위에 손바닥을 대고 표시했다. 다들 그 손을 보고 넘었다. 하나씩. 무릎을 높이.<br><br>마지막에 이쪽이 넘었다. 손을 떼는 순간 철사가 떤다. 바람이다. 바람에 떨 정도로 팽팽하다.<br><br>넘고 나서 돌아보니 철사가 하나 더 있다. 머리 높이에. 그건 아까 다들 숙인 덕에 안 닿았다.`,
      ng:`셋째가 넘을 때 뒤꿈치가 철사를 스쳤다.<br><br>어둠 속에서 무언가 툭 떨어졌다. 깡통이 아니다. 화약 냄새.<br>다들 엎드렸다. 터지지 않았다. 불발이다. 젖어서. 비가 이번엔 이쪽 편을 들었다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-20, spirit:-18 } },
    { l:'③ 철사를 풀어 쫓는 쪽으로 돌려 건다.', k:'fix', dc:21,
      ok:`다들 넘긴 뒤 철사를 벽 고리에서 풀었다. 끝에 달린 것을 조심히 떼어 왔다. 작은 꾸러미다. 화약 냄새.<br><br>통로 뒤쪽, 우리가 지나온 쪽에 같은 높이로 다시 걸었다. 꾸러미도 다시 달았다. 젖은 심지 대신 이쪽 마른 심지로.<br><br>한참 가다 뒤에서 둔한 소리가 났다. 쫓던 것들이 걸음을 멈추는 소리가 이어졌다.`,
      ng:`풀다가 철사가 손가락을 갈랐다. 피가 철사를 타고 흐른다.<br><br>다시 걸 시간이 없다. 발소리가 온다. 철사를 들고 뛰었다.<br>손가락 피가 바닥에 점점이 떨어진다. 이쪽 길을 그린다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B1', t:'부두 — 기름 드럼',
  x:`부두 길목에 기름 드럼이 줄지어 섰다. 열 개. 녹슬었다.<br><br>
    뒤에서 차 한 대가 불을 끈 채 온다. 바퀴가 웅덩이를 가르는 소리.<br>
    드럼 열 개를 본다. 다 터뜨리면 부두 하나가 없어진다. 하나만 터뜨리면 길 하나가 없어진다.<br><br>
    차 소리가 모퉁이 하나 너머다.`,
  o:[
    { l:'① 드럼 하나만 터뜨려 길을 막는다.', k:'break', dc:21,
      ok:`줄 맨 끝 드럼 하나를 골랐다. 옆 드럼과 한 뼘 떨어진 것. 뚜껑 밑에 화약 한 꼬집을 넣고 심지를 길게 끌었다.<br><br>붙이고 뛰었다. 퍽. 불기둥이 선다. 옆 드럼들은 그을리기만 했다. 길이 불로 막혔다.<br>모퉁이를 돌아온 차가 불 앞에서 선다. 문이 열리고 우비들이 내린다. 불 너머를 본다. 이쪽은 이미 다음 골목이다.<br><br>하나만 터뜨리려고 하나를 떼어 놓은 사람이 누군지는 모른다. 고마웠다.`,
      ng:`하나를 터뜨렸는데 옆 드럼에 금이 가 있었다. 기름이 새고 있었다.<br><br>불이 옆으로 옮는다. 두 개, 세 개. 부두 전체가 붉어진다.<br>열기에 떠밀려 뛰었다. 등이 뜨겁다. 차는 멈췄지만 이쪽 길도 같이 막혔다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-14 } },
    { l:'② 빈 드럼을 굴려 차 앞에 보낸다.', k:'steady', dc:20,
      ok:`드럼을 두드려 봤다. 셋째가 비었다. 소리가 다르다. 빈 것을 눕혀 굴렸다. 모퉁이로.<br><br>차가 모퉁이를 돌다 드럼을 받았다. 쿵. 바퀴가 드럼을 타고 오르다 미끄러진다. 차가 옆으로 서 버렸다.<br><br>화약은 하나도 안 썼다. 빈 드럼도 길을 막는다. 터지지 않는 것으로 막는 게 제일 조용하다.`,
      ng:`빈 줄 알았던 드럼에 기름이 반 남아 있었다. 무겁다. 안 구른다.<br><br>밀다가 손이 미끄러져 드럼이 이쪽 발 위로 쓰러졌다. 발등이 눌렸다.<br>차 불이 켜졌다. 이쪽 다리를 비춘다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B2', t:'병실 문 — 바깥 자물쇠',
  x:`병실 문이 바깥에서 잠겼다. 안쪽에는 열쇠 구멍만 있다. 안에서 열라고 만든 구멍이 아니다. 들여다보라고 만든 구멍이다.<br><br>
    화약 쓰는 눈에는 열쇠 구멍이 화약 한 꼬집 들어갈 자리로 보인다.<br>
    문제는 소리다. 이 층은 소리 하나에 숫자를 다시 센다.<br><br>
    주머니에 성냥이 한 갑 있다. 화약은 아끼고 싶다.`,
  o:[
    { l:'① 성냥 머리를 긁어모아 구멍에 다진다.', k:'fix', dc:21,
      ok:`성냥 스무 개의 머리를 손톱으로 긁어 가루로 모았다. 열쇠 구멍 안에 넣고 철사로 다졌다.<br><br>성냥 하나 남은 걸로 불을 댔다. 퍽, 하고 작게. 기침 소리만 했다. 자물쇠 안에서 무언가 녹아 붙었다가 떨어진다. 문이 반 치 밀린다.<br><br>성냥갑이 비었다. 화약은 그대로다. 문은 열렸다.`,
      ng:`성냥 머리 가루가 손 땀에 젖었다. 다져지지 않고 뭉친다.<br><br>불을 대자 칙 소리만 내고 꺼졌다. 열쇠 구멍에서 연기가 샌다.<br>복도에서 딸깍 소리가 멈췄다. 연기 냄새를 맡은 것이다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 화약 한 꼬집으로 자물쇠를 날린다.', k:'break', dc:21,
      ok:`화약 한 꼬집을 구멍에 넣고 베개로 문을 덮었다. 베개 위로 몸을 붙였다.<br><br>퍽. 베개가 소리를 먹었다. 깃털이 날린다. 자물쇠가 문 밖으로 떨어졌다.<br>복도로 나가 깃털을 털었다. 소리는 복도 끝까지 안 갔다. 베개 하나가 화약 한 꼬집을 숨겼다.`,
      ng:`베개를 덮었는데 너무 얇다. 퍽 소리가 그대로 복도로 간다.<br><br>자물쇠는 떨어졌다. 동시에 복도 문들이 열린다. 다들 나와서 숫자를 센다. 이쪽 방부터.<br>열린 문 앞에 서서 세어졌다. 깃털이 머리에 붙어 있다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B3', t:'화물칸 — 째깍거리는 상자',
  x:`화물칸이다. 짐 상자들이 천장까지 묶였다. 열차가 흔들릴 때마다 밧줄이 운다.<br><br>
    그 소리 사이로 째깍 소리가 난다. 상자 하나에서. 다른 짐보다 새것이다. 꼬리표에 이름이 없다.<br>
    째깍 소리를 들으면 숨부터 멈춘다. 시계는 시계일 수도 있다. 대개는 아니다.<br><br>
    방송이 다음 역을 부른다. 서지 않는다.`,
  o:[
    { l:'① 상자를 열고 안을 본다.', k:'gaze', dc:22,
      doom:{ title:'째깍거리는 상자', what:'화물칸이 터지기 직전입니다', dc:18, sec:45,
        text:`상자 뚜껑의 못을 칼끝으로 뺐다. 하나, 둘, 셋.<br><br>넷째 못에 철사가 감겨 있었다. 못이 빠지는 순간 철사가 당겨졌다. 째깍 소리가 멈췄다.<br>멈춘 째깍은 끝난 게 아니다. 다음으로 넘어간 것이다.<br><br>뚜껑 틈에서 연기가 한 줄 올라온다. 가늘다. 빠르다.`,
        dieText:`그날 밤 열차는 서지 않고 달렸다. 맨 뒤 칸이 조금 가벼워진 채로.<br><br>방송은 다음 역을 꼬박꼬박 불렀다.<br>선로 옆 덤불에 상자 꼬리표 하나가 걸려 있었다. 이름 칸에 처음으로 글씨가 있었다.` },
      ok:`뚜껑 틈부터 봤다. 칼끝을 넣어 못 하나하나에 무엇이 걸렸는지 더듬었다. 넷째 못에 철사.<br><br>철사를 먼저 끊고 뚜껑을 열었다. 자명종 시계와 꾸러미. 시계 뒤 전선 둘 중 새것을 뽑았다. 째깍 소리는 계속 난다. 이제 그냥 시계다.<br><br>꾸러미를 챙겼다. 남이 이쪽 몫으로 싼 화약이다. 이쪽이 쓴다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 상자째 화물 문 밖으로 던진다.', k:'break', dc:21,
      ok:`화물칸 옆문 빗장을 풀고 열었다. 빗바람이 들이친다. 선로 옆이 어둡게 흘러간다.<br><br>상자를 들었다. 무겁다. 째깍. 흔들지 않게. 문밖으로 밀어 던졌다.<br>열 숨쯤 지나 뒤쪽 어둠에서 불빛이 피었다. 소리는 바퀴 소리에 묻혔다.<br><br>문을 닫았다. 화물칸 밧줄이 다시 운다. 이제 그 소리만 난다.`,
      ng:`던지려는데 상자가 다른 짐과 밧줄로 묶여 있었다. 같이 끌려온다.<br><br>밧줄을 칼로 끊는 사이 째깍 소리가 빨라졌다. 상자를 문밖으로 걷어찼다. 문밖 바로 앞에서 터졌다.<br>열풍이 화물칸 안으로 들이친다. 얼굴과 손이 화끈하다. 귀가 먹먹하다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-30, spirit:-14 } },
    { l:'③ 째깍 소리로 남은 시간을 잰다.', k:'sense', dc:21,
      ok:`상자에 귀를 댔다. 째깍 소리 사이에 한 번씩 다른 소리가 섞인다. 톱니 하나가 넘어가는 소리. 예순 번에 한 번.<br><br>그 소리 개수를 셌다. 이 시계는 분을 세는 게 아니라 역을 센다. 열차 바퀴에 맞춰 돈다. 네 번 더 넘어가면 끝이다.<br>네 역이 남았다. 내릴 때까지 이 칸에 안 오면 된다. 다들 화물칸을 나왔다. 문을 철사로 묶었다.<br><br>네 역. 시간표의 남은 역을 셌다. 종착 바로 앞이다.`,
      ng:`세는데 열차가 터널에 들어갔다. 바퀴 소리가 두 배로 커진다. 째깍 소리가 안 들린다.<br><br>얼마나 남았는지 모른다. 모르는 채로 상자 앞에 서 있는 게 제일 나쁘다.<br>다들 끌고 앞 칸으로 갔다. 귀 뒤에서 째깍 소리가 계속 들린다. 들릴 리가 없는데.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-14 } }
  ] },

{ at:'B', t:'쉬는 자리 — 심지와 맥박',
  x:`잠깐 숨을 돌린다. 폭파공은 쉬는 동안 심지를 잰다.<br><br>
    한 뼘이 몇 숨에 타는지. 비 오는 밤 공기는 무겁다. 숨이 느려진다. 그런데 쫓기는 몸은 숨이 빨라진다.<br>
    숨으로 재면 숨이 틀린다. 숨이 틀리면 심지가 틀린다.<br><br>
    남은 심지가 세 뼘이다. 하나를 잴 때마다 하나가 준다.`,
  o:[
    { l:'① 한 뼘을 태워 숨을 센다.', k:'sense', dc:20,
      ok:`한 뼘을 잘라 불을 붙였다. 숨을 셌다. 아홉.<br><br>평소보다 셋이 많다. 공기가 무겁다. 남은 두 뼘에 숯으로 금을 다시 그었다.<br><br>한 뼘이 줄었다. 두 뼘이 정확해졌다. 정확한 두 뼘이 대충인 세 뼘보다 낫다.`,
      ng:`세는데 숨이 빨라진다. 밖에서 무슨 소리가 났다.<br><br>여섯인지 일곱인지 모르겠다. 한 뼘을 그냥 태웠다.<br>남은 두 뼘은 아까보다 더 모르는 심지가 됐다.`,
      win:{ exp:15, dream:1 }, lose:{ mind:-14, spirit:-14 } },
    { l:'② 숨 대신 맥박으로 잰다.', k:'steady', dc:21, wake:1,
      ok:`목에 손가락을 댔다. 맥이 뛴다. 빠르다. 그래도 숨보다 고르다.<br><br>한 뼘을 태우며 맥을 셌다. 열여섯. 다시 반 뼘을 태우며. 여덟. 맥은 쫓겨도 제 박자로 간다. 빨라지면 같이 빨라지되 고르게.<br>남은 심지에 금을 그었다. 맥박 수로.<br><br>숨은 마음을 따라간다. 맥은 몸을 따라간다. 몸 안에 시계가 하나 있었다. 이제 그 시계로 불을 잰다.`,
      ng:`맥을 세는데 맥이 건너뛴다. 하나, 둘, 쉬고, 셋.<br><br>오래 쫓긴 심장이 박자를 놓친다. 그걸 세다 보니 더 놓친다.<br>심지 한 뼘이 그냥 탔다. 손이 떨려 금도 비뚤게 그었다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B', t:'배신 — 화약을 나눠 달라는 사람',
  x:`낯선 사람이 같이 가자고 붙었다. 다른 문을 하나 안다고 했다. 저쪽 문을 열 화약만 나눠 달라고.<br><br>
    손을 내민다. 깨끗한 손이다. 손톱 밑이 하얗다.<br>
    폭파공은 손톱 밑으로 사람을 본다. 화약을 만지는 사람은 손톱 밑이 까맣다. 아무리 씻어도.<br><br>
    그는 화약을 만져 본 적이 없거나, 이 일을 아주 오래 해서 장갑을 끼는 사람이다.`,
  o:[
    { l:'① 젖은 화약만 골라 준다.', k:'fix', dc:20,
      ok:`주머니에서 제일 젖은 꾸러미를 골라 줬다. 눌러 보면 질척하다. 겉보기엔 같다.<br><br>그가 고맙다며 다른 길로 간다. 한참 뒤 그쪽에서 성냥 긋는 소리가 여러 번 났다. 그리고 욕설. 그리고 발소리가 이쪽으로 빨라진다. 여럿.<br><br>그가 화약을 들고 간 곳은 문이 아니라 쫓는 쪽이었다. 젖은 걸 줘서 다행이다.`,
      ng:`젖은 것을 고르는데 그가 이쪽 손을 봤다. 고르는 손을.<br><br>웃는다. 그럼 마른 걸로 달라고 한다. 이번엔 손목을 잡는다. 장갑 낀 손이 주머니로 온다.<br>뿌리쳤다. 주머니 끈이 끊어지고 화약 반이 바닥에 쏟아졌다. 빗물에 젖는다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 그의 소매 끝과 신발을 본다.', k:'gaze', dc:21,
      ok:`손은 깨끗하다. 소매 끝을 봤다. 소맷단 안쪽에 검은 가루가 한 줄 묻어 있다. 장갑을 벗을 때 묻는 자리다.<br><br>신발을 봤다. 신발 끈 구멍에 쇠가 없다. 불꽃 안 튀게 고른 신발이다. 이쪽과 같은 신발이다.<br>화약을 주지 않았다. 대신 웃으며 말했다. 그 문은 이쪽이 이미 열었다고.<br><br>그가 웃음을 거두고 돌아선다. 같은 일을 하는 사람은 서로를 안다.`,
      ng:`보는데 그가 먼저 이쪽 손톱을 봤다. 까만 손톱.<br><br>그가 웃는다. 아 그쪽이 그거구나, 하는 웃음. 뒤로 물러서며 휘파람을 분다.<br>멀리서 대답하는 휘파람. 이쪽이 무엇인지 저쪽이 다 알게 됐다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B1', t:'창고 사무실 — 금고 문',
  x:`2층 사무실 구석에 금고가 있다. 장부가 저 안에 있다.<br><br>
    다이얼 자물쇠다. 금고 문은 두꺼운 쇠다. 큰 화약은 금고와 사무실과 이쪽을 같이 없앤다.<br>
    금고 문 경첩을 본다. 쇠판과 쇠판이 만나는 이음매. 손가락 굵기의 선 하나.<br><br>
    계단 아래에서 양동이 내려놓는 소리가 났다.`,
  o:[
    { l:'① 경첩 이음매를 따라 화약을 가늘게 깐다.', k:'break', dc:22, wake:1,
      ok:`화약을 한 덩이로 붙이지 않았다. 손가락으로 집어 경첩 이음매를 따라 실처럼 깔았다. 위에서 아래로. 끝을 젖은 종이로 눌렀다.<br><br>불을 붙였다. 터지지 않고 지지직 탄다. 이음매를 따라 위에서 아래로. 쇠가 이음매만 따라 하얗게 갈라진다.<br>금고 문이 경첩 쪽부터 떨어져 내려 비스듬히 섰다. 소리는 장작 갈라지는 소리만 했다.<br><br>화약은 덩어리로만 쓰는 줄 알았다. 실로 깔면 칼이 된다. 터뜨리는 게 아니라 가르는 것. 손이 그 굵기를 오늘 찾았다.`,
      ng:`깔다가 화약 실이 끊겼다. 중간에 빈 데가 생겼다.<br><br>불이 거기서 멈췄다. 위는 갈라지고 아래는 멀쩡하다. 금고 문이 반쯤 기울어 걸렸다.<br>억지로 젖히는 사이 계단에서 장화 소리가 올라온다. 장부를 반만 뜯어 들고 창으로 나갔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, mind:-16 } },
    { l:'② 다이얼에 귀를 대고 돌린다.', k:'sense', dc:21,
      ok:`이쪽 귀는 반쯤 운다. 그래도 쇠가 맞물리는 소리는 손으로 듣는다. 다이얼에 귀와 손가락 끝을 같이 댔다.<br><br>천천히 돌렸다. 딸깍이 아니라 아주 작은 걸림. 셋. 문이 열렸다. 화약은 안 썼다.<br><br>장부 마지막 장에 오늘 날짜와 다섯 줄. 그 밑에 한 줄이 더 있다. 연필로. 『화약 담당 — 현장 처리.』 이쪽 일이 적혀 있다.`,
      ng:`귀가 울려 걸림을 놓쳤다. 두 번 돌리고 세 번 돌렸다.<br><br>다이얼이 잠겼다. 틀린 횟수가 넘었다. 금고 안에서 쇠 빗장이 하나 더 내려오는 소리.<br>계단에서 장화 소리가 올라온다. 이제 화약을 써도 늦다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B2', t:'계단실 — 6층 방화문',
  x:`7층에서 6층으로 내려왔다. 6층 방화문이 계단실 쪽에서 잠겼다. 계단은 더 아래로 이어지지 않는다. 막혔다. 6층을 지나야 한다.<br><br>
    문을 본다. 화약 한 꼬집이면 된다. 계단실은 소리를 위아래로 다 나른다.<br>
    위에서 정각 점검이 돈다. 딸깍 소리가 계단을 타고 내려온다.<br><br>
    계단참에 낡은 매트리스가 하나 버려져 있다.`,
  o:[
    { l:'① 그냥 터뜨리고 뛴다.', k:'break', dc:21,
      doom:{ title:'울린 계단실', what:'계단실 아래로 끌려갑니다', dc:17, sec:50,
        text:`걸쇠에 화약을 붙이고 붙였다. 퍽. 걸쇠가 날았다.<br><br>소리가 계단실 위아래로 퍼진다. 위의 딸깍 소리가 멈춘다. 아래 막힌 줄 알았던 계단참 아래에서 무언가 움직인다. 막힌 게 아니라 가려져 있었다.<br>문을 열고 뛰려는 순간 아래에서 손이 올라와 외투 자락을 잡았다.<br><br>당긴다. 막힌 줄 알았던 아래로. 있는 줄 몰랐던 층으로.`,
        dieText:`6층 방화문은 열렸다. 일행은 6층을 지났다.<br><br>정각 점검의 숫자는 맞았다. 계단실 아래에서 누가 대신 대답했다.<br>문 앞 바닥에 화약 그을음이 별 모양으로 남았다.` },
      ok:`걸쇠에 화약을 붙이고 심지를 아주 짧게 했다. 붙이자마자 문을 어깨로 밀 수 있게 섰다.<br><br>퍽. 걸쇠가 날자마자 밀었다. 다들 6층으로 쏟아져 들어갔다. 문을 닫았다.<br>계단실 쪽에서 위아래로 발소리가 모인다. 소리 난 자리로. 문 앞에 모여 한참 서 있다.<br><br>그때 이쪽은 이미 6층 복도 끝이다. 소리를 낸 곳에 오래 있지 않는 것. 폭파공이 제일 먼저 배우는 것이다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 매트리스를 덮어 소리를 먹이고 터뜨린다.', k:'fix', dc:21,
      ok:`매트리스를 끌어다 걸쇠 자리에 세우고 등으로 눌렀다. 심지는 매트리스 밑으로 뺐다.<br><br>퍽. 매트리스가 등을 한 번 밀었다. 소리는 이불 터는 소리만 했다. 걸쇠가 떨어졌다.<br>위의 딸깍 소리가 멈추지 않고 계속 간다. 못 들었다.<br><br>매트리스에 그을린 구멍이 났다. 등에 멍이 들 것이다. 싸다.`,
      ng:`매트리스가 젖어 무겁다. 세우다가 쓰러졌다. 쿵.<br><br>그 소리가 화약 소리보다 컸다. 위의 딸깍 소리가 멈췄다. 내려오는 발소리.<br>서둘러 붙인 화약이 매트리스 없이 터졌다. 귀가 먹먹하다. 문은 열렸다. 다들 들켰다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } }
  ] },

{ at:'B3', t:'식당칸 — 가스 냄새',
  x:`식당칸 주방에서 가스 냄새가 난다. 화구 손잡이가 다 열려 있다. 불은 안 켜졌다.<br><br>
    요리사는 없다. 칼만 도마 위에 가지런하다.<br>
    코를 막았다. 이 냄새가 칸 하나를 채우는 데 얼마나 걸리는지 안다. 거의 다 찼다.<br><br>
    뒤 칸에서 그것이 온다. 담배를 입에 물었다. 아직 불은 안 붙였다.`,
  o:[
    { l:'① 화구를 잠그고 창을 연다.', k:'fix', dc:21,
      ok:`숨을 참고 주방에 들어가 화구 손잡이를 하나씩 잠갔다. 여섯.<br><br>식당칸 창을 다 내렸다. 빗바람이 들이쳐 냄새를 쓸어 간다. 보가 날린다.<br>뒤 칸 문이 열리고 그것이 들어온다. 라이터를 켠다. 아무 일도 없다. 그것이 담배에 불을 붙이며 이쪽을 본다. 아쉬워하는 얼굴로 바뀐다.<br><br>다음 칸으로 갔다. 등 뒤에서 그것이 연기를 길게 내뿜는다.`,
      ng:`잠그는 사이 숨이 다했다. 들이쉬었다. 머리가 핑 돈다.<br><br>손잡이 하나를 못 잠갔다. 창을 내리는데 팔에 힘이 없다.<br>뒤 칸 문이 열린다. 라이터 소리. 엎드렸다. 화구 하나 몫만큼 작게 붙었다가 꺼졌다. 머리카락 끝이 탔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-16 } },
    { l:'② 다 건너간 뒤 일부러 터뜨려 뒤를 끊는다.', k:'break', dc:22,
      ok:`다들 식당칸을 지나 앞 칸으로 보냈다. 이쪽은 연결 통로에서 마지막으로 돌아섰다.<br><br>그것이 뒤 칸 문을 열고 들어온다. 라이터를 든다. 그보다 먼저 이쪽이 화약 심지 끝을 식당칸 안으로 던져 넣고 문을 닫았다. 불붙은 채로.<br>연결 통로 철판에 엎드렸다. 식당칸이 한 번 숨을 크게 쉬었다. 유리가 밖으로 다 터졌다.<br><br>일어나 보니 식당칸 뒤쪽 문이 막혔다. 그것은 그 너머에 있다. 문을 두드리지 않는다.`,
      ng:`심지를 던지는 순간 그것이 먼저 라이터를 켰다.<br><br>불이 이쪽 앞에서 피었다. 연결 통로로 열풍이 밀려온다. 이쪽은 아직 문을 다 닫지 못했다.<br>얼굴과 손이 익는다. 굴러서 앞 칸으로 들어갔다. 귀가 안 들린다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-32, spirit:-14 } }
  ] },

{ at:'B', t:'창밖 — 천둥',
  x:`문 하나만 터뜨리면 나간다. 문 너머 가까운 데에 깨어 있는 것들이 있다. 터지는 소리 하나면 다 온다.<br><br>
    비가 세진다. 창밖 하늘이 하얗게 번쩍인다. 숨 여덟 뒤에 천둥이 온다.<br>
    큰 소리 속에 작은 소리를 숨기는 법을 들은 적이 있다. 해 본 적은 없다.<br><br>
    다시 번쩍인다.`,
  o:[
    { l:'① 번개를 보고 심지를 잘라 천둥에 맞춘다.', k:'sense', dc:21, wake:1,
      ok:`번쩍임과 천둥 사이를 셌다. 여덟 숨. 다음엔 일곱. 가까워진다.<br><br>다음 번쩍임이 오는 순간 심지에 불을 붙였다. 심지는 여섯 숨 반 길이로 잘라 두었다. 번개가 가까워진 만큼 줄였다.<br>천둥이 하늘을 찢었다. 그 한가운데에서 문이 터졌다. 아무것도 오지 않았다. 천둥이 크다고 누가 투덜대는 소리만 멀리서 났다.<br><br>소리를 숨기는 데는 더 큰 소리가 있으면 된다. 손이 바깥 박자에 심지를 맞췄다. 터지는 때를 고르는 데에 하늘까지 들어왔다.`,
      ng:`셌는데 천둥이 생각보다 빨리 왔다. 번개가 바로 위다.<br><br>천둥이 끝난 다음에 문이 터졌다. 혼자서. 빗소리 위로 또렷하게.<br>사방에서 문 열리는 소리가 대답한다. 하나, 둘, 여럿.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 기다리지 않고 지금 터뜨린다.', k:'break', dc:21,
      ok:`기다릴 시간이 없다. 뒤에서 발소리가 온다. 지금 터뜨렸다.<br><br>문이 날았다. 사방에서 문 열리는 소리. 다들 뛰었다. 연기 속으로.<br>깨어난 것들과 쫓던 것들이 소리 난 자리로 한꺼번에 모인다. 서로 부딪치는 사이 이쪽은 이미 다음 모퉁이다.<br><br>소리에 모이는 것이 많으면 서로가 서로를 막는다. 그렇게 믿기로 했다.`,
      ng:`터뜨렸는데 문이 반만 열렸다. 젖은 화약이 반만 탔다.<br><br>사방에서 문 열리는 소리. 다들 반쯤 열린 문에 몸을 비집었다. 이쪽이 마지막이다.<br>틈에 끼었다. 빼는 사이 등 뒤에서 손전등이 이쪽을 비춘다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, spirit:-14 } }
  ] },

{ at:'B1', t:'정문 — 사슬 감긴 철문',
  x:`항구 정문이다. 철문에 굵은 사슬이 감겼다. 자물쇠가 셋.<br><br>
    정문 위 『출입』 네온이 떨린다. 하늘 끝이 아직 검다. 해무호 고동이 멀리서 운다. 들어오고 있다.<br>
    사슬을 본다. 고리 하나만 끊으면 사슬 전체가 풀린다. 어느 고리인지만 고르면.<br><br>
    등 뒤 창고 쪽에서 양동이 덜그럭거리는 소리가 다가온다.`,
  o:[
    { l:'① 녹이 제일 슨 고리 하나만 끊는다.', k:'break', dc:21,
      ok:`사슬 고리를 하나씩 손가락으로 훑었다. 열둘째 고리가 다른 것보다 가늘다. 녹이 속까지 먹었다.<br><br>그 고리 안쪽에 화약 손톱만큼을 이겨 붙였다. 심지를 손가락 길이로. 퍽. 고리가 터지자 사슬이 제 무게로 미끄러져 내린다. 철문이 삐걱 열린다.<br><br>다들 빠져나갔다. 돌아보니 양동이를 든 그림자가 창고 앞에 서서 이쪽을 본다. 쫓지 않는다. 시계를 본다.`,
      ng:`고른 고리가 아니라 옆 고리가 터졌다. 사슬은 그대로다.<br><br>둘째 고리를 고르는 사이 양동이 소리가 가까워진다. 손이 떨려 화약을 흘렸다.<br>세 번째에 끊었다. 철문을 빠져나올 때 등 뒤에서 대걸레 자루가 철문을 쳤다. 손가락 한 마디 옆을.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-24, spirit:-16 } },
    { l:'② 철문 기둥 밑 흙을 터뜨려 기둥째 기울인다.', k:'fix', dc:21,
      ok:`사슬은 두고 철문 기둥을 봤다. 아스팔트가 갈라져 기둥 밑 흙이 드러났다. 빗물에 무르다.<br><br>기둥 밑 흙에 화약을 꾹 묻었다. 퍽, 둔하게. 기둥이 바깥쪽으로 기운다. 철문이 사슬째 같이 기울어 아래에 틈이 생겼다.<br>다들 그 틈으로 기어 나갔다.<br><br>사슬과 자물쇠는 멀쩡하다. 아침에 오는 사람은 문이 잠겼다고 할 것이다.`,
      ng:`흙이 너무 물러 화약이 젖었다. 터지지 않고 연기만 났다.<br><br>다시 묻는 사이 손이 진흙투성이가 됐다. 둘째는 터졌다. 기둥이 덜 기울었다.<br>틈이 좁다. 기어 나오다 철문 밑에 등이 긁혔다. 길게.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-12 } }
  ] },

{ at:'B2', t:'세탁물 통로 — 막힌 관',
  x:`세탁물 통로 쇠 뚜껑을 열었다. 아래로 이어지는 관이다. 종이학에 적혀 있던 길.<br><br>
    한 층 아래쯤에서 관이 막혔다. 무언가 걸려 있다. 무르다. 시트 뭉치 같다. 시트 뭉치이길 바란다.<br>
    막힌 관을 보면 화약부터 생각난다. 관 안에서 터지면 소리가 관을 따라 병원 전체로 간다.<br><br>
    복도에서 딸깍 소리가 다가온다.`,
  o:[
    { l:'① 꾸러미를 줄에 달아 내려 작게 터뜨린다.', k:'break', dc:21,
      ok:`꾸러미를 신발 끈에 달아 관 아래로 내렸다. 막힌 것에 닿았을 때 멈췄다. 심지는 끈을 따라 위로 올렸다.<br><br>불을 붙이고 뚜껑을 닫았다. 관 안에서 툭. 소리가 관을 타고 내려간다. 위로는 안 온다.<br>뚜껑을 열자 아래에서 바람이 올라온다. 뚫렸다. 다들 하나씩 내려갔다.<br><br>내려가다 벽에 젖은 시트 조각이 붙어 있었다. 시트였다.`,
      ng:`꾸러미가 막힌 것에 닿기 전에 관 이음매에 걸렸다.<br><br>거기서 터졌다. 관이 울리며 위아래로 소리가 간다. 막힌 것은 그대로다. 오히려 더 단단히 걸렸다.<br>딸깍 소리가 멈췄다. 세탁실 문이 열린다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 내려가서 손으로 빼낸다.', k:'steady', dc:21,
      ok:`발부터 관에 넣었다. 등과 발로 벽을 버티며 내려갔다. 막힌 데에 발이 닿는다.<br><br>무르다. 발로 밀었다. 안 내려간다. 손을 내려 더듬었다. 젖은 시트다. 시트 사이로 손가락 같은 게 만져진다. 장갑이다. 빈 장갑.<br>시트를 한 장씩 뽑아 위로 넘겼다. 아홉 장째에 뚫렸다.<br><br>빈 장갑은 손에 남았다. 놓고 내려가지 못했다.`,
      ng:`버티던 등이 미끄러졌다. 막힌 데에 발부터 박혔다.<br><br>시트가 다리를 감싼다. 무르고 차다. 빠지지 않는다.<br>위에서 동료가 손을 내려 겨우 끌어올렸다. 다리에 시트 자국이 붉게 감겨 있다. 손가락 모양으로.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B3', t:'터널 — 먹먹한 귀',
  x:`터널이다. 바퀴 소리가 벽에 부딪혀 귀를 짓누른다. 화약 다루는 귀는 원래 반쯤 운다. 지금은 아무것도 안 들린다.<br><br>
    객차 불이 깜빡인다. 켜질 때마다 일행이 하나씩 자리를 바꿔 앉아 있다.<br>
    누가 이쪽 귀에 대고 무어라 말한다. 입김이 닿는다. 말은 안 들린다. 목소리가 일행 것 같다.<br><br>
    이 터널은 길다.`,
  o:[
    { l:'① 손바닥을 바닥에 대고 떨림을 읽는다.', k:'steady', dc:21,
      ok:`귀를 포기했다. 손바닥을 객차 바닥에 댔다.<br><br>바퀴 떨림 사이로 발소리 떨림이 섞인다. 일행 발은 넷. 다섯째 발은 떨림이 없다. 무게가 없는 발이다. 이쪽 바로 뒤에 서 있다.<br>불이 켜지는 순간 돌아서서 그 자리를 손바닥으로 밀었다. 무언가 밀려 통로 끝으로 미끄러진다.<br><br>터널을 나오자 귀가 돌아온다. 일행이 이쪽 이름을 부르고 있다. 넷.`,
      ng:`손바닥에 떨림이 너무 많다. 터널 전체가 떨린다.<br><br>어느 것이 발인지 모르겠다. 그사이 귀 옆 입김이 말을 계속한다.<br>터널을 나와 귀가 돌아왔을 때 그 말이 마지막 한 마디만 들렸다. 『다음은 너.』`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-16 } },
    { l:'② 섬광 가루를 터뜨려 얼굴들을 비춘다.', k:'break', dc:21,
      ok:`주머니 바닥에 은빛 가루가 한 꼬집 있다. 소리는 작고 빛이 큰 것.<br><br>불이 꺼진 순간 손바닥에 놓고 불을 댔다. 하얀 빛이 객차를 한 번 때렸다. 그 한순간에 얼굴이 다 보였다. 일행 넷. 그리고 이쪽 바로 뒤 하나. 얼굴이 아직 정해지지 않은 채로 있다.<br><br>빛이 꺼지고 불이 켜졌을 때 그것은 없었다. 바뀌는 도중에 들킨 것은 오래 머물지 않는다.`,
      ng:`가루가 손바닥 땀에 젖어 있었다. 빛이 반만 났다.<br><br>반만 밝은 빛에 얼굴들이 다 같아 보인다. 다섯이 다 일행 얼굴이다.<br>눈이 부셔 한참 안 보였다. 다시 보일 때 일행은 넷이다. 다섯째가 누구였는지 이쪽만 모른다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B', t:'쉬는 자리 — 손톱 밑의 검정',
  x:`숨은 자리에서 손을 봤다. 손톱 밑이 까맣다. 손바닥에도 화약 가루가 배었다.<br><br>
    화약 만지는 손은 냄새가 난다. 유황과 숯. 개는 그 냄새를 멀리서 맡는다. 사람도 맡는다. 냄새를 아는 사람이라면.<br>
    밖에서 개 숨소리가 지나간다. 킁킁. 멈췄다 다시 간다.<br><br>
    빗물받이 통에 물이 고여 있다.`,
  o:[
    { l:'① 빗물로 손을 문질러 씻는다.', k:'heal', dc:20,
      ok:`빗물받이 통에 손을 넣고 문질렀다. 손톱 밑을 손톱으로 팠다.<br><br>검은 물이 빠진다. 다 빠지지는 않는다. 화약 묻은 손톱은 원래 안 빠진다. 그래도 냄새는 옅어졌다.<br>개 숨소리가 숨은 자리 앞을 지나간다. 멈추지 않고.<br><br>깨끗해진 손이 낯설다. 이 손으로 내일 또 화약을 만진다.`,
      ng:`손을 넣자 통의 물이 까맣게 번졌다. 냄새가 물에 풀려 더 퍼진다.<br><br>개가 멈췄다. 킁킁. 이쪽 쪽으로.<br>숨은 자리 틈으로 개 코가 들어왔다. 다들 반대쪽으로 빠져 뛰었다. 등 뒤에서 개가 짖는다.`,
      win:{ exp:14, dream:1, hp:8 }, lose:{ hp:-20, spirit:-16 } },
    { l:'② 화약 가루를 반대쪽에 뿌려 냄새 길을 낸다.', k:'hide', dc:21,
      ok:`주머니에서 쓸모없는 젖은 화약을 한 줌 꺼냈다. 숨은 자리 반대편 골목에 뿌렸다. 벽에 문질렀다. 다섯 걸음마다.<br><br>그리고 손을 빗물에 씻고 반대로 갔다.<br>개 숨소리가 냄새 길을 따라간다. 신이 났다. 사람 발소리가 개를 따라간다.<br><br>쓸모없는 화약도 일을 한다. 이번엔 쫓는 것들을 끌고 갔다.`,
      ng:`뿌리는 사이 개가 먼저 왔다. 냄새 길의 시작이 이쪽 발밑이다.<br><br>개가 이쪽 신발에 코를 박는다. 짖는다.<br>개를 걷어차고 뛰었다. 손에서 화약 냄새가 더 난다. 방금 뿌렸으니까.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B', t:'마지막 문 — 남은 화약 전부',
  x:`나가는 문이다. 두꺼운 쇠문. 빗소리가 문 너머에서 난다.<br><br>
    주머니에 화약이 한 줌 남았다. 오늘 쓰고 남은 전부다. 이 문에는 한 줌이 맞을 수도, 모자랄 수도, 넘칠 수도 있다.<br>
    뒤에서 쫓는 것들이 온다. 시계는 마지막 칸 앞이다.<br><br>
    문에 손바닥을 댔다. 쇠가 차다.`,
  o:[
    { l:'① 한 줌을 다 넣는다.', k:'break', dc:22,
      doom:{ title:'한 줌', what:'문과 함께 터졌습니다', dc:18, sec:45,
        text:`한 줌을 문 가운데에 다 이겨 붙였다. 심지를 길게 끌 시간이 없다. 짧게.<br><br>붙이고 돌아서 뛰었다. 셋을 세었다. 둘째에 터졌다. 심지가 젖어 있었다. 빨리 탔다.<br>등 뒤에서 쇠문이 꽃처럼 벌어진다. 파편이 빗발친다.<br><br>폭파공은 터지는 것의 크기를 잰다. 오늘은 시간을 못 쟀다.`,
        dieText:`문은 열렸다. 넘치게.<br><br>다들 빗속으로 나갔다. 문턱에 한 사람이 엎드려 있었다. 손에 성냥갑을 쥔 채로.<br>성냥은 다 젖어 있었다. 마지막 불은 다른 데서 왔다.` },
      ok:`한 줌을 다 넣었다. 대신 심지를 문 밖이 아니라 문 옆 벽을 따라 멀리 돌렸다. 모퉁이 하나 너머까지.<br><br>쫓는 것들이 모퉁이에 닿는 순간 붙였다. 쇠문이 꽃처럼 벌어진다. 파편이 쫓는 쪽 통로로 쏟아졌다. 문과 길을 한 번에.<br>연기 속을 뚫고 빗속으로 나갔다.<br><br>주머니가 비었다. 가볍다. 오늘은 한 줌이 맞았다.`,
      win:{ exp:25, dream:4 } },
    { l:'② 반만 쓴다 — 문이 아니라 문의 숨구멍에.', k:'gaze', dc:21, wake:1,
      ok:`문을 손바닥으로 훑었다. 가운데가 아니라 아래쪽 귀퉁이에서 손바닥이 미세하게 시원하다. 바람이 샌다. 문과 문틀 사이가 거기만 뜬다.<br><br>반 줌을 그 틈에 넣었다. 둔하게 터졌다. 문이 귀퉁이부터 들려 문틀에서 빠졌다. 반 줌으로.<br>남은 반 줌은 쥐고 나갔다. 빗속에서 쫓는 것들이 문턱에 닿았다. 그 발밑에 남은 반을 던졌다.<br><br>문은 어디로 숨을 쉬는지 손바닥이 안다. 숨구멍에 넣으면 반이면 된다. 손이 이제 문의 숨을 찾는다.`,
      ng:`시원한 데를 찾았다고 생각했는데 그게 아니었다. 이쪽 손바닥 땀이 식는 것이었다.<br><br>반 줌이 문에 금만 냈다. 남은 반을 마저 넣었다. 그제야 열렸다.<br>던질 것이 없다. 쫓는 것들이 문턱을 넘어온다. 맨손으로 문짝을 끌어 막으며 나갔다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-30, spirit:-16 } },
    { l:'③ 문은 두고 옆 벽 이음매를 노린다.', k:'fix', dc:21,
      ok:`쇠문 옆 벽은 블록이다. 줄눈이 빗물에 젖어 무르다. 블록 하나가 다른 것보다 튀어나왔다.<br><br>그 블록 줄눈을 칼끝으로 파 화약을 다졌다. 퍽. 블록 셋이 빠졌다. 사람 하나 기어 나갈 구멍이다.<br>다들 구멍으로 나갔다. 쇠문은 끝까지 잠겨 있다.<br><br>쇠문을 지키는 사람은 쇠문만 본다. 벽은 아무도 안 본다.`,
      ng:`블록 안에 쇠막대가 들어 있었다. 블록은 깨졌는데 쇠막대가 구멍을 가로막는다.<br><br>쇠막대 사이로 몸을 비집었다. 셋은 나갔다. 이쪽 어깨가 걸린다.<br>뒤에서 손이 발목을 잡았다. 걷어차고 빠져나왔다. 신발 한 짝을 두고.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B', t:'좁은 목 — 뒤에서 오는 것들',
  x:`사람 하나 겨우 지나는 좁은 목이다. 위에 낡은 문틀이 걸렸다. 문짝은 없다. 문틀 위로 무게가 실려 있다.<br><br>
    좁은 목 너머가 나가는 쪽이다. 뒤에서 쫓는 것들이 온다. 이쪽이 지나면 저것들도 지난다.<br>
    폭파공은 문틀을 받친 이음매를 본다. 녹슬었다. 화약 한 꼬집이면 문틀째 내려앉는다.<br><br>
    내려앉는 때를 고르는 게 전부다. 일찍 무너뜨리면 이쪽이 못 지나고, 늦으면 저것들이 지난다.`,
  o:[
    { l:'① 다 지난 뒤 첫째가 문틀 밑에 설 때 무너뜨린다.', k:'break', dc:22, wake:1,
      ok:`이음매에 꾸러미를 붙이고 심지를 좁은 목 너머까지 끌었다. 다들 먼저 보냈다. 이쪽이 마지막으로 지났다.<br><br>쫓는 것들이 좁은 목에 들어선다. 첫째. 둘째. 첫째가 문틀 밑에 닿기 네 걸음 전에 붙였다. 심지는 네 걸음 길이다. 첫째가 문틀 밑을 밟는 순간 이음매가 터졌다.<br>문틀이 위의 무게째 내려앉는다. 좁은 목이 막혔다. 저쪽에 남은 것들이 멈춰 섰다.<br><br>문을 열 때는 언제 터지든 상관없었다. 오늘은 남의 걸음에 심지를 맞췄다. 쫓는 것의 발이 심지 끝이 된다.`,
      ng:`붙이는 순간 첫째가 뛰었다. 걸음이 바뀌었다.<br><br>문틀이 내려앉았을 때 첫째는 이미 이쪽에 와 있었다. 목은 막혔다. 첫째만 건너왔다.<br>첫째와 이쪽이 막힌 목 앞에서 마주 섰다. 동료들이 같이 막아서야 했다. 팔을 물렸다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-30, spirit:-14 } },
    { l:'② 지나는 중에 심지를 먼저 붙이고 달린다.', k:'steady', dc:21,
      ok:`이음매에 꾸러미를 붙이고 심지에 바로 불을 댔다. 그리고 달렸다. 다들 같이.<br><br>심지는 열 숨. 좁은 목을 다 빠지는 데 아홉 숨. 마지막 사람이 빠지고 한 숨 뒤에 터졌다.<br>뒤에서 문틀이 내려앉는 소리. 쫓던 것들이 저쪽에서 멈춘다.<br><br>한 숨이 남았다. 한 숨이면 넉넉하다. 폭파공 셈으로는.`,
      ng:`달리다 동료 하나가 젖은 바닥에 미끄러졌다. 일으키는 데 두 숨.<br><br>이쪽이 문틀 밑에 있을 때 터졌다. 떨어지는 것을 등으로 받으며 굴러 나왔다.<br>동료들이 끌어냈다. 등이 펴지지 않는다. 뒤는 막혔다. 막히긴 막혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

]);

// ------------------------------------------
// 대검사 · 무력
// ------------------------------------------
kJob('greatsword', 'B', [

{ at:'B', t:'빗속 — 칼집에 고인 물',
  x:`비가 칼집 입구로 들어간다. 칼을 멘 등이 무겁다. 물 무게까지 졌다.<br><br>
    칼집 안에 물이 고이면 날이 녹슨다. 녹슨 날은 뽑을 때 걸린다. 걸리는 한 숨에 일이 끝난다.<br>
    대검사의 칼은 사람 키만 하다. 뽑는 데만 한 숨이 든다. 거기에 한 숨이 더 들면 늦다.<br><br>
    뒤에서 쫓는 발소리가 빗소리 사이로 섞인다.`,
  o:[
    { l:'① 칼집을 거꾸로 메어 물을 뺀다.', k:'fix', dc:20,
      ok:`칼집을 풀어 거꾸로 들었다. 물이 줄줄 쏟아진다. 생각보다 많다.<br><br>끝에 천을 쑤셔 넣어 막고 입구가 아래로 가게 다시 멨다. 이제 들어간 물은 나온다.<br>뽑는 방향이 바뀌었다. 위가 아니라 아래로 뽑아야 한다. 몇 번 해 봤다. 손이 금방 외운다.`,
      ng:`거꾸로 드는 사이 칼이 칼집에서 미끄러졌다. 날이 먼저 땅에 떨어졌다.<br><br>쇳소리가 골목을 울린다. 발소리가 멈췄다가 이쪽으로 빨라진다.<br>칼을 주워 칼집에 넣으려는데 젖은 칼집 입구가 날을 물고 안 받는다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-20, mind:-14 } },
    { l:'② 칼을 뽑아 든 채로 다닌다.', k:'steady', dc:21, wake:1,
      ok:`칼을 뽑았다. 칼집은 등에 빈 채로 멨다. 칼은 손에 들었다. 칼끝을 땅 쪽으로, 날을 몸 바깥으로.<br><br>빗물이 날을 타고 흘러내린다. 고이지 않는다. 무겁다. 팔이 금방 지친다. 지칠 때마다 칼끝을 땅에 한 번 대고 쉬었다. 대는 자리가 매번 같은 자리가 된다.<br><br>뽑아 든 칼은 뽑는 한 숨이 없다. 들고 다니는 것 자체가 칼을 뽑아 둔 자세가 됐다. 걸음과 칼이 같이 가는 법을 몸이 하나 얻었다.`,
      ng:`들고 다니는데 팔이 먼저 졌다. 칼끝이 땅을 긁는다. 쇳소리가 길게 따라온다.<br><br>쫓는 것들이 그 소리를 듣는다. 다들 이쪽을 돌아본다. 소리를 끌고 다니는 사람을.<br>칼집에 다시 넣었다. 젖은 칼집 안으로.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-22, spirit:-14 } }
  ] },

{ at:'B1', t:'잔교 — 빠진 널판',
  x:`창고 뒤 잔교다. 바다 위로 뻗은 나무 길. 널판이 군데군데 빠졌다.<br><br>
    빠진 데 아래로 검은 물이 출렁인다. 물이 널판 밑을 두드린다. 무언가 같이 두드린다.<br>
    건너편에 작은 배가 묶여 있다. 노가 하나 있다.<br><br>
    빠진 널판 너비를 본다. 칼 길이보다 조금 짧다.`,
  o:[
    { l:'① 칼을 빠진 데에 걸쳐 디딤판으로 쓴다.', k:'fix', dc:21,
      ok:`칼을 칼집째 빠진 데 위에 가로로 걸쳤다. 양 끝이 널판에 한 뼘씩 걸린다.<br><br>다들 칼집 위를 한 발로 디디고 건넜다. 마지막에 이쪽이 칼을 들어 올리며 뛰었다. 칼집 밑에서 물이 튄다. 무언가 칼집 끝을 잡으려다 놓쳤다.<br><br>건너편에서 칼집을 봤다. 끝에 젖은 손자국이 있다. 손가락이 넷이다.`,
      ng:`걸쳤는데 한쪽 널판이 썩었다. 칼집 끝이 미끄러진다.<br><br>둘째가 건널 때 칼이 기울었다. 둘째 다리가 빠졌다. 붙잡아 끌어올렸다.<br>그사이 칼이 물에 빠질 뻔했다. 칼자루를 손끝으로 겨우 쥐었다. 물속에서 무언가 칼끝을 같이 쥐고 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 칼을 짚고 장대처럼 넘는다.', k:'evade', dc:21,
      ok:`칼집째 칼끝을 빠진 데 건너편 널판에 짚었다. 자루를 잡고 몸을 날렸다.<br><br>칼이 휜다. 이 칼은 원래 안 휜다. 휜 것처럼 느꼈다. 건너편에 발이 닿았다.<br>칼을 뽑아 다시 이쪽으로 내밀었다. 다들 칼집 끝을 잡고 하나씩 뛰었다.<br><br>마지막 사람이 건너올 때 아래 물이 크게 출렁였다. 아무도 내려다보지 않았다.`,
      ng:`짚은 널판이 무너졌다. 칼끝이 허공을 짚는다.<br><br>몸이 빠진 데로 떨어진다. 팔꿈치로 널판 가장자리를 걸었다. 다리가 물에 잠긴다. 차다. 무언가 발목을 쓸고 지나간다.<br>동료들이 끌어올렸다. 장화 안에 물과 미끈한 것이 같이 들어 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B2', t:'간호사실 — 압수된 칼',
  x:`눈을 뜨니 칼이 없다. 등이 가볍다. 칼을 메던 등이 가벼우면 이상한 등이다.<br><br>
    간호사실 유리창 너머 철제 보관함에 칼이 꽂혀 있다. 칼자루가 보관함 위로 삐죽 나왔다. 이름표가 붙었다. 이쪽 이름이 아니다. 숫자다.<br>
    간호사실에는 아무도 없다. 정각까지 칠 분.<br><br>
    칼 없는 대검사는 어깨가 넓은 사람일 뿐이다.`,
  o:[
    { l:'① 들어가서 보관함 자물쇠를 연다.', k:'fix', dc:21,
      ok:`간호사실 문은 안 잠겼다. 잠글 필요가 없다고 생각했을 것이다.<br><br>보관함 자물쇠는 작다. 머리핀으로 열 만큼. 손가락이 굵어 몇 번 놓쳤다. 다섯 번째에 열렸다.<br>칼을 뽑아 등에 멨다. 등이 다시 무겁다. 무거워서 숨이 편하다.<br><br>나오다 보니 보관함 안에 다른 것들이 더 있다. 지팡이, 우산, 안경. 다 숫자 이름표가 붙었다. 주인들은 돌아오지 않았다.`,
      ng:`자물쇠를 만지는데 머리핀이 부러졌다. 반쪽이 구멍 안에 박혔다.<br><br>딸깍 소리가 복도에서 다가온다. 칼자루를 잡고 보관함째 흔들었다. 열리지 않는다. 소리만 난다.<br>간호사가 문간에 섰다. 이쪽 손이 칼자루를 쥐고 있다. 간호사가 수첩에 무언가 적는다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 간호사실 창 밑을 기어 보관함 뒤로 돈다.', k:'hide', dc:21,
      ok:`창 밑에 붙어 기었다. 덩치가 크다. 기는 것도 크게 긴다. 숨을 짧게 끊었다.<br><br>보관함 뒤로 돌아 뒤판을 손으로 밀었다. 나사가 헐겁다. 뒤판이 젖혀진다. 칼날 쪽부터 칼을 빼냈다.<br>정각에 간호사가 들어와 보관함을 본다. 칼자루가 아직 꽂혀 있다. 칼집만 남겨 두었다.<br><br>칼집 없이 칼을 들고 나왔다. 날이 맨살처럼 차다.`,
      ng:`기는데 등이 창틀을 쳤다. 덩치가 너무 크다.<br><br>쾅. 유리가 떤다. 복도 끝 문이 열린다.<br>보관함까지 못 갔다. 침대로 돌아가 누웠다. 정각에 세어졌다. 칼은 숫자를 달고 보관함에 남았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-20, mind:-16 } }
  ] },

{ at:'B3', t:'9호차 — 선반에 걸리는 칼',
  x:`객차 통로다. 등에 멘 칼이 선반을 긁는다. 칼자루가 천장 손잡이에 부딪힌다.<br><br>
    뒤에서 그것이 온다. 얼굴을 바꾸는 손님. 좌석 등받이를 하나씩 짚으며.<br>
    큰 칼은 등에서 머리 위로 뽑는다. 여기서 그렇게 뽑으면 칼이 천장에 박힌다.<br><br>
    그것이 다섯 걸음 뒤에 있다.`,
  o:[
    { l:'① 칼을 머리 위가 아니라 앞으로 밀어 뽑는다.', k:'break', dc:22, wake:1,
      ok:`칼자루를 어깨 위로 잡지 않았다. 등 뒤로 손을 돌려 칼집을 옆구리로 내렸다. 칼집 끝을 앞으로 향하게.<br><br>칼집을 뒤로 당기며 칼을 앞으로 밀었다. 뽑는 것과 찌르는 것이 한 번에 됐다. 칼끝이 통로를 일직선으로 갔다. 그것이 뒷걸음질 친다. 칼끝이 그 가슴 앞 한 치에서 섰다.<br><br>칼은 위로 뽑는 것이라고 배웠다. 좁은 데서는 앞으로 뽑는다. 뽑는 길이 바뀌자 칼이 다른 칼이 됐다. 팔이 그 길을 바로 외웠다.`,
      ng:`옆구리로 내리는데 칼자루가 좌석 팔걸이에 걸렸다.<br><br>그것이 그사이 붙었다. 이쪽 손목을 칼자루째 잡는다. 칼을 못 뺀다.<br>손목을 비틀어 빼냈다. 칼은 아직 반쯤 칼집에 있다. 그것은 다른 얼굴로 앞 칸에 들어갔다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, spirit:-14 } },
    { l:'② 뽑지 않고 칼집째 휘두른다.', k:'steady', dc:21,
      ok:`뽑기를 포기했다. 칼을 칼집째 등에서 끌러 두 손으로 들었다. 쇠막대다.<br><br>그것이 붙는 순간 칼집 끝으로 가슴을 밀쳤다. 그것이 좌석 사이에 넘어진다. 일어나려는 어깨를 칼집으로 눌렀다.<br><br>그것의 얼굴이 이쪽 얼굴로 바뀌다 멈췄다. 칼 무게에 눌린 채로는 다 못 바꾼다. 그대로 두고 앞으로 갔다.`,
      ng:`칼집째 휘두르는데 칼집 끝이 선반을 쳤다. 선반 가방들이 쏟아진다.<br><br>가방 사이로 그것이 지나온다. 칼집 위로 손을 뻗어 이쪽 목을 쥔다.<br>무릎으로 밀어내고 빠졌다. 목에 손자국이 남았다. 차다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-16 } }
  ] },

{ at:'B', t:'통로 — 앞뒤로 막혔다',
  x:`통로 앞에 둘. 뒤에 둘. 쫓던 것들이 길을 나눠 왔다.<br><br>
    통로 너비는 칼 길이와 같다. 칼을 가로로 들면 벽에서 벽까지 닿는다.<br>
    칼은 한쪽만 본다. 앞을 보면 뒤가 비고, 뒤를 보면 앞이 빈다.<br><br>
    앞뒤 넷이 동시에 한 걸음 들어온다.`,
  o:[
    { l:'① 칼을 벽에 걸쳐 한쪽을 막는다.', k:'fix', dc:21,
      ok:`칼을 가로로 들어 뒤쪽 통로에 걸쳤다. 칼끝과 칼자루가 양쪽 벽 틈에 박힌다. 칼이 문빗장이 됐다.<br><br>뒤의 둘이 칼에 막혔다. 넘으려 하면 날이다. 앞의 둘에게는 맨손으로 돌아섰다. 동료들과 같이.<br>앞을 뚫고 나서 칼을 뽑으러 돌아갔다. 뒤의 둘이 칼을 사이에 두고 이쪽을 본다. 칼을 뽑자마자 뛰었다.`,
      ng:`걸쳤는데 한쪽 벽 틈이 얕았다. 칼이 미끄러져 떨어졌다.<br><br>뒤의 둘이 칼을 밟고 넘어온다. 맨손으로 앞뒤를 받았다. 팔이 모자라다.<br>동료가 칼을 주워 던져 줬다. 받는 사이 어깨를 맞았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-12 } },
    { l:'② 앞을 베고 돌아선다.', k:'break', dc:22,
      doom:{ title:'등 뒤', what:'뒤에서 붙잡혔습니다', dc:17, sec:50,
        text:`앞의 둘을 벴다. 크게 한 번. 둘이 같이 벽에 부딪혔다.<br><br>돌아서는데 칼이 너무 길다. 통로에서 칼이 돌아서는 데 한 숨이 더 든다.<br>그 한 숨 사이 뒤의 둘이 등에 붙었다. 팔을 잡는다. 칼 든 팔을.<br><br>칼을 놓지 않았다. 대검사는 칼을 놓지 않는다. 그래서 칼째로 끌려간다.`,
        dieText:`통로 바닥에 칼 한 자루가 남았다. 칼은 멀쩡했다.<br><br>칼을 쥐었던 손이 칼과 같이 가지 않았다. 끝까지 쥔 손이 그렇게 됐다.<br>다들 칼을 들고 나왔다. 무거웠다. 한 사람 몫만큼.` },
      ok:`앞의 둘을 벴다. 크게 한 번. 그리고 돌아서지 않았다. 칼자루 끝을 뒤로 내질렀다.<br><br>칼자루 끝 쇠뭉치가 뒤의 첫째 명치에 박혔다. 둘째가 붙기 전에 칼을 몸 앞에서 한 바퀴 돌려 날을 뒤로 보냈다. 둘째가 날 앞에서 멈춘다.<br><br>칼은 한쪽만 보는 줄 알았다. 칼자루도 칼이다. 앞뒤가 다 끝났다.`,
      win:{ exp:22, dream:3 } },
    { l:'③ 무력을 쓴다 — 칼을 눕혀 들고 앞쪽 둘을 밀어낸다.', k:'steady', dc:21, cost:{ might:25 },
      ok:`칼을 가로로 눕혀 두 손으로 들었다. 칼면이 통로를 가득 막는다. 무력을 실어 앞으로 밀었다.<br><br>앞의 둘이 칼면에 밀려 뒷걸음질 친다. 둘이 한꺼번에. 통로 끝 모퉁이까지 밀어붙였다. 동료들이 칼 뒤에 붙어 따라온다. 뒤의 둘은 동료들이 막았다.<br><br>모퉁이에서 칼을 세웠다. 앞의 둘은 모퉁이 너머로 넘어졌다. 길이 열렸다.`,
      ng:`밀었는데 앞의 둘이 칼면을 붙잡고 버틴다. 넷이 칼 하나를 사이에 두고 민다.<br><br>무력이 다 빠지는 사이 등 뒤에서 동료 비명.<br>칼을 놓고 돌아설 수도 없다. 결국 칼을 비틀어 빠졌다. 동료 팔에 피가 흐른다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-14, might:-5 } }
  ] },

{ at:'B1', t:'창고 — 매달린 그물 짐',
  x:`창고 천장 크레인에 그물 짐이 매달렸다. 굵은 쇠줄 하나에.<br><br>
    셔터 쪽에서 우비들이 들어온다. 손전등이 넷. 이쪽은 짐 더미 뒤에 있다.<br>
    쇠줄을 본다. 칼이 닿는 높이다. 쇠줄을 베는 칼은 흔치 않다. 이 칼은 무겁다.<br><br>
    우비들이 짐 밑으로 걸어온다.`,
  o:[
    { l:'① 무력을 쓴다 — 쇠줄을 벤다.', k:'break', dc:22, cost:{ might:24 },
      ok:`짐 더미 위로 올라섰다. 쇠줄이 눈높이다. 무력을 끝까지 모았다.<br><br>우비들이 짐 바로 밑에 왔을 때 그었다. 쇠줄이 터지듯 끊어진다. 그물 짐이 떨어진다. 상자가 쏟아진다. 손전등 둘이 상자 밑에서 꺼졌다.<br><br>칼날을 봤다. 이가 하나 나갔다. 쇠줄을 벤 값으로 싸다.`,
      ng:`그었는데 쇠줄이 반만 끊겼다. 풀린 가닥이 채찍처럼 튀었다.<br><br>쇠 가닥이 뺨을 긋고 갔다. 손전등 넷이 이쪽을 비춘다.<br>남은 반이 그물 무게에 천천히 풀린다. 짐이 떨어질 때 우비들은 이미 비켜 있었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-26, spirit:-14, might:-5 } },
    { l:'② 칼끝으로 그물을 갈라 상자 사이에 숨는다.', k:'hide', dc:21,
      ok:`그물 짐 아래쪽 그물코를 칼끝으로 갈랐다. 상자 몇 개가 미끄러져 바닥에 쌓인다. 그 사이에 사람이 들어갈 틈이 생겼다.<br><br>다들 들어갔다. 이쪽은 칼을 세로로 세워 상자 틈에 끼고 들어갔다. 칼이 제일 숨기 어렵다.<br>손전등이 지나간다. 상자 틈을 비추다 칼자루에서 멈췄다. 상자에 꽂힌 쇠막대로 보였는지 지나갔다.`,
      ng:`그물코를 가르는데 상자가 한꺼번에 쏟아졌다. 쾅.<br><br>손전등이 모인다. 숨을 틈이 아니라 쓰러진 상자 더미만 남았다.<br>더미 뒤로 기어 빠졌다. 칼이 상자에 걸려 끌리는 소리가 났다. 다들 그 소리를 들었다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-22, mind:-14 } }
  ] },

{ at:'B2', t:'병실 — 칼도 세어진다',
  x:`정각이다. 다들 침대 발치에 섰다. 칼은 등에 멨다.<br><br>
    간호사가 계수기를 누르며 온다. 이쪽 앞에서 딸깍. 그리고 이쪽 등 뒤의 칼자루를 본다. 딸깍. 한 번 더.<br>
    칼이 하나로 세어졌다. 사람 하나로.<br><br>
    화이트보드 숫자가 하나 늘 것이다. 늘어난 하나는 다음 정각에 대답해야 한다.`,
  o:[
    { l:'① 칼을 빈 침대에 눕히고 이불을 덮는다.', k:'fix', dc:21,
      ok:`간호사가 지나간 뒤 칼을 풀어 빈 침대에 눕혔다. 이불을 덮었다. 칼자루를 베개에 올렸다. 사람 키만 한 칼이다. 사람 모양이 된다.<br><br>다음 정각에 간호사가 그 침대 앞에서 딸깍 누른다. 이불 속에서 대답이 없다. 간호사가 한참 서 있다가 다음 침대로 간다. 숫자가 맞으면 대답은 상관없나 보다.<br><br>칼을 다시 멨다. 이불에 칼 모양으로 자국이 남았다.`,
      ng:`눕혔는데 이불이 짧다. 칼끝이 침대 발치로 비어져 나왔다.<br><br>다음 정각에 간호사가 그 칼끝을 본다. 계수기를 누르지 않는다. 이쪽을 본다.<br>보호사가 와서 칼을 침대째 끌고 갔다. 찾으러 가는 데 한 층이 걸렸다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-16, spirit:-16 } },
    { l:'② 칼을 등에 바짝 붙이고 몸 뒤로 숨긴다.', k:'hide', dc:21,
      ok:`다음 정각 전에 칼집 끈을 조였다. 칼이 등뼈에 붙는다. 칼자루를 뒤통수 뒤로 숨겼다. 고개를 조금 숙였다.<br><br>딸깍. 이쪽. 간호사 눈이 이쪽 어깨 위를 본다. 칼자루가 안 보인다. 딸깍은 한 번뿐이다.<br><br>화이트보드 숫자가 다시 하나 줄었다. 줄어든 것은 칼이다. 칼은 대답할 필요가 없다.`,
      ng:`조이는데 칼집 끈이 끊어졌다. 칼이 등에서 미끄러져 바닥을 친다.<br><br>쩡. 병실 전체가 울린다. 간호사가 칼을 내려다본다. 딸깍. 딸깍.<br>두 번. 이번엔 칼이 아니라 이쪽이 둘로 세어졌다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-20, spirit:-18 } }
  ] },

{ at:'B3', t:'화물칸 — 짐의 벽',
  x:`화물칸이 짐으로 막혔다. 트렁크, 상자, 포대. 천장까지 밧줄로 묶였다.<br><br>
    앞 칸으로 가려면 이 짐을 지나야 한다. 짐 틈으로 앞 칸 문 유리가 조금 보인다.<br>
    짐의 벽을 본다. 밧줄을 베면 무너진다. 무너진 짐이 길을 더 막을 수도 있다. 사람을 덮칠 수도 있다.<br><br>
    짐 틈 저편에서 누가 이쪽을 본다.`,
  o:[
    { l:'① 밧줄만 베고 칼을 멈춘다.', k:'break', dc:22, wake:1,
      ok:`짐을 묶은 밧줄은 열둘이다. 그중 셋이 문 앞 짐을 묶었다. 그 셋만 골랐다.<br><br>칼을 그었다. 첫째 밧줄. 칼이 트렁크에 닿기 한 치 전에 섰다. 둘째. 셋째. 칼이 매번 같은 자리에서 섰다. 문 앞 짐이 앞으로 무너져 내리고 나머지 벽은 그대로다.<br><br>큰 칼은 끝까지 가야 한다고 믿었다. 가다가 서는 것이 더 어렵다. 그 무게를 한 치 앞에서 세웠다. 팔이 처음으로 칼을 멈추는 힘을 가졌다.`,
      ng:`셋째 밧줄에서 칼이 안 섰다. 넷째까지 갔다.<br><br>짐의 벽 위쪽이 기운다. 트렁크가 떨어진다. 어깨로 받았다. 하나, 둘.<br>길은 났다. 어깨가 안 올라간다. 짐 틈 저편의 눈은 사라졌다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-12 } },
    { l:'② 무력을 쓴다 — 칼을 지렛대로 짐을 통째로 민다.', k:'steady', dc:21, cost:{ might:24 },
      ok:`칼끝을 바닥 짐 밑에 쑤셔 넣었다. 칼자루를 어깨에 걸었다. 무력을 다리에서부터 올렸다.<br><br>짐의 벽 아래쪽이 들린다. 벽 전체가 한 덩이로 옆으로 미끄러진다. 밧줄은 하나도 안 끊겼다. 사람 하나 지날 틈이 났다.<br><br>칼을 빼자 짐이 도로 내려앉았다. 틈은 남았다. 칼날이 조금 휘었다. 휜 걸 손으로 펴 보았다. 안 펴진다.`,
      ng:`들어 올리는데 칼끝이 짐 밑에서 미끄러졌다. 벽이 이쪽으로 기운다.<br><br>무력으로 받쳤다. 다들 빠질 때까지. 그사이 위에서 포대 하나가 떨어져 머리를 쳤다.<br>눈앞이 하얬다가 돌아왔다. 칼은 짐 밑에 반쯤 깔렸다. 뽑는 데 한참.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, spirit:-12, might:-5 } }
  ] },

{ at:'B', t:'쉬는 자리 — 휘두르지 않고 휘두르기',
  x:`잠깐 숨을 데에 들어왔다. 좁다. 칼을 뽑을 수 없다.<br><br>
    대검사는 하루에 칼을 백 번 휘두른다. 휘두르지 않은 날은 팔이 안다. 이틀이면 칼이 안다.<br>
    오늘 백 번을 못 채웠다. 쫓기느라. 내일도 못 채울 것이다.<br><br>
    칼을 무릎 위에 눕혔다. 날이 손바닥 아래에서 차다.`,
  o:[
    { l:'① 눈을 감고 백 번을 벤다.', k:'steady', dc:21, wake:1,
      ok:`칼을 쥐지 않았다. 무릎 위 칼에 손바닥만 얹었다. 눈을 감고 휘둘렀다. 머릿속에서.<br><br>어깨가 움직이지 않는데 어깨가 무겁다. 허리가 돌지 않는데 허리가 뻐근하다. 쉰 번째에 칼 무게가 손바닥에 실렸다. 백 번째에 이마에 땀이 났다.<br><br>눈을 떴다. 칼은 그대로 무릎 위에 있다. 몸은 백 번을 했다. 칼이 없는 데서도 칼을 쓸 수 있다. 이제 하루 백 번은 어디서든 채운다.`,
      ng:`감고 휘두르는데 머릿속 칼이 자꾸 벽에 걸린다. 이 좁은 데가 머릿속까지 들어왔다.<br><br>열 번을 넘기지 못했다. 다시 하면 또 걸린다. 걸릴 때마다 진짜 어깨가 움찔한다.<br>움찔할 때 무릎 위 칼이 벽을 톡 쳤다. 바깥이 조용해졌다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-16, spirit:-14 } },
    { l:'② 날의 이를 손끝으로 센다.', k:'gaze', dc:20,
      ok:`손끝으로 날을 쓸었다. 칼끝에서 칼자루 쪽으로. 이 나간 데가 걸린다. 일곱.<br><br>하나하나 어디서 나갔는지 떠올렸다. 셔터, 사슬, 쇠줄, 문. 오늘 것이 셋이다.<br>이가 몰린 데가 칼 가운데다. 거기만 많이 쓴다. 내일은 칼끝 쪽을 쓰기로 했다.<br><br>날은 이쪽 하루를 기억한다. 손끝이 그걸 읽었다.`,
      ng:`쓸다가 이 나간 데에 손끝이 베였다. 깊게.<br><br>피가 날 홈을 타고 흐른다. 닦는 천이 없다. 소매로 닦았다.<br>손끝이 욱신거린다. 칼을 쥘 때마다 그 손가락이 먼저 운다.`,
      win:{ exp:15, dream:1 }, lose:{ hp:-20, mind:-14 } }
  ] },

{ at:'B', t:'배신 — 칼을 들어 주겠다는 사람',
  x:`낯선 사람이 같이 가자고 붙었다. 친절하다. 이쪽 칼을 보고 무겁겠다고 한다. 잠깐 들어 주겠다고.<br><br>
    손을 내민다. 손이 작다. 이 칼을 들 손이 아니다.<br>
    칼을 남에게 맡긴 적이 없다. 칼을 맡기는 순간 그냥 어깨 넓은 사람이 된다.<br><br>
    뒤에서 쫓는 것들이 온다. 칼이 무거운 건 사실이다.`,
  o:[
    { l:'① 칼을 맡긴다.', k:'luck', dc:21,
      ok:`칼을 맡겼다. 그가 받아 든다. 무릎이 꺾인다. 칼끝이 땅에 떨어진다.<br><br>그는 칼을 들고 뛰지 못했다. 들고 뛰려고 했다. 한 걸음 만에 알았다. 이 칼은 들고 도망칠 수 있는 칼이 아니다.<br>그가 칼을 내려놓고 웃는다. 그리고 혼자 뛴다. 쫓는 것들 쪽으로.<br><br>칼을 다시 멨다. 무거운 칼은 훔쳐 갈 수도 없다. 그게 다행이었다.`,
      ng:`맡겼는데 그가 칼을 들지 않고 칼집 끈만 잡았다. 끈을 칼로 끊었다. 그의 칼로.<br><br>칼이 떨어진다. 그가 칼을 발로 차서 배수구 쪽으로 보낸다. 칼이 배수구 쇠창살에 걸렸다.<br>그는 뛰었다. 칼을 꺼내는 사이 쫓는 것들이 모퉁이를 돌았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-22, spirit:-16 } },
    { l:'② 웃으며 거절한다.', k:'steady', dc:20,
      ok:`괜찮다고 했다. 칼은 등에 있어야 덜 무겁다고.<br><br>그가 웃는다. 그럼 앞장서겠다고 한다. 그가 앞장서고 이쪽은 칼을 메고 따라갔다.<br>세 번째 모퉁이에서 그가 갑자기 비켰다. 그 너머에 쫓는 것들이 있다. 칼은 이미 손에 있었다. 등에서 뽑을 필요가 없었다.<br><br>남이 친절하면 칼을 미리 쥔다. 큰 칼을 멘 사람의 셈이다.`,
      ng:`거절했다. 그가 웃는다. 앞장서겠다고 한다.<br><br>모퉁이에서 그가 비켰다. 그 너머에 쫓는 것들. 칼은 아직 등에 있다.<br>뽑는 한 숨이 늦었다. 칼자루를 잡은 팔을 몽둥이가 쳤다.`,
      win:{ exp:16, dream:1 }, lose:{ hp:-28, mind:-12 } },
    { l:'③ 칼은 두고 빈 칼집만 맡긴다.', k:'fix', dc:21,
      ok:`칼을 뽑아 손에 들었다. 빈 칼집만 그에게 줬다. 이거라도 들어 달라고.<br><br>그가 칼집을 받는다. 가볍다. 실망한 얼굴. 그래도 받았다.<br>세 번째 모퉁이에서 그가 칼집을 들고 뛰었다. 쫓는 것들 쪽으로. 빈 칼집을 들고.<br><br>저쪽에서 칼집을 받은 것들이 웃는 소리가 났다. 이쪽은 칼을 들고 반대로 갔다.`,
      ng:`칼집을 받은 그가 칼집으로 이쪽 손목을 쳤다. 쇠로 감은 칼집이다.<br><br>칼을 놓쳤다. 그가 칼집을 들고 뛴다.<br>칼을 주웠다. 칼집이 없다. 이제 칼날을 등에 멜 수 없다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-14 } }
  ] },

{ at:'B1', t:'냉동 창고 — 비닐에 싼 것',
  x:`냉동 창고 안쪽 갈고리에 큰 것이 매달려 있다. 두꺼운 비닐로 쌌다. 사람 키만 하다.<br><br>
    비닐에 서리가 끼어 안이 안 보인다. 바닥에 굵은 소금이 쏟아져 있다.<br>
    칼을 뽑았다. 베면 무엇인지 알 것이다. 베고 나서 알면 늦을 수도 있다.<br><br>
    비닐 안에서 무언가 손톱으로 긁는 소리가 났다. 한 번.`,
  o:[
    { l:'① 비닐째 벤다.', k:'break', dc:21,
      ok:`칼을 크게 들어 비닐째 그었다. 언 것은 잘 갈린다. 소리가 맑다.<br><br>비닐이 갈라진다. 안에 언 생선이 가득하다. 큰 것 작은 것. 그 사이에 손가락 크기의 갈고리 하나가 끼어 있다. 긁는 소리는 그게 비닐을 긁은 것이었다.<br><br>생선 더미 밑에서 소금 덩이를 집었다. 칼날에 서리가 붙었다. 털어도 안 떨어진다.`,
      ng:`그었는데 비닐이 질기다. 칼이 비닐에 감겨 미끄러졌다.<br><br>매달린 것이 흔들린다. 갈고리째 이쪽으로 돌아온다. 무겁다. 가슴을 쳤다.<br>뒤로 넘어졌다. 바닥 소금이 등에 박힌다. 매달린 것은 계속 흔들린다. 긁는 소리가 이번엔 여러 번.`,
      win:{ exp:18, dream:2, item:'소금 덩이' }, lose:{ hp:-28, spirit:-14 } },
    { l:'② 칼끝으로 비닐 한 겹만 가른다.', k:'gaze', dc:22, wake:1,
      ok:`칼을 크게 들지 않았다. 칼끝만 비닐에 댔다. 사람 키만 한 칼의 끝 한 치. 비닐 한 겹 두께만 밀었다.<br><br>비닐이 한 줄로 벌어진다. 안쪽 것은 칼끝이 안 닿았다. 들여다봤다. 사람이다. 숨을 쉰다. 입이 테이프로 막혔다. 눈이 이쪽을 본다.<br>칼끝으로 테이프만 갈랐다. 그 사람이 숨을 몰아쉰다. 해무호에 실릴 짐이었다고 한다. 다섯 중 하나로.<br><br>무거운 칼일수록 끝은 가볍게 쓸 수 있다. 칼끝 한 치가 손끝이 됐다. 이 칼로 실 한 오라기도 가를 수 있다.`,
      ng:`칼끝을 댔는데 손이 언 채로 떨렸다. 두 겹이 갈렸다.<br><br>안에서 신음이 났다. 비닐 틈으로 붉은 것이 번진다. 칼끝이 닿았다.<br>칼을 거두고 비닐을 손으로 찢었다. 안의 사람이 이쪽을 본다. 이쪽 칼을 본다. 무서워서 눈을 감는다.`,
      win:{ exp:22, dream:2 }, lose:{ mind:-18, spirit:-18 } }
  ] },

{ at:'B2', t:'세탁실 — 널린 시트',
  x:`세탁실 빨랫줄에 흰 시트가 줄줄이 걸렸다. 건조기 바람에 흔들린다.<br><br>
    시트 너머에 사람 그림자가 여럿 비친다. 서 있는 것, 앉은 것. 환자인지 직원인지 모른다.<br>
    칼을 뽑았다. 시트째 베면 길이 난다. 시트 뒤에 누가 있는지는 베고 나서 안다.<br><br>
    그림자 하나가 시트 너머에서 이쪽으로 손을 뻗는다.`,
  o:[
    { l:'① 손 뻗은 그림자의 시트를 벤다.', k:'break', dc:21,
      ok:`그림자가 손을 뻗은 높이를 봤다. 어깨 높이. 칼을 그보다 아래로 그었다. 발목 높이로.<br><br>시트가 아래에서부터 갈라진다. 그림자가 넘어진다. 직원 옷이다. 넘어지면서 손에 쥔 주사기를 놓쳤다.<br>다른 그림자들은 움직이지 않는다. 시트 너머로 보니 다 빨래 바구니에 걸쳐 둔 환자복이다. 사람은 하나였다.<br><br>갈라진 시트 사이로 지나갔다. 직원은 발목을 쥐고 소리를 안 낸다.`,
      ng:`그었는데 시트 뒤에 아무도 없었다. 그림자는 다른 시트에 비친 것이었다.<br><br>진짜 손은 옆에서 왔다. 시트 두 장 사이로. 목덜미에 따끔.<br>칼로 그 시트를 마저 갈랐다. 직원이 넘어진다. 그사이 다리가 풀렸다. 시트를 붙잡고 겨우 섰다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-16 } },
    { l:'② 칼끝으로 시트를 하나씩 들춘다.', k:'gaze', dc:21,
      ok:`베지 않았다. 칼끝으로 시트 귀퉁이를 하나씩 들어 올렸다.<br><br>첫째 뒤에는 바구니. 둘째 뒤에는 환자 하나가 서서 자고 있다. 셋째 뒤에 직원. 주사기를 쥐었다. 들킨 줄 알고 뛴다.<br>환자를 깨웠다. 환자가 눈을 비비며 세탁물 통로를 가리킨다. 거기로 가면 된다고.<br><br>칼을 들어 올리는 것만으로 다 봤다. 베는 건 그다음이었다. 필요 없었다.`,
      ng:`들추는데 시트가 칼끝에 감겼다. 줄이 끊어지며 시트 셋이 한꺼번에 떨어진다.<br><br>시트 밑에서 무언가 이쪽 발목을 잡았다. 시트째로.<br>칼로 시트를 갈라 겨우 뺐다. 발목에 손가락 자국. 시트 밑에는 아무도 없다.`,
      win:{ exp:16, dream:1 }, lose:{ mind:-16, spirit:-18 } }
  ] },

{ at:'B3', t:'침대칸 — 칼이 안 들어가는 칸',
  x:`침대칸 한 칸 안으로 끌려 들어왔다. 문이 닫혔다. 이층 침대 둘 사이, 한 사람 너비.<br><br>
    칼은 등에 있다. 여기서는 뽑을 수도 없다. 뽑아도 휘두를 데가 없다.<br>
    상대가 이쪽 얼굴을 하고 있다. 이쪽보다 조금 웃는 얼굴로.<br><br>
    상대 손에 짧은 칼이 있다. 이 칸에 맞는 칼이다.`,
  o:[
    { l:'① 칼을 반만 뽑아 날 가운데를 쥐고 쓴다.', k:'break', dc:22, wake:1,
      ok:`칼을 반만 뽑았다. 그리고 왼손으로 날 가운데를 쥐었다. 장갑 위로. 칼이 반 길이가 됐다. 칼자루와 날 가운데, 두 손으로 쥔 짧은 창.<br><br>상대의 짧은 칼을 날 가운데로 받았다. 받은 채로 밀었다. 칼끝이 상대 어깨에 들어간다. 상대 얼굴이 이쪽 얼굴에서 다른 얼굴로 흩어진다.<br><br>날을 쥐면 손이 베일 줄 알았다. 베는 쪽으로만 안 밀면 날도 손잡이다. 긴 칼이 짧아졌다. 칼 길이를 손으로 고를 수 있다.`,
      ng:`날 가운데를 쥐는데 장갑이 젖어 미끄러졌다. 손바닥이 날에 쓸렸다.<br><br>짧은 칼이 그사이 들어왔다. 옆구리. 얕다.<br>무릎으로 밀어내고 문을 차고 굴러 나왔다. 손바닥과 옆구리에서 같이 피가 난다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-32, spirit:-12 } },
    { l:'② 칼을 내려놓고 맨손으로 붙는다.', k:'steady', dc:21,
      ok:`칼을 등에서 풀어 침대 위로 밀어 넣었다. 맨손이 됐다. 어깨 넓은 사람이 됐다. 이 칸에서는 그게 낫다.<br><br>상대 칼 든 손목을 잡아 침대 기둥에 쳤다. 칼이 떨어진다. 어깨로 밀어 문에 붙였다. 상대가 문과 이쪽 사이에 낀다. 숨을 못 쉰다.<br><br>상대 얼굴이 바뀌다 말고 멈췄다. 숨이 모자라면 얼굴도 못 바꾸나 보다. 칼을 다시 메고 나왔다.`,
      ng:`칼을 풀어 놓는 사이 상대가 들어왔다. 짧은 칼이 팔뚝을 긋는다.<br><br>맨손으로 붙었다. 상대가 이쪽 얼굴로 웃으며 이쪽 수를 그대로 쓴다. 같은 손목, 같은 어깨.<br>둘이 같이 문에 부딪혀 통로로 쏟아졌다. 일행이 둘 중 누구를 잡아야 할지 몰라 멈췄다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-14 } }
  ] },

{ at:'B', t:'네온 아래 — 칼에 비친 얼굴',
  x:`창으로 든 네온 빛이 떤다. 붉은 빛이 칼날에 번진다.<br><br>
    이 칼은 넓다. 날이 거울만 하다. 걸으면서 칼을 조금 기울이면 등 뒤가 비친다.<br>
    등 뒤에 누가 있다. 젖은 우산을 들었다. 칼날 속에서 한 걸음씩 커진다.<br><br>
    돌아보면 없을 것이다. 이런 건 돌아보면 없다.`,
  o:[
    { l:'① 칼날을 거울로 쓰며 거리를 잰다.', k:'gaze', dc:21,
      ok:`돌아보지 않았다. 칼을 조금씩 기울이며 걸었다. 우산이 칼날 속에서 커진다. 세 걸음. 두 걸음.<br><br>한 걸음 반에서 우산이 접힌다. 접힌 우산 끝이 쇠다. 뾰족하다. 등을 노린다.<br>그 순간 칼을 등 뒤로 넘겨 세웠다. 칼면이 등을 막는다. 쇠끝이 칼면에 부딪혀 튄다. 그제야 돌아섰다. 아무도 없다.<br><br>칼면에 긁힌 자국이 한 줄 새로 생겼다. 등은 멀쩡하다.`,
      ng:`기울이는데 네온 빛이 칼날에 번져 아무것도 안 보인다. 붉기만 하다.<br><br>우산이 어디 있는지 놓쳤다. 등이 따끔했다. 쇠끝이 외투를 뚫고 살갗에 닿았다 빠졌다.<br>돌아섰다. 없다. 등에 동그란 구멍 하나.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-16 } },
    { l:'② 돌며 크게 벤다.', k:'break', dc:21,
      ok:`돌지 않고 걷다가 한 번에 돌았다. 칼이 몸을 따라 크게 한 바퀴.<br><br>칼끝에 무언가 걸렸다. 천. 우산살. 찢긴 우산이 날아간다. 우산 든 사람은 이미 한 걸음 물러나 있다. 얼굴은 모자 그늘이다.<br><br>둘이 서로를 본다. 그가 먼저 등을 돌려 어둠 속으로 간다. 찢긴 우산은 바닥에 남았다. 손잡이가 아직 따뜻하다. 오래 쥐고 있던 손이다.`,
      ng:`도는데 칼끝이 기둥에 걸렸다. 칼이 멈추고 몸만 돈다.<br><br>손목이 꺾였다. 우산 든 사람이 그 틈에 지나갔다. 옆을 스치며 귀에 대고 무어라 속삭인다. 빗소리에 묻혔다.<br>칼을 기둥에서 뽑았다. 손목이 붓는다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'B1', t:'방파제 — 청소부',
  x:`방파제 위에 청소부가 서 있다. 우비에 장화. 쇠 자루 대걸레. 자루 끝에 갈고리.<br><br>
    청소부 뒤로 바다가 검다. 해무호 불빛이 멀리서 다가온다. 시간이 거의 없다.<br>
    이쪽 칼은 길다. 청소부의 자루도 길다. 둘 다 긴 것을 들었다.<br><br>
    청소부가 양동이를 내려놓는다. 바닥을 닦을 준비를 한다.`,
  o:[
    { l:'① 정면으로 들어가 벤다.', k:'break', dc:22,
      doom:{ title:'방파제의 청소', what:'갈고리에 걸려 바다로 끌려갑니다', dc:18, sec:45,
        text:`칼을 높이 들고 들어갔다. 크게 내리쳤다.<br><br>청소부가 자루로 받지 않았다. 비켰다. 칼이 방파제 시멘트를 쳤다. 손이 울린다.<br>그 한 숨에 갈고리가 칼자루와 손목 사이에 걸렸다. 청소부가 당긴다. 방파제 끝으로.<br><br>칼을 놓으면 손목이 빠진다. 손은 칼을 놓지 않는다.`,
        dieText:`청소부는 방파제를 닦았다. 꼼꼼하게.<br><br>해무호가 5시 10분에 들어왔다. 방파제 끝 물속에 무언가 길쭉한 것이 꽂혀 있는 걸 갑판원 하나가 봤다. 칼자루 같았다.<br>배가 지나가자 물결이 그것을 덮었다.` },
      ok:`높이 들지 않았다. 칼을 낮게 들고 들어갔다. 청소부 자루와 같은 높이로.<br><br>자루가 온다. 칼면으로 받아 흘렸다. 갈고리가 칼면을 미끄러져 허공을 긁는다. 그 길이 끝나는 데에서 칼을 돌려 자루를 쳤다. 쇠 자루가 반으로 꺾였다.<br><br>청소부가 꺾인 자루를 내려다본다. 양동이를 들고 돌아선다. 아무 말 없이. 일이 끝나지 않았다는 듯이.`,
      win:{ exp:25, dream:3 } },
    { l:'② 칼을 시멘트에 꽂고 그 뒤에서 버틴다.', k:'steady', dc:21,
      ok:`칼을 방파제 시멘트 틈에 꽂았다. 칼자루를 두 손으로 잡았다. 칼이 벽이 됐다.<br><br>갈고리가 칼 양옆을 노린다. 칼자루를 돌려 칼면으로 막았다. 몇 번이고. 청소부가 지친 게 아니라 시간이 다 됐다. 해무호 고동이 운다.<br><br>청소부가 고동 소리에 고개를 든다. 대걸레를 거둔다. 시간이 되면 일을 멈추는 사람이다. 그 사이 다들 방파제를 내려왔다.`,
      ng:`꽂은 틈이 얕았다. 갈고리가 칼날에 걸려 칼을 뽑아 넘겼다.<br><br>칼이 방파제 위를 미끄러진다. 쫓아가 잡는 사이 갈고리가 어깨에 걸렸다.<br>외투째 찢고 빠졌다. 어깨에서 피가 빗물에 섞인다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-14 } },
    { l:'③ 무력을 쓴다 — 갈고리 자루째 벤다.', k:'break', dc:22, cost:{ might:26 },
      ok:`청소부가 자루를 휘두르는 순간 칼을 옆으로 그었다. 무력을 끝까지 실어서. 사람이 아니라 자루를.<br><br>쇠가 갈린다. 갈고리 달린 끝이 빗속으로 날아가 바다에 떨어진다. 청소부 손에 짧은 쇠막대만 남았다.<br><br>청소부가 쇠막대를 본다. 양동이를 본다. 그리고 쇠막대로 양동이를 들어 올리고 간다. 다른 갈고리를 가지러.`,
      ng:`그었는데 자루가 아니라 갈고리에 칼이 걸렸다. 쇠와 쇠가 물렸다.<br><br>청소부가 비튼다. 칼이 손에서 돌아간다. 무력이 빠지는 게 느껴진다.<br>칼을 겨우 빼냈다. 날에 갈고리 자국이 깊게 패었다. 손목이 시큰하다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-26, mind:-14, might:-5 } }
  ] },

{ at:'B2', t:'병실 — 침대 밑의 손',
  x:`병실 침대 밑에서 손이 나와 일행 발목을 잡았다. 일행이 넘어졌다. 끌려간다. 침대 밑으로.<br><br>
    침대 밑은 어둡다. 손 하나가 아니다. 손 여럿이 일행 다리를 하나씩 잡는다.<br>
    칼을 뽑았다. 침대 밑을 베려면 침대를 베어야 한다.<br><br>
    일행 무릎이 이미 침대 밑으로 들어갔다.`,
  o:[
    { l:'① 칼을 침대 판째 내리꽂는다.', k:'break', dc:22,
      ok:`일행 다리 바로 옆 침대 판에 칼끝을 내리꽂았다. 칼이 매트리스와 판을 뚫고 바닥까지 간다.<br><br>침대 밑에서 무언가 째지는 소리. 손들이 한꺼번에 일행 다리를 놓는다. 일행을 끌어냈다.<br>칼을 뽑았다. 칼끝에 아무것도 안 묻었다. 침대 밑을 들여다봤다. 빈 바닥이다. 바닥에 손톱자국만 빽빽하다.<br><br>그날 밤 그 침대 숫자는 비었다. 아무도 채우지 못했다.`,
      ng:`꽂았는데 침대 판 밑 쇠틀에 칼끝이 막혔다. 바닥까지 안 간다.<br><br>손들이 놓지 않는다. 일행 허리까지 들어간다. 칼을 버리고 일행 팔을 잡아 당겼다.<br>끌어냈다. 일행 신발 둘은 침대 밑에 남았다. 다리에 손 자국이 수십 개.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-24, spirit:-18 } },
    { l:'② 무력을 쓴다 — 침대를 들어 엎는다.', k:'steady', dc:21, cost:{ might:22 },
      ok:`칼을 내려놓았다. 침대 머리 쪽 쇠틀을 두 손으로 잡았다. 무력을 끌어올려 들었다.<br><br>침대가 통째로 들린다. 그리고 뒤로 넘어간다. 침대 밑이 드러났다. 불빛이 들자 손들이 바닥 틈으로 빨려 들어간다. 바닥 타일 사이로. 손가락 끝까지.<br><br>일행이 바닥에 누운 채 이쪽을 본다. 일어나지 못한다. 다리가 떨려서.`,
      ng:`들었는데 침대 반대쪽에서 누가 누른다. 침대 밑에서.<br><br>무력이 다 나간다. 침대가 반만 들렸다 내려온다. 일행 다리 위로.<br>다시 들어 끌어냈다. 일행이 다리를 절며 일어난다. 이쪽 허리가 끊어질 것 같다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-28, mind:-12, might:-5 } }
  ] },

{ at:'B3', t:'연결 통로 — 떨어져 나가는 객차',
  x:`연결 통로에 섰는데 발밑에서 쇠 빠지는 소리가 났다. 핀이다. 누가 뽑았다.<br><br>
    뒤 칸이 조금씩 멀어진다. 철판 두 장 사이가 벌어진다. 한 뼘. 두 뼘. 일행 하나가 아직 뒤 칸에 있다.<br>
    앞 칸 유리 너머에서 그것이 손을 흔든다. 뽑은 핀을 들고.<br><br>
    칼은 벌어지는 틈보다 길다. 아직은.`,
  o:[
    { l:'① 칼을 두 칸 사이에 걸고 붙잡아 버틴다.', k:'steady', dc:22,
      doom:{ title:'벌어지는 틈', what:'떨어져 나가는 객차와 함께 끌려갑니다', dc:18, sec:45,
        text:`칼을 두 칸 연결 고리에 걸쳐 끼웠다. 칼자루를 잡고 버텼다. 벌어지는 게 멈춘다.<br><br>일행이 뒤 칸에서 뛰어 건너온다. 됐다. 칼을 빼려는데 안 빠진다. 고리에 물렸다.<br>뒤 칸이 다시 당긴다. 칼이 당겨진다. 칼을 놓으면 산다.<br><br>대검사는 칼을 놓지 않는다. 손이 그렇게 배웠다. 발이 철판 끝에서 미끄러진다.`,
        dieText:`앞 칸은 서지 않고 달렸다. 뒤 칸은 어둠 속에서 천천히 섰다.<br><br>연결 통로 철판 끝에 손바닥 자국 둘이 남았다.<br>방송이 다음 역을 부른다. 한 칸 줄어든 열차가 그 역을 지나간다.` },
      ok:`칼을 두 칸 연결 고리에 걸쳐 끼웠다. 칼자루를 어깨로 받치고 버텼다. 벌어지던 틈이 멈춘다.<br><br>일행이 뒤 칸에서 뛰어 건너온다. 이쪽 등을 밟고. 됐다. 칼을 비틀어 고리에서 뺐다. 빠지는 순간 뒤 칸이 쑥 멀어진다.<br><br>칼날 가운데에 고리 자국이 깊게 패었다. 일행은 다섯이다. 맞다.`,
      win:{ exp:25, dream:3 } },
    { l:'② 뒤 칸으로 뛰어가 일행을 업고 건넌다.', k:'evade', dc:21,
      ok:`벌어지는 틈을 넘어 뒤 칸으로 갔다. 일행 허리를 잡아 어깨에 올렸다. 칼까지 셋의 무게.<br><br>돌아섰다. 틈이 세 뼘이다. 뛰었다. 앞 칸 철판 끝에 한 발이 걸렸다. 무게가 뒤로 쏠린다. 일행을 앞으로 던지고 철판 끝을 손으로 잡았다.<br><br>일행이 이쪽 손목을 잡아 끌어올렸다. 뒤 칸이 어둠 속으로 멀어진다. 그것이 앞 칸 유리 너머에서 손을 내린다.`,
      ng:`업고 뛰었는데 틈이 생각보다 빨리 벌어졌다. 발이 허공을 밟는다.<br><br>일행은 앞으로 던졌다. 이쪽은 철판 끝에 팔꿈치로 걸렸다. 다리가 선로 위에 떠 있다.<br>끌려 올라오는 사이 정강이가 철판 모서리에 갈렸다. 칼집 끝이 선로에 부딪혀 불꽃이 튀었다.`,
      win:{ exp:20, dream:2 }, lose:{ hp:-32, mind:-12 } }
  ] },

{ at:'B', t:'쉬는 자리 — 칼날의 이',
  x:`쉴 데에 앉아 칼을 봤다. 오늘 이가 셋 더 나갔다. 셔터, 쇠줄, 문.<br><br>
    칼을 닦고 싶다. 칼을 닦아야 하루가 끝난다. 쇠에 천이 닿는 소리는 생각보다 크다.<br>
    밖에서 발소리가 지나간다. 천천히. 들으면서.<br><br>
    날 홈에 빗물과 다른 것이 섞여 말라 붙었다.`,
  o:[
    { l:'① 소리 없이 손바닥으로 닦는다.', k:'fix', dc:20,
      ok:`천을 쓰지 않았다. 손바닥에 침을 묻혀 날의 면을 쓸었다. 날 쪽은 안 닿게. 살갗이 쇠를 쓸면 소리가 안 난다.<br><br>천천히. 칼끝에서 칼자루까지. 손바닥이 까매진다. 칼이 조금 밝아진다.<br>발소리가 지나갔다. 다 닦지는 못했다. 그래도 하루가 끝났다.`,
      ng:`손바닥으로 쓸다가 이 나간 데에 걸렸다. 손바닥이 갈렸다.<br><br>피가 날에 번진다. 닦으려던 것에 이쪽 피가 더해졌다.<br>발소리가 멈췄다. 피 냄새를 맡은 것 같다. 한참 뒤에 갔다.`,
      win:{ exp:14, dream:1, hp:6 }, lose:{ hp:-20, spirit:-14 } },
    { l:'② 이 나간 데를 손끝으로 갈아 세운다.', k:'break', dc:21,
      ok:`숫돌이 없다. 벽 돌을 골랐다. 결 고운 것. 이 나간 데 양옆만 아주 조금씩 갈았다. 소리 안 나게 손톱만큼씩.<br><br>나간 이가 메워지지는 않는다. 양옆이 섰다. 날이 다시 걸린다.<br>새벽까지 셋 중 둘을 세웠다. 하나는 그대로 두었다. 오늘을 기억하라고.`,
      ng:`갈다가 돌이 부서졌다. 돌가루가 날에 박힌다.<br><br>돌 부서지는 소리가 밖으로 갔다. 발소리가 다가온다.<br>칼을 무릎에 안고 숨을 죽였다. 날에 돌가루가 박힌 채로. 내일 그 날로 벤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-16, spirit:-14 } }
  ] },

{ at:'B', t:'마지막 문 — 칼 한 번',
  x:`나가는 문이다. 두꺼운 나무 문에 쇠띠를 둘렀다. 빗장은 바깥에 있다.<br><br>
    뒤에서 쫓는 것들이 온다. 시계는 마지막 칸 앞이다.<br>
    칼을 뽑았다. 이 문을 한 번에 가르면 나간다. 한 번에 못 가르면 칼이 문에 박힌다.<br><br>
    대검사는 칼을 놓지 않는다. 박힌 칼을 놓지 않으면 문 앞에 남는다.`,
  o:[
    { l:'① 무력을 다 실어 쇠띠 사이 나무만 벤다.', k:'break', dc:22, cost:{ might:30 }, wake:1,
      ok:`문을 봤다. 쇠띠가 셋. 쇠띠와 쇠띠 사이 나무가 두 뼘씩. 쇠를 벨 필요가 없다. 나무만 베면 된다.<br><br>무력을 남김없이 모았다. 칼을 쇠띠 사이 틈에 맞춰 내리쳤다. 쇠에 닿기 전에 나무만 가르고 나왔다. 한 번 더. 문 가운데가 사각으로 빠졌다.<br>다들 그 구멍으로 빠져나갔다. 마지막으로 이쪽이 칼을 들고 나왔다.<br><br>칼은 큰 것을 크게 베는 줄 알았다. 큰 것 안에서 벨 데만 골라 베었다. 같은 무게가 더 좁은 길로 갔다. 이제 막힌 것이 막힌 것으로 안 보인다. 틈으로 보인다.`,
      ng:`첫 칼은 나무를 갈랐다. 둘째 칼이 쇠띠에 걸렸다. 박혔다.<br><br>무력이 다 나갔다. 칼이 안 빠진다. 발소리가 등 뒤에 닿는다.<br>동료들이 구멍 반쪽으로 빠져나간다. 이쪽은 칼을 비틀어 겨우 뺐다. 빼는 사이 등을 맞았다.`,
      win:{ exp:25, dream:3 }, lose:{ hp:-32, spirit:-14, might:-5 } },
    { l:'② 문틈에 칼을 넣어 빗장을 들어 올린다.', k:'fix', dc:21,
      ok:`문과 문틀 틈으로 칼끝을 넣었다. 칼이 얇아서 들어간다. 바깥 빗장 밑에 칼끝이 닿는다.<br><br>칼을 지렛대로 젖혔다. 빗장이 위로 들린다. 걸쇠에서 빠졌다. 문이 바깥으로 밀린다.<br>칼을 빼고 다들 나갔다. 칼끝이 조금 휘었다. 휜 칼끝을 빗속에서 손으로 펴 봤다. 반쯤 펴졌다.`,
      ng:`칼끝이 빗장에 닿았는데 빗장이 너무 무겁다. 칼이 휘기 시작한다.<br><br>칼을 놓을 수도 더 휠 수도 없다. 그대로 버텼다.<br>바깥에서 누가 빗장을 들어 줬다. 일행 중 하나가 창으로 먼저 나가 있었다. 칼은 활처럼 휘었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-16 } },
    { l:'③ 뒤에 남아 칼을 세운다.', k:'steady', dc:22,
      doom:{ title:'세운 칼', what:'쫓아온 것들에게 붙잡혔습니다', dc:18, sec:45,
        text:`동료들에게 문을 맡기고 돌아섰다. 칼을 가로로 들었다. 통로가 칼 길이만큼 막힌다.<br><br>첫째가 칼에 막힌다. 둘째도. 셋째가 칼 위로 넘어온다. 넷째가 칼 밑으로.<br>칼은 넓어도 한 줄이다. 줄은 넘으면 그만이다.<br><br>칼자루를 쥔 손을 잡혔다. 칼을 놓지 않았다.`,
        dieText:`문은 열렸다. 다들 빗속으로 나갔다.<br><br>통로에 칼 한 자루가 가로로 남았다. 벽에서 벽까지. 그 너머로는 아무것도 나오지 않았다.<br>칼을 쥔 사람은 칼 이쪽에 없었다.` },
      ok:`동료들에게 문을 맡기고 돌아섰다. 칼을 가로로 들었다. 칼끝과 칼자루를 양쪽 벽 틈에 박았다.<br><br>칼이 빗장이 됐다. 쫓는 것들이 칼에 막힌다. 넘으려 하면 칼자루를 비틀어 날을 세웠다. 등 뒤에서 문 열리는 소리.<br>칼을 벽에서 뽑으며 뒤로 뛰었다. 빗속으로.<br><br>칼을 막대로 쓴 날은 칼이 운다. 오늘은 칼이 조용하다.`,
      win:{ exp:25, dream:4 } }
  ] },

{ at:'B', t:'막다른 데 — 낮은 천장',
  x:`막다른 데로 몰렸다. 천장이 낮다. 손을 들면 닿는다. 배관이 지나간다.<br><br>
    큰 칼은 위로 들어 내리친다. 여기서 들면 칼이 배관에 박힌다.<br>
    쫓아온 것들이 그걸 안다. 천천히 다가온다. 셋.<br><br>
    칼을 들 수 없으면 칼 든 짐꾼이다.`,
  o:[
    { l:'① 위에서 아래가 아니라 아래에서 위로 올려 벤다.', k:'break', dc:22, wake:1,
      ok:`칼끝을 바닥에 내렸다. 칼을 끌듯이 뒤로 뺐다. 첫째가 들어온다.<br><br>바닥에서 위로 올려 그었다. 칼이 천장에 닿기 전에 첫째를 지나간다. 무게가 위로 가니 칼이 느리다. 느려서 정확하다. 둘째도 같은 길로. 셋째는 오지 않았다.<br><br>칼은 떨어뜨리는 무게로 베는 줄 알았다. 들어 올리는 무게로도 벤다. 천장이 낮으면 바닥에서 시작한다. 칼이 시작하는 자리가 하나 더 생겼다.`,
      ng:`올려 벴는데 칼끝이 바닥 틈에 걸렸다. 칼이 멈칫한다.<br><br>그 한 숨에 첫째가 칼을 밟았다. 칼이 바닥에 눌린다. 둘째가 들어온다.<br>칼을 놓고 맨손으로 받았다. 머리를 배관에 찧었다. 눈앞이 하얗다.`,
      win:{ exp:22, dream:2 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 칼을 가로로 들고 셋을 밀어낸다.', k:'steady', dc:21,
      ok:`칼을 가슴 높이로 가로로 들었다. 칼면이 통로를 가득 채운다.<br><br>앞으로 걸었다. 셋이 칼면에 밀려 뒷걸음질 친다. 한 걸음씩. 천장이 낮아도 가로는 넓다.<br>통로가 넓어지는 데까지 밀어냈다. 거기서 칼을 세웠다. 셋이 흩어진다. 다들 그 사이로 뛰었다.`,
      ng:`밀었는데 셋이 칼면에 매달렸다. 무게가 칼 끝으로 쏠린다.<br><br>칼이 기울며 배관을 쳤다. 배관이 터져 뜨거운 김이 쏟아진다. 셋도 이쪽도 같이 덴다.<br>김 속에서 칼을 끌고 빠져나왔다. 팔에 물집이 잡혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-12 } }
  ] }

]);
